function getGlossaryDefinition(term) {
  const entry = glosario[term];
  if (typeof entry === 'string') return entry;
  if (entry && typeof entry === 'object') return entry.secundaria || entry.definicion || entry.basico || '';
  return '';
}

function getGlossaryLearningEntry(term, tags = []) {
  const key = normalizeForSearch(term);
  const base = getGlossaryDefinition(term);
  const override = GLOSSARY_LEVEL_OVERRIDES[key] || {};
  const primaryTag = tags.find(tag => tag !== 'all') || classifyGlossaryTerm(term, base)[0] || 'filogenia';
  const template = GLOSSARY_LEVEL_TEMPLATES[primaryTag] || GLOSSARY_LEVEL_TEMPLATES.filogenia;
  return {
    secundaria: override.secundaria || base,
    bachillerato: override.bachillerato || template.bachillerato,
    avanzado: override.avanzado || template.avanzado,
    ejemplo: override.ejemplo || template.ejemplo
  };
}

