function handleSpeciesOpenControls(e) {
  const trigger = e.target.closest?.('[data-open-species]');
  if (!trigger) return;
  e.preventDefault();
  e.stopImmediatePropagation();
  if (e.type === 'click' && Date.now() - _speciesOpenPointerAt < 500) return;
  if (e.type === 'pointerdown') _speciesOpenPointerAt = Date.now();
  const sp = DB_INDEX[trigger.dataset.openSpecies];
  if (!sp) return;
  document.body.dataset.pbCoreControl = 'species:' + sp.id;
  const matrixModal = document.getElementById('matrixModal');
  if (matrixModal?.classList.contains('active')) {
    toggleModal('matrixModal');
    setTimeout(function(){ showDetail(sp); }, 180);
  } else {
    showDetail(sp);
  }
}
window.addEventListener('pointerdown', handleSpeciesOpenControls, true);
