let _canonicalPointerTarget = null;
let _canonicalPointerAt = 0;
function isFinalFloatingControl(trigger) {
  return Boolean(window.PaleoBotV88FloatingMenuFinal && trigger?.closest?.(
    '.fab-group,#pb-a11y-toolbar-root,.scroll-top-btn,#pb-mobile-tools-toggle'
  ));
}
function handleCanonicalPointerControl(e) {
  const trigger = e.target.closest?.(INTERACTIVE_BUTTON_CONTRACTS.join(','));
  if (!trigger) return;
  if (isFinalFloatingControl(trigger)) return;
  _canonicalPointerTarget = null;
  handleCoreDelegatedClick(e);
  if (e.defaultPrevented) {
    _canonicalPointerTarget = trigger;
    _canonicalPointerAt = Date.now();
    e.stopImmediatePropagation();
  }
}
window.addEventListener('pointerdown', handleCanonicalPointerControl, true);

// Puente registrado antes de los reparadores especializados. El dispatcher
// canónico se asigna al terminar de declarar el router completo.
window.addEventListener('click', function(e) {
  const pointerTarget = e.target.closest?.(INTERACTIVE_BUTTON_CONTRACTS.join(','));
  if (pointerTarget && isFinalFloatingControl(pointerTarget)) return;
  if (pointerTarget && pointerTarget === _canonicalPointerTarget && Date.now() - _canonicalPointerAt < 500) {
    e.preventDefault();
    e.stopImmediatePropagation();
    return;
  }
  const dispatch = typeof window.PaleoBotCoreDispatch === 'function'
    ? window.PaleoBotCoreDispatch
    : handleCoreDelegatedClick;
  dispatch(e);
  if (e.defaultPrevented) e.stopImmediatePropagation();
}, true);

