function shouldActivateCustomControl(e, control) {
  if (!control || (e.key !== 'Enter' && e.key !== ' ')) return false;
  const tag = String(control.tagName || '').toLowerCase();
  return !['button', 'a', 'input', 'select', 'textarea', 'summary'].includes(tag);
}

