document.addEventListener('error', function(e) {
  const img = e.target;
  if (!(img instanceof HTMLImageElement)) return;
  const mode = img.dataset.imageError;
  if (!mode) return;

  if (mode === 'media') {
    handleImageError(img);
    return;
  }

  if (mode === 'thumb') {
    handleThumbError(img);
    return;
  }

  if (mode === 'hide') {
    img.style.display = 'none';
    return;
  }

  if (mode === 'fade') {
    img.style.opacity = '0';
    return;
  }

  if (mode === 'placeholder') {
    if (img.dataset.placeholderApplied === '1') {
      img.style.display = 'none';
      return;
    }
    img.dataset.placeholderApplied = '1';
    img.src = IMAGE_PLACEHOLDER_SRC;
  }
}, true);

const GLOSSARY_THEME_META = {
  all: { label: 'Todo', hint: 'Vista completa' },
  anatomia: { label: 'Anatomía', hint: 'Cráneo, dientes y postcráneo' },
  datacion: { label: 'Datación', hint: 'Métodos, estratos y cronología' },
  filogenia: { label: 'Filogenia', hint: 'Clados, rasgos y parentesco' },
  paleogenomica: { label: 'Paleogenómica', hint: 'ADN, introgresión y genes' },
  paleoambiente: { label: 'Paleoambiente', hint: 'Clima, biomas y ecología' },
  cultura: { label: 'Cultura material', hint: 'Herramientas y conducta' }
};

let glossaryActiveTheme = 'all';

function classifyGlossaryTerm(term, definition) {
  const haystack = (term + ' ' + definition).toLowerCase();
  const tags = [];
  const rules = {
    anatomia: /cr[aá]neo|mand[ií]bula|maxilar|diente|dental|alv[eé]olo|molar|premolar|esmalte|pelvis|acet[aá]bulo|ilion|isquion|pubis|f[eé]mur|h[uú]mero|radio|ulna|c[uú]bito|esc[aá]pula|postcraneal|biped|foramen|sagital|supraorbit|ment[oó]n|torus|capacidad craneal|cerebro|falange|canino|v[eé]rtebra|entesis|arco cigom[aá]tico|aparato masticatorio|abducci[oó]n|aducci[oó]n|alometr/,
    datacion: /dataci[oó]n|cronolog|dimensi[oó]n temporal|edad m[ií]nima|edad m[aá]xima|estratigraf|is[oó]top|arg[oó]n|uranio|radiocarbono|luminiscencia|esr|series|\bka\b|\bma\b|tefro|magneto|biocronolog|sedimento|nivel/,
    filogenia: /clado|sinapomorf|plesiomorf|autapomorf|apomorf|anag[eé]nic|especiaci[oó]n|selecci[oó]n natural|taxonom|filogen|linaje|homolog|analog|convergencia|ancestro|hominin|hominoid|parafilet/,
    paleogenomica: /adn|gen[oó]m|introgresi[oó]n|mitocondrial|nuclear|prote[oó]mica|epas1|foxp2|mc1r|denisov|neandertal|haplogrupo|alelo/,
    paleoambiente: /clima|paleoambiente|sabana|bosque|aridez|vegetaci[oó]n|c4|bioma|ecolog|dieta|isotop|nicho|tafonom|paisaje|rift|glacial|interglacial|cuenca|deposici[oó]n|desecaci[oó]n|aluvial|lacustre/,
    cultura: /herramient|l[ií]tica|olduvayense|achelense|musteriense|arte|simb[oó]lic|industria|tecnolog|conducta|fuego|enterramiento|cultura|modo /
  };
  Object.entries(rules).forEach(([key, regex]) => {
    if (regex.test(haystack)) tags.push(key);
  });
  return tags.length ? tags : ['filogenia'];
}

function applyGlossaryFilters() {
  if (window.PaleoBotGlossaryPagination?.filter) {
    return window.PaleoBotGlossaryPagination.filter();
  }
  const activeTheme = GLOSSARY_THEME_META[glossaryActiveTheme] ? glossaryActiveTheme : 'all';
  const searchTerm = normalizeForSearch(document.querySelector('[data-gloss-search]')?.value || '');
  document.querySelectorAll('[data-gloss-theme]').forEach(btn => {
    const active = btn.dataset.glossTheme === activeTheme;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
  document.querySelectorAll('.glossary-card').forEach(card => {
    const tags = String(card.dataset.glossTags || '').split(',');
    const matchTheme = activeTheme === 'all' || tags.includes(activeTheme);
    const matchSearch = !searchTerm || normalizeForSearch(card.textContent || '').includes(searchTerm);
    card.hidden = !(matchTheme && matchSearch);
  });
  document.querySelectorAll('.glossary-section').forEach(section => {
    section.hidden = section.querySelectorAll('.glossary-card:not([hidden])').length === 0;
  });
  const count = document.getElementById('glossThemeCount');
  if (count) {
    const visible = document.querySelectorAll('.glossary-card:not([hidden])').length;
    count.textContent = activeTheme === 'all'
      ? `${visible} términos visibles`
      : `${visible} términos en ${GLOSSARY_THEME_META[activeTheme].label.toLowerCase()}`;
  }
}

function filterGlossaryTheme(theme = 'all') {
  glossaryActiveTheme = GLOSSARY_THEME_META[theme] ? theme : 'all';
  applyGlossaryFilters();
}

function renderGlossary() {
  const container = document.getElementById("glossaryContent");
  if (!container) return;
  // FIX v21: guard against rebuilding — openGlossaryAt needs stable DOM IDs
  if (container.dataset.rendered === '1') return;
  container.dataset.rendered = '1';
  const terms = Object.keys(glosario).sort((a, b) => a.localeCompare(b, "es", { sensitivity: "base" }));

  // Group by first letter (normalizado sin acentos)
  const byLetter = {};
  terms.forEach(term => {
    const letter = term.normalize('NFD').replace(/[\u0300-\u036f]/g,'')[0].toUpperCase();
    if (!byLetter[letter]) byLetter[letter] = [];
    byLetter[letter].push(term);
  });
  const letters = Object.keys(byLetter).sort();
  const themeCounts = Object.fromEntries(Object.keys(GLOSSARY_THEME_META).map(key => [key, 0]));
  const termTags = {};
  terms.forEach(term => {
    const tags = classifyGlossaryTerm(term, getGlossaryDefinition(term));
    termTags[term] = tags;
    tags.forEach(tag => { themeCounts[tag] = (themeCounts[tag] || 0) + 1; });
  });
  themeCounts.all = terms.length;

  // A-Z nav bar — sin template literals anidados
  let navBtns = '';
  for (const l of 'ABCDEFGHIJKLMNOPQRSTUVWXYZ') {
    if (byLetter[l]) {
      navBtns += '<button type="button" class="glossary-nav-btn" data-gloss-scroll="' + l + '">' + l + '</button>';
    } else {
      navBtns += '<span class="glossary-nav-empty">' + l + '</span>';
    }
  }

  const themeBtns = Object.entries(GLOSSARY_THEME_META).map(([key, meta]) =>
    '<button type="button" class="glossary-theme-btn' + (key === 'all' ? ' active' : '') + '" data-gloss-theme="' + key + '" aria-pressed="' + (key === 'all' ? 'true' : 'false') + '">' +
      '<strong>' + escapeHtmlText(meta.label) + ' · ' + (themeCounts[key] || 0) + '</strong>' +
      escapeHtmlText(meta.hint) +
    '</button>'
  ).join('');

  // Sections by letter
  let sections = '';
  letters.forEach(letter => {
    let cards = '';
    byLetter[letter].forEach(term => {
      const safeId = 'gt-' + term.replace(/[\s()\/]+/g,'_');
      const tags = termTags[term] || [];
      const learning = getGlossaryLearningEntry(term, tags);
      const tagLabels = tags.map(tag => '<span class="glossary-card-tag">' + escapeHtmlText(GLOSSARY_THEME_META[tag]?.label || tag) + '</span>').join('');
      cards += '<article class="glossary-card" id="' + safeId + '" data-gloss-tags="' + escapeHtmlAttr(tags.join(',')) + '">';
      cards += '<div class="glossary-card-head">';
      cards += '<h3>' + escapeHtmlText(term) + '</h3>';
      cards += '<button type="button" class="glossary-top-btn" data-gloss-top>inicio</button>';
      cards += '</div>';
      cards += '<div class="glossary-levels">';
      cards += '<div class="glossary-level secundaria"><strong>Secundaria</strong><p>' + escapeHtmlText(learning.secundaria) + '</p></div>';
      cards += '<div class="glossary-level bachillerato"><strong>Bachillerato / Universidad</strong><p>' + escapeHtmlText(learning.bachillerato) + '</p></div>';
      cards += '<div class="glossary-level avanzado"><strong>Lectura avanzada</strong><p>' + escapeHtmlText(learning.avanzado) + '</p></div>';
      cards += '</div>';
      cards += '<div class="glossary-example"><strong>Uso en PaleoBot:</strong> ' + escapeHtmlText(learning.ejemplo) + '</div>';
      cards += '<div class="glossary-card-tags">' + tagLabels + '</div>';
      cards += '</article>';
    });
    sections += '<div class="glossary-section" id="gloss-sec-' + letter + '">';
    sections += '<div class="glossary-section-head">';
    sections += '<span class="glossary-section-letter">' + letter + '</span>';
    sections += '<span class="glossary-section-count">' + byLetter[letter].length + ' término' + (byLetter[letter].length > 1 ? 's' : '') + '</span>';
    sections += '</div>';
    sections += '<div class="glossary-grid">' + cards + '</div>';
    sections += '</div>';
  });

  container.innerHTML =
    '<div class="glossary-top" id="gloss-top">' +
      '<p>Diccionario por niveles: cada concepto incluye una explicación para <strong>Secundaria</strong>, una lectura para <strong>Bachillerato / Universidad</strong> y una precisión <strong>avanzada</strong>. Los mismos términos aparecen subrayados y clicables dentro de cada ficha.</p>' +
      '<div class="glossary-total">' + terms.length + ' términos · ' + letters.length + ' letras</div>' +
      '<input class="glossary-search" type="search" data-gloss-search placeholder="Buscar concepto: bipedismo, ADN, datación..." aria-label="Buscar en el glosario">' +
    '</div>' +
    '<section class="glossary-theme-panel" aria-label="Filtros temáticos del glosario">' +
      '<div class="glossary-theme-intro"><strong>Explora por disciplina</strong><p>Filtra el vocabulario según el tipo de problema: anatomía, datación, filogenia, paleogenómica, paleoambiente o cultura material. Útil para preparar clases, debates y trabajos de investigación.</p><p id="glossThemeCount" class="glossary-count">' + terms.length + ' términos visibles</p></div>' +
      '<div class="glossary-theme-grid" role="group" aria-label="Categorías temáticas del glosario">' + themeBtns + '</div>' +
    '</section>' +
    /* FIX A-9: role=navigation + aria-label para WCAG 2.4.1 (Bypass Blocks) */
    '<nav class="glossary-nav" aria-label="Navegación alfabética del glosario">' +
      '<span class="glossary-nav-label">Ir a:</span>' +
      navBtns +
    '</nav>' +
    sections;
}

// Scroll dentro del modal del glosario
function glossScrollTo(letter) {
  const el = document.getElementById('gloss-sec-' + letter);
  if (!el) return;
  const modal = document.querySelector('#glossaryModal .modal-content');
  if (modal) { modal.scrollTop = el.offsetTop - 80; }
  else el.scrollIntoView({behavior:'smooth', block:'start'});
}
function glossScrollTop() {
  const modal = document.querySelector('#glossaryModal .modal-content');
  if (modal) modal.scrollTop = 0;
}
// Abre el glosario y salta al término específico
function openGlossaryAt(term) {
  openGlossary();
  // FIX v21: increased delay; renderGlossary now cached so DOM is stable on reopen
  setTimeout(() => {
    // term already has spaces→_ from aplicarGlosario; try both raw and normalised
    const variants = [
      'gt-' + term,
      'gt-' + term.replace(/[\s()\/]+/g,'_'),
      'gt-' + term.replace(/'/g,'_'),
      'gt-' + term.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\s()\/]+/g,'_')
    ];
    let el = null;
    for (const id of variants) {
      el = document.getElementById(id);
      if (el) break;
    }
    if (!el) {
      // last resort: partial match on data-id attribute or text content
      document.querySelectorAll('.glossary-card').forEach(card => {
        if (!el && card.querySelector('h3')?.textContent.toLowerCase().includes(term.toLowerCase().replace(/_/g,' '))) el = card;
      });
    }
    if (!el) return;
    if (window.PaleoBotGlossaryPagination?.reveal) {
      window.PaleoBotGlossaryPagination.reveal(el);
    }
    const modal = document.querySelector('#glossaryModal .modal-content');
    if (modal) modal.scrollTop = el.offsetTop - 80;
    el.style.transition = 'background 0.35s';
    el.style.background = '#e4f5ef';
    el.style.outline = '2px solid var(--accent)';
    el.style.borderRadius = '10px';
    setTimeout(() => { el.style.background = ''; el.style.outline = ''; }, 2000);
  }, 200);
}

