/**
 * Rango temporal en Ma. Delegado a ComputedCache para memoización automática.
 * Misma API pública que la versión anterior.
 */
function getSpeciesTimeRange(sp) {
  return PaleoBot.ComputedCache.getTimeRange(sp);
}

function formatTimePoint(ma) {
  const value = Number(ma);
  if (value === 0) return 'Hoy';
  if (value < 1) return `${Math.round(value * 1000)} ka`;
  return `${Number.isInteger(value) ? value.toFixed(0) : value.toFixed(2).replace(/0+$/,'').replace(/\.$/,'')} Ma`;
}

function speciesInTimeFilter(sp) {
  const tr = getSpeciesTimeRange(sp);
  return tr.start >= timeFilter.young && tr.end <= timeFilter.old;
}

function updateTimeFilterUI() {
  const oldInput = document.getElementById('timeRangeOld');
  const youngInput = document.getElementById('timeRangeYoung');
  const fill = document.getElementById('timeSliderFill');
  const readout = document.getElementById('timeFilterReadout');
  if (oldInput) oldInput.value = String(timeFilter.old);
  if (youngInput) youngInput.value = String(timeFilter.young);
  if (fill) {
    fill.style.left = `${(timeFilter.young / 23) * 100}%`;
    fill.style.right = `${100 - (timeFilter.old / 23) * 100}%`;
  }
  if (readout) {
    readout.textContent = timeFilter.old === timeFilter.young
      ? `Instantánea: ${formatTimePoint(timeFilter.old)}`
      : `${formatTimePoint(timeFilter.young)} – ${formatTimePoint(timeFilter.old)}`;
  }
  document.querySelectorAll('.time-chip-btn').forEach(btn => btn.classList.remove('active'));
}

/**
 * Actualiza el filtro temporal desde los sliders de rango.
 * Sincroniza valores y atributos ARIA (FIX C-3a — WCAG 2.1 §4.1.2).
 * @param {'old'|'young'} changed - Qué slider se modificó
 */
function setTimeRangeFromInputs(changed) {
  const oldInput   = document.getElementById('timeRangeOld');
  const youngInput = document.getElementById('timeRangeYoung');
  if (!oldInput || !youngInput) return;

  let oldVal   = parseFloat(oldInput.value);
  let youngVal = parseFloat(youngInput.value);

  // Garantizar que el límite antiguo >= límite reciente
  if (changed === 'old'   && oldVal   < youngVal) youngVal = oldVal;
  if (changed === 'young' && youngVal > oldVal)   oldVal   = youngVal;

  // Sincronizar los valores de los inputs si se corrigieron
  oldInput.value   = oldVal;
  youngInput.value = youngVal;

  // FIX C-3a: actualizar atributos ARIA en tiempo real para lectores de pantalla
  oldInput.setAttribute('aria-valuenow',   oldVal.toFixed(1));
  oldInput.setAttribute('aria-valuetext',  oldVal.toFixed(1) + ' Ma');
  youngInput.setAttribute('aria-valuenow',  youngVal.toFixed(1));
  youngInput.setAttribute('aria-valuetext', youngVal.toFixed(1) + ' Ma');

  timeFilter = { old: +oldVal.toFixed(2), young: +youngVal.toFixed(2) };
  updateTimeFilterUI();
  applyFilters();
}

function setTimePreset(oldMa, youngMa) {
  timeFilter = {
    old: Math.max(oldMa, youngMa),
    young: Math.min(oldMa, youngMa)
  };
  updateTimeFilterUI();
  applyFilters();
}

/**
 * Determina si una especie pasa los filtros activos.
 * Usa SearchEngine para scoring multi-campo (antes era solo substring en 6 campos).
 * Retrocompatible: sigue siendo llamable con un solo argumento.
 */
function matchesActiveFilters(sp) {
  const term = document.getElementById('searchInput')?.value || '';
  const matchClado  = cladoFilter === 'all' || sp.clado === cladoFilter;
  if (!matchClado) return false;
  if (!speciesInTimeFilter(sp)) return false;
  if (!term.trim()) return true;
  // SearchEngine.search devuelve array ordenado por score; score>0 = match
  const results = PaleoBot.SearchEngine.search(term, [sp]);
  return results.length > 0;
}

function getSpeciesContinents(sp) {
  if (CONTINENT_OVERRIDES[sp.id]) return CONTINENT_OVERRIDES[sp.id];
  const loc = normalizeForSearch(sp.ubicacion || '');
  const hits = [];
  if (/(africa|kenia|uganda|chad|etiopia|tanzania|sudafrica|zambia|marruecos)/.test(loc)) hits.push('africa');
  if (/(europa|espana|italia|francia|alemania|georgia|grecia|caucaso)/.test(loc)) hits.push('europe');
  if (/(asia|siberia|china|indonesia|filipinas|java|sudeste asiat|caucaso)/.test(loc)) hits.push('asia');
  if (!hits.length && sp.id === 'sapiens') hits.push('africa', 'europe', 'asia');
  return [...new Set(hits)];
}

function renderContinentsView() {
  const container = document.getElementById('continentBoard');
  if (!container) return;

  const taxa = DB
    .filter(matchesActiveFilters)
    .map(sp => ({ ...sp, range: getSpeciesTimeRange(sp), continents: getSpeciesContinents(sp) }));

  const countEl = document.getElementById('continentVisibleCount');
  const rangeEl = document.getElementById('continentRangeHint');
  if (countEl) countEl.textContent = String(taxa.length);
  if (rangeEl) {
    if (!taxa.length) {
      rangeEl.textContent = 'sin rango';
    } else {
      const oldest = Math.max(...taxa.map(sp => sp.range.start));
      const youngest = Math.min(...taxa.map(sp => sp.range.end));
      rangeEl.textContent = formatMaRange(oldest, youngest);
    }
  }

  if (!taxa.length) {
    container.innerHTML = `<div class="continent-empty">No hay taxones visibles con esta combinación de búsqueda y filtro de clado.</div>`;
    return;
  }

  const axisTicks = [23, 10, 5, 2, 1, 0.3, 0];
  const xAt = ma => ((23 - ma) / 23) * 100;

  container.innerHTML = CONTINENT_LANES.map(lane => {
    const items = taxa
      .filter(sp => sp.continents.includes(lane.id))
      .sort((a, b) => b.range.start - a.range.start || b.range.end - a.range.end);

    if (!items.length) {
      return `<section class="continent-panel" style="--continent-accent:${escapeHtmlAttr(lane.color)};--continent-soft:${escapeHtmlAttr(lane.soft)}">
        <div class="continent-top">
          <div class="continent-title-wrap">
            <h3>${escapeHtmlText(lane.label)}</h3>
            <p>${escapeHtmlText(lane.summary)}</p>
          </div>
        </div>
        <div class="continent-empty">No hay taxones visibles en este carril continental con los filtros actuales.</div>
      </section>`;
    }

    const oldest = Math.max(...items.map(sp => sp.range.start));
    const youngest = Math.min(...items.map(sp => sp.range.end));
    const clades = [...new Set(items.map(sp => CLADE_NAMES[sp.clado] || sp.clado))].join(' · ');
    const rows = items.map(sp => {
      const left = xAt(sp.range.start);
      const width = Math.max(xAt(sp.range.end) - left, 1.8);
      const debated = sp.estado === 'debatida' || sp.estado === 'revision';
      const linkedContinents = sp.continents.filter(id => id !== lane.id).map(id => CONTINENT_LABELS[id]);
      const safeId = escapeHtmlAttr(sp.id);
      const safeName = escapeHtmlText(sp.nombre);
      const safeYears = escapeHtmlText(sp.anos);
      const safeLocation = escapeHtmlText(sp.ubicacion);
      const safeColor = escapeHtmlAttr(CLADE_COLORS[sp.clado] || lane.color);
      const duplicate = linkedContinents.length ? `<span class="continent-dup">↔ ${escapeHtmlText(linkedContinents.join(' · '))}</span>` : '';
      return `<div class="continent-row">
        <button type="button" class="continent-taxon" data-open-species="${safeId}">
          <span class="continent-taxon-name">${safeName}</span>
          <span class="continent-taxon-meta">
            <span>${safeYears}</span>
            <span>·</span>
            <span>${safeLocation}</span>
            ${duplicate}
          </span>
        </button>
        <div class="continent-track">
          <div class="continent-bar ${debated ? 'debated' : ''}" style="left:${left.toFixed(2)}%;width:${width.toFixed(2)}%;background:${safeColor}">
            ${safeYears}
          </div>
        </div>
      </div>`;
    }).join('');

    const axis = axisTicks.map(ma => {
      const label = ma === 0 ? 'Hoy' : ma < 1 ? `${Math.round(ma * 1000)} ka` : `${ma} Ma`;
      return `<span class="continent-axis-tick" style="left:${xAt(ma).toFixed(2)}%"></span><span class="continent-axis-label" style="left:${xAt(ma).toFixed(2)}%">${escapeHtmlText(label)}</span>`;
    }).join('');

    return `<section class="continent-panel" style="--continent-accent:${escapeHtmlAttr(lane.color)};--continent-soft:${escapeHtmlAttr(lane.soft)}">
      <div class="continent-top">
        <div class="continent-title-wrap">
          <h3>${escapeHtmlText(lane.label)}</h3>
          <p>${escapeHtmlText(lane.summary)}</p>
        </div>
        <div class="continent-kpis">
          <span class="continent-kpi">${escapeHtmlText(items.length)} taxones</span>
          <span class="continent-kpi">${escapeHtmlText(formatMaRange(oldest, youngest))}</span>
          <span class="continent-kpi">${escapeHtmlText(clades)}</span>
        </div>
      </div>
      <div class="continent-axis">
        <div class="continent-axis-line"></div>
        ${axis}
      </div>
      <div class="continent-list">${rows}</div>
      <div class="continent-footer">
        <span>Haz clic en una fila para abrir la ficha completa.</span>
        <span>La barra expresa rango temporal estimado, no una fecha puntual.</span>
      </div>
    </section>`;
  }).join('');
}

