function getAsiaTaxa() {
  const ids = new Set(ASIA_TAXON_IDS);
  return DB.filter(sp => ids.has(sp.id) && matchesActiveFilters(sp));
}

function renderAsiaRoutes() {
  return `<section class="america-panel">
    <div class="america-panel-head">
      <h3>Problemas de dispersión asiática</h3>
      <p>Lee Asia como conjunto de corredores, refugios y barreras, no como una flecha continua hacia el este.</p>
    </div>
    <div class="america-route-list">
      ${ASIA_DISPERSAL_PROBLEMS.map(route => `<article class="america-route-card">
        <h4>${escapeHtmlText(route.title)}</h4>
        <div class="america-route-meta">
          <span class="america-pill">${escapeHtmlText(route.period)}</span>
          ${renderAmericaConsensus(route.status)}
        </div>
        <p>${escapeHtmlText(route.summary)}</p>
      </article>`).join('')}
    </div>
    <p class="america-note"><strong>Clave didáctica:</strong> Asia permite enseñar que dispersión, persistencia, mezcla e insularidad son procesos distintos. Una ruta de mapa no equivale a parentesco ni a consenso taxonómico.</p>
  </section>`;
}

function renderAsiaCaseList() {
  const sorted = [...ASIA_CASES].sort((a, b) => b.ageSort - a.ageSort);
  return `<section class="america-panel">
    <div class="america-panel-head">
      <h3>Casos de estudio</h3>
      <p>Ordenados de más antiguo a más reciente para comparar oleadas, regiones y tipos de evidencia.</p>
    </div>
    <div class="america-site-list">
      ${sorted.map(item => `<button type="button" class="america-site-card ${item.id === asiaActiveCaseId ? 'active' : ''}" data-asia-case="${escapeHtmlAttr(item.id)}">
        <h4>${escapeHtmlText(item.name)}</h4>
        <div class="america-site-meta">
          <span class="america-pill">${escapeHtmlText(item.region)}</span>
          <span class="america-pill">${escapeHtmlText(item.age)}</span>
          ${renderAmericaConsensus(item.consensus)}
        </div>
        <p>${escapeHtmlText(item.evidence)}</p>
      </button>`).join('')}
    </div>
  </section>`;
}

function renderAsiaCaseDetail(item) {
  const refs = item.sourceIds.map(id => ASIA_SOURCES.find(src => src.id === id)).filter(Boolean);
  const taxa = item.taxonIds.map(id => DB_INDEX[id]).filter(Boolean);
  return `<section class="america-panel">
    <div class="america-panel-head">
      <h3>${escapeHtmlText(item.name)}</h3>
      <p>${escapeHtmlText(item.region)} · ${escapeHtmlText(item.age)} · lectura crítica de dispersión</p>
    </div>
    <div class="america-site-list">
      <article class="america-site-card active">
        <h4>Qué enseña</h4>
        <p>${escapeHtmlText(item.meaning)}</p>
        <div class="america-evidence-box"><strong>Evidencia:</strong> ${escapeHtmlText(item.evidence)}</div>
        <div class="america-evidence-box"><strong>Cautela:</strong> ${escapeHtmlText(item.caution)}</div>
        <div class="america-route-meta">
          ${taxa.map(sp => `<button type="button" class="america-pill" data-open-species="${escapeHtmlAttr(sp.id)}">${escapeHtmlText(sp.nombre)}</button>`).join('')}
        </div>
      </article>
    </div>
    <div class="america-source-list">
      ${refs.map(src => renderAsiaSourceItem(src)).join('')}
    </div>
  </section>`;
}

function renderAsiaActivities() {
  const activities = [
    {
      title: 'Secundaria',
      prompt: 'Ordena Dmanisi, Homo erectus asiático, Denisova/Harbin y Flores/Luzón. Después marca qué caso es fósil, cuál es ADN/proteína y cuál depende de inferencia.'
    },
    {
      title: 'Bachillerato',
      prompt: 'Explica por qué “Asia fue solo una ruta de paso” es una mala afirmación científica. Usa dos casos y una cautela.'
    },
    {
      title: 'Universidad',
      prompt: 'Construye una matriz con región, cronología, evidencia principal, grado de consenso y pregunta abierta para cada caso asiático.'
    }
  ];
  return `<section class="america-panel">
    <div class="america-panel-head">
      <h3>Actividad graduada por nivel</h3>
      <p>La misma vista se convierte en secuencia didáctica: orientación, argumentación y lectura crítica de literatura reciente.</p>
    </div>
    <div class="america-activity-grid">
      ${activities.map(item => `<article class="america-activity-card">
        <h4>${escapeHtmlText(item.title)}</h4>
        <p>${escapeHtmlText(item.prompt)}</p>
      </article>`).join('')}
    </div>
  </section>`;
}

function renderAsiaSourceItem(src) {
  return `<article class="america-source-item">
    <strong>${escapeHtmlText(src.title)}</strong>
    <span>${escapeHtmlText(src.authors)} (${src.year}) · ${escapeHtmlText(src.journal)}</span>
    ${src.note ? `<span>${escapeHtmlText(src.note)}</span>` : ''}
    <a href="https://doi.org/${escapeHtmlAttr(src.doi)}" target="_blank" rel="noopener">doi:${escapeHtmlText(src.doi)}</a>
  </article>`;
}

function renderAsiaSourceIndex() {
  return `<section class="america-panel">
    <div class="america-panel-head">
      <h3>Bibliografía reciente verificada</h3>
      <p>Selección centrada en 2023-2025 para actualizar Asia: Denisovanos, Harbin, Yunxian, Hualongdong y Juluren.</p>
    </div>
    <div class="america-source-list">
      ${ASIA_SOURCES.map(src => renderAsiaSourceItem(src)).join('')}
    </div>
  </section>`;
}

function renderAsiaView() {
  const container = document.getElementById('asiaDashboard');
  if (!container) return;
  const visibleAsiaTaxa = getAsiaTaxa();
  const activeCase = ASIA_CASES.find(item => item.id === asiaActiveCaseId) || ASIA_CASES[0];
  asiaActiveCaseId = activeCase.id;

  const kpiTaxa = document.getElementById('asiaKpiTaxa');
  const kpiCases = document.getElementById('asiaKpiCases');
  const kpiSources = document.getElementById('asiaKpiSources');
  if (kpiTaxa) kpiTaxa.textContent = String(visibleAsiaTaxa.length);
  if (kpiCases) kpiCases.textContent = String(ASIA_CASES.length);
  if (kpiSources) kpiSources.textContent = String(ASIA_SOURCES.length);

  container.innerHTML = `<div class="america-grid">
    <div>
      ${renderAsiaRoutes()}
      ${renderAsiaCaseList()}
    </div>
    <div>
      ${renderAsiaCaseDetail(activeCase)}
    </div>
  </div>
  ${renderAsiaActivities()}
  ${renderAsiaSourceIndex()}`;
}

function selectAsiaCase(caseId) {
  if (!ASIA_CASES.some(item => item.id === caseId)) return;
  asiaActiveCaseId = caseId;
  renderAsiaView();
}

