function getBiogeoRecordThumb(rec, sp, dbIdCounts) {
  const media = rec.media_id ? BIO_SPECIMEN_MEDIA[rec.media_id] : null;
  if (media) {
    const alt = `${media.title}. ${rec.elemento} atribuido a ${rec.especie}.`;
    const provenance = `${media.title}. Fuente: ${media.source}. Licencia: ${media.license}.`;
    return `<img src="${escapeHtmlAttr(media.url)}" class="biogeo-record-thumb" alt="${escapeHtmlAttr(alt)}" title="${escapeHtmlAttr(provenance)}" data-specimen-media="exact" data-specimen-media-key="${escapeHtmlAttr(rec.media_id)}" data-specimen-label="${escapeHtmlAttr(rec.especimen)}" data-specimen-site="${escapeHtmlAttr(rec.yacimiento)}" loading="lazy" decoding="async" referrerpolicy="no-referrer">`;
  }

  const sharedTaxonImage = rec.db_id && (dbIdCounts.get(rec.db_id) || 0) > 1;
  if (sp && !sharedTaxonImage) {
    return `<img src="${getSpeciesThumb(sp, 120)}" class="biogeo-record-thumb" alt="${escapeHtmlAttr(sp.nombre)}" data-image-error="hide" loading="lazy" decoding="async" referrerpolicy="no-referrer">`;
  }

  return `<span class="biogeo-record-thumb biogeo-record-thumb-missing" role="img" aria-label="No hay una imagen específica abierta y verificada para ${escapeHtmlAttr(rec.especimen)}" title="Sin imagen específica abierta y verificada"><span aria-hidden="true">N/D</span></span>`;
}


function renderBiogeo() {
  if (biogeoRendered) return;
  biogeoRendered = true;
  const container = document.getElementById('biogeoContainer');
  if (!container) return;

  const allRecs   = BIO_REGIONES.flatMap(r => r.registros);
  const totalRecs = allRecs.length;
  const linkedRecs = allRecs.filter(r => r.db_id).length;
  const dbIdCounts = allRecs.reduce((counts, rec) => {
    if (rec.db_id) counts.set(rec.db_id, (counts.get(rec.db_id) || 0) + 1);
    return counts;
  }, new Map());
  const withAge   = allRecs.filter(r => r.edad_ma).sort((a,b) => b.edad_ma - a.edad_ma);
  const oldest    = withAge[0];
  const totalTaxa = BIO_LEYENDA.reduce((s,g) => s + g.especies.filter(sp => !sp.isHeader).length, 0);
  const MAX_MA    = 2.5;

  // Stats bar
  const statsBar = `
    <div class="biogeo-stats">
      <div class="biogeo-stat"><strong>${totalRecs}</strong><span>Especímenes</span></div>
      <div class="biogeo-stat"><strong>${BIO_REGIONES.length}</strong><span>Regiones</span></div>
      <div class="biogeo-stat"><strong>${oldest ? oldest.edad : '—'}</strong><span>Registro más antiguo</span></div>
      <div class="biogeo-stat"><strong>${linkedRecs}</strong><span>Con ficha enlazada</span></div>
      <div class="biogeo-stat"><strong>${totalTaxa}</strong><span>Taxones en leyenda</span></div>
    </div>`;

  // Leyenda
  const legendGroups = BIO_LEYENDA.map(g => {
    const items = g.especies.map(sp => {
      if (sp.isHeader) return `<span class="biogeo-legend-subheader">${escapeHtmlText(sp.nombre)}</span>`;
      const col = sp.color || g.color;
      const hasDb = sp.id && DB.find(s => s.id === sp.id);
      const clickAttr = hasDb
        ? `data-open-species="${escapeHtmlAttr(sp.id)}" role="button" tabindex="0" title="Abrir ficha: ${escapeHtmlAttr(sp.nombre)}" aria-label="Abrir ficha: ${escapeHtmlAttr(sp.nombre)}"`
        : '';
      return `<div class="biogeo-legend-sp ${hasDb ? 'clickable' : ''}" style="border-left-color:${escapeHtmlAttr(col)}" ${clickAttr}>${escapeHtmlText(sp.nombre)}${sp.nota ? `<small>${escapeHtmlText(sp.nota)}</small>` : ''}</div>`;
    }).join('');
    return `<div class="biogeo-legend-group" style="background:${escapeHtmlAttr(g.bg)};border-color:${escapeHtmlAttr(g.color)}44">
      <div class="biogeo-legend-group-header" style="background:${escapeHtmlAttr(g.color)}">${escapeHtmlText(g.grupo)}</div>
      ${items}
    </div>`;
  }).join('');

  // Paneles regionales
  const regionPanels = BIO_REGIONES.map(reg => {
    const cards = reg.registros.map(rec => {
      const col = CLADE_COLORS[rec.clado] || '#888';
      const sp  = rec.db_id ? DB.find(s => s.id === rec.db_id) : null;
      const isLink = !!sp;
      const clickAttr = isLink ? `data-open-species="${escapeHtmlAttr(rec.db_id)}" role="button" tabindex="0" aria-label="Abrir ficha: ${escapeHtmlAttr(rec.especie)}"` : '';
      const notaBadge = rec.nota ? `<span class="biogeo-tag-note">⚠ ${escapeHtmlText(rec.nota)}</span>` : '';
      const ageBadge  = rec.edad_ma !== null
        ? `<span class="biogeo-tag-age">⏱ ${escapeHtmlText(rec.edad)}</span>`
      : `<span class="biogeo-tag-age muted">Edad indeterminada</span>`;
      const linkBadge = isLink ? `<span class="biogeo-tag-link">→ Ficha</span>` : '';
      const thumb     = getBiogeoRecordThumb(rec, sp, dbIdCounts);
      const agePct    = rec.edad_ma ? Math.min((rec.edad_ma / MAX_MA) * 100, 100).toFixed(0) : 0;
      const safeColor = escapeHtmlAttr(col);
      const ageBar    = `<div class="biogeo-age-track"><div class="biogeo-age-fill" style="width:${agePct}%;background:${safeColor}70"></div></div>`;
      return `<div class="biogeo-record${isLink ? ' is-link' : ''}" style="border-left-color:${safeColor}" ${clickAttr}>
        <div class="biogeo-record-inner">
          ${thumb}
          <div class="biogeo-record-body">
            <div class="biogeo-record-site">${escapeHtmlText(rec.yacimiento)}</div>
            <div class="biogeo-record-specimen">${escapeHtmlText(rec.especimen)}</div>
            <div class="biogeo-record-element">${escapeHtmlText(rec.elemento)}</div>
            <div class="biogeo-record-species">${escapeHtmlText(rec.especie)}</div>
            <div class="biogeo-record-meta">${ageBadge}<span class="biogeo-tag-loc">📍 ${escapeHtmlText(rec.pais)}</span>${notaBadge}${linkBadge}</div>
            ${ageBar}
          </div>
        </div>
      </div>`;
    }).join('');
    return `<div class="biogeo-region">
      <div class="biogeo-region-header" style="background:${escapeHtmlAttr(reg.color)}">
        <span class="biogeo-region-icon">${escapeHtmlText(reg.icono)}</span>
        <span class="biogeo-region-title">${escapeHtmlText(reg.titulo)}</span>
        <span class="biogeo-region-count">${escapeHtmlText(reg.registros.length)} registros</span>
      </div>
      <div class="biogeo-records">${cards}</div>
    </div>`;
  }).join('');

  container.innerHTML = `
    <div class="biogeo-header">
      <div class="biogeo-header-top">
        <div>
          <h2>Cronología de los primeros homininos según una base biogeográfica</h2>
          <p>Especímenes clave por región · Ordenados cronológicamente · Las barras indican antigüedad relativa (escala 0–2,5 Ma)</p>
        </div>
        <span class="biogeo-badge-count">${totalRecs} especímenes</span>
      </div>
      ${statsBar}
      <div style="margin-top:16px">
        <div class="biogeo-legend-label"><span class="ico" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><rect x="9" y="2" width="6" height="4" rx="1"/><rect x="2" y="18" width="5" height="4" rx="1"/><rect x="9" y="18" width="5" height="4" rx="1"/><rect x="17" y="18" width="5" height="4" rx="1"/><path d="M4.5 22v-4a7 7 0 0 1 15 0v4"/><line x1="12" y1="6" x2="12" y2="18"/></svg></span>&nbsp;Taxones representados · Haz clic en cualquier nombre para abrir su ficha</div>
        <div class="biogeo-legend-grid">${legendGroups}</div>
      </div>
    </div>
    <div class="biogeo-regions">${regionPanels}</div>`;
}




function openLightbox(src) {
    document.getElementById('lbImage').src = src;
    document.getElementById('lightbox').classList.add('active');
    updateBackButtonState();
}

function closeDetailPanel() {
    const panel = document.getElementById('detailView');
    if (!panel) return false;
    const wasActive = panel.classList.contains('active');
    panel.classList.remove('active');
    if (wasActive) {
        currentSpecies = null;
        // FIX C-3e: liberar focus trap y devolver foco al disparador
        if (typeof _panelTrapRemover === 'function') {
            try { _panelTrapRemover(); } catch(e) { /* recuperable: suprimido intencionalmente */ }
            _panelTrapRemover = null;
        }
        // Destroy Leaflet map to free memory
        if (_activeLeafletMap) {
            try { _activeLeafletMap.remove(); } catch(e) { if(typeof Logger!=="undefined") Logger.debug("leaflet.remove", e); }
            _activeLeafletMap = null;
        }
    }
    updateBackButtonState();
    return wasActive;
}

// closeTopModal: ya definido en toggleModal block

function closeActiveUI() {
    const lightbox = document.getElementById('lightbox');
    if (lightbox && lightbox.classList.contains('active')) {
        lightbox.classList.remove('active');
        updateBackButtonState();
        return true;
    }
    if (closeTopModal()) {
        updateBackButtonState();
        return true;
    }
    if (closeDetailPanel()) {
        updateBackButtonState();
        return true;
    }
    return false;
}

function bindUIEnhancements() {
    if (document.body.dataset.uiEnhancementsBound === 'true') return;
    document.body.dataset.uiEnhancementsBound = 'true';

    document.querySelectorAll('.modal-overlay').forEach(modal => {
        modal.addEventListener('click', (e) => {
            if (e.target === modal) {
                modal.classList.remove('active');
                updateBackButtonState();
            }
        });
    });

    document.addEventListener('keydown', (e) => {
        // FIX v23-6: keyboard navigation
        const activeTag = document.activeElement?.tagName;
        const typing = activeTag === 'INPUT' || activeTag === 'TEXTAREA' || activeTag === 'SELECT';
        if (e.key === 'Enter' && document.activeElement?.id === 'landingSearchInput') {
            e.preventDefault();
            switchView('timeline', getViewButton('timeline'));
            document.getElementById('main-content')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
            return;
        }
        // '/' → activar buscador desde cualquier vista
        if (e.key === '/' && !typing && !e.ctrlKey && !e.metaKey) {
            e.preventDefault();
            const si = document.getElementById('searchInput');
            if (si) { si.focus(); si.select(); }
            return;
        }
        if ((e.altKey || e.metaKey) && e.key === 'ArrowLeft' && !typing) {
            e.preventDefault();
            navigateBack();
            return;
        }
        // ← / → → navegar entre fichas visibles en el panel de detalle
        // BUG-C FIX: ignorar este handler cuando la presentación está activa;
        // la navegación por flechas la gestiona presKeyHandler de forma exclusiva.
        if ((e.key === 'ArrowRight' || e.key === 'ArrowLeft') && currentSpecies && !typing) {
            if (document.getElementById('presOverlay')?.classList.contains('active')) return;
            e.preventDefault();
            const visible = DB.filter(matchesActiveFilters);
            const idx = visible.findIndex(s => s.id === currentSpecies.id);
            if (idx !== -1) {
                const next = e.key === 'ArrowRight' ? visible[idx + 1] : visible[idx - 1];
                if (next) showDetail(next);
            }
            return;
        }
        if (e.key !== 'Escape') return;
        if (closeActiveUI()) e.preventDefault();
    });
}

// FIX #5: toggleModal ya no llama a renderMatrix; openMatrix() es el único punto de entrada
// FIX C-3e: mapa de funciones de limpieza de focus trap por modal (WCAG 2.1 §2.1.2)
const _modalTrapRemovers = {};
/** Elemento que tenía el foco justo antes de abrir un modal */
const _modalFocusTriggers = {};

/**
 * Abre o cierra un modal y gestiona el focus trap.
 * @param {string} id - ID del modal overlay
 */
function toggleModal(id) {
  const modal = document.getElementById(id);
  if (!modal) return;
  const isOpening = !modal.classList.contains('active');

  if (isOpening) {
    // Guardar disparador y activar trap
    _modalFocusTriggers[id] = document.activeElement;
    modal.classList.add('active');
    _modalTrapRemovers[id] = createFocusTrap(modal, _modalFocusTriggers[id]);

    // ── v28: render lazy del comparador al abrir su modal ──────────
    if (id === 'compareModal') {
      requestAnimationFrame(() => {
        try { cmpOnModalOpen(); } catch(e) { if(typeof Logger!=="undefined") Logger.error("toggleModal→cmpOnModalOpen", e); }
      });
    }
  } else {
    // Liberar trap y restaurar foco
    modal.classList.remove('active');
    if (typeof _modalTrapRemovers[id] === 'function') {
      _modalTrapRemovers[id]();
      delete _modalTrapRemovers[id];
    }
  }
  updateBackButtonState();
}

/**
 * Cierra el modal superior activo y libera su trap de foco.
 * @returns {boolean} true si había algún modal activo
 */
function closeTopModal() {
  const modals   = [...document.querySelectorAll('.modal-overlay.active')];
  const modal    = modals[modals.length - 1];
  if (!modal) return false;
  const id = modal.id;
  modal.classList.remove('active');
  if (typeof _modalTrapRemovers[id] === 'function') {
    _modalTrapRemovers[id]();
    delete _modalTrapRemovers[id];
  }
  updateBackButtonState();
  return true;
}

/**
 * FIX B-1 (v32): filas clickables con data-open-species + tabindex.
 * FIX B-4 (v32): barra de acciones con botón "Abrir presentación" y
 *                "Exportar CSV visible" desde el modal de la matriz.
 * FIX B-7 (v32): título del modal actualizado dinámicamente con el
 *                recuento real de DB (no hardcoded "50 Registros").
 */
function renderMatrix() {
    // FIX B-7: actualizar título del modal con recuento real
    const titleEl = document.getElementById('matrixModal-title');
    if (titleEl) titleEl.textContent = `Matriz de Caracteres — ${DB.length} registros`;

    const t = document.getElementById('matrixTableContent');
    if (!t) return;

    // FIX B-4: barra de acciones en la cabecera del modal
    const actionBar = document.getElementById('matrixActionBar');
    if (actionBar && !actionBar.dataset.rendered) {
        actionBar.dataset.rendered = 'true';
        actionBar.innerHTML = `
            <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;padding:0 0 10px;border-bottom:1px solid var(--border);margin-bottom:10px">
                <span style="font-size:0.71rem;font-family:'JetBrains Mono',monospace;color:var(--text-hint);flex:1">
                    Pulsa una fila para abrir la ficha completa · ${DB.length} taxones
                </span>
                <button type="button" class="exam-btn"
                        data-action="openPresentation"
                        style="font-size:0.73rem;padding:5px 12px"
                        aria-label="Abrir modo presentación desde la matriz">
                    ▶ Presentación
                </button>
                <button type="button" class="exam-btn"
                        data-action="exportToCSV"
                        style="font-size:0.73rem;padding:5px 12px"
                        aria-label="Exportar datos visibles a CSV">
                    ↓ CSV
                </button>
            </div>`;
    }

    const EST_MAP = {aceptada:'✓ Aceptada', debatida:'⚠ Debatida', revision:'↺ Revisión'};
    let h = `<thead>
        <tr>
            <th scope="col">#</th>
            <th scope="col">Especie</th>
            <th scope="col">Clado</th>
            <th scope="col">Edad</th>
            <th scope="col">Holotipo</th>
            <th scope="col">CC (cc)</th>
            <th scope="col">Datación</th>
            <th scope="col">Dieta</th>
            <th scope="col">Estado</th>
            <th scope="col">Ficha</th>
        </tr>
    </thead><tbody>`;

    DB.forEach((s, i) => {
        const est       = EST_MAP[s.estado || 'aceptada'] || s.estado;
        const safeId    = escapeHtmlAttr(s.id);
        const safeName  = escapeHtmlText(s.nombre);
        const safeYears = escapeHtmlText(s.anos);
        const safeHolo  = escapeHtmlText(s.holo);
        const safeDat   = escapeHtmlText(s.datacion);
        const safeDiet  = escapeHtmlText(s.dieta || '—');
        const safeCC    = escapeHtmlText(String(s.cc || '—'));
        const safeClado = escapeHtmlText(CLADE_NAMES[s.clado] || s.clado);
        const safeEst   = escapeHtmlText(est);

        // FIX B-1: fila clickable + botón de ficha explícito (accesibilidad)
        h += `<tr class="matrix-row-clickable"
                   data-open-species="${safeId}"
                   role="button"
                   tabindex="0"
                   aria-label="Abrir ficha de ${safeName}"
                   title="Abrir ficha: ${safeName}">
                <td class="matrix-row-index">${i + 1}</td>
                <td class="matrix-row-taxon"><em>${safeName}</em></td>
                <td class="matrix-row-clade">${safeClado}</td>
                <td class="matrix-row-mono">${safeYears}</td>
                <td class="matrix-row-mono">${safeHolo}</td>
                <td class="matrix-row-cc">${safeCC}</td>
                <td>${safeDat}</td>
                <td>${safeDiet}</td>
                <td class="matrix-row-status">${safeEst}</td>
                <td><button type="button" class="matrix-open-btn"
                            data-open-species="${safeId}"
                            aria-label="Abrir ficha de ${safeName}"
                            tabindex="-1">→</button></td>
              </tr>`;
    });

    t.innerHTML = h + '</tbody>';
}

function morphCorpus(sp) {
    return normalizeForSearch([
        sp.descripcion,
        sp.experto?.descripcion_tecnica,
        sp.experto?.anatomia_craneal,
        sp.experto?.anatomia_postcraneal,
        sp.experto?.paleoecologia
    ].filter(Boolean).join(' '));
}

function morphState(sp, key) {
    const txt = morphCorpus(sp);
    if (key === 'sagittal') {
        if (/sin cresta sagital|cresta sagital ausente/.test(txt)) return { state:'absent', label:'Ausente' };
        if (/cresta sagital|sagital compuesta|quilla sagital/.test(txt)) return { state:'present', label:'Presente' };
        return { state:'unknown', label:'No documentada' };
    }
    if (key === 'torus') {
        if (/sin toro supraorbitario|sin torus supraorbitario|arcos superciliares reducidos|toro.*reducido|torus.*reducido/.test(txt)) return { state:'partial', label:'Reducido' };
        if (/toro supraorbitario|torus supraorbitario|arco superciliar|superciliar enorme|supercilios robustos/.test(txt)) return { state:'present', label:'Marcado' };
        return { state:'unknown', label:'No documentado' };
    }
    if (key === 'chin') {
        if (/sin menton|menton ausente/.test(txt)) return { state:'absent', label:'Ausente' };
        if (/menton incipiente/.test(txt)) return { state:'partial', label:'Incipiente' };
        if (/menton|protuberancia mental/.test(txt)) return { state:'present', label:'Presente' };
        return { state:'unknown', label:'No documentado' };
    }
    if (key === 'biped') {
        if (/bipedos obligados|bipedismo plenamente moderno|pie.*moderno|piernas modernas|rodilla valga|arco plantar/.test(txt)) return { state:'present', label:'Obligado / eficiente' };
        if (/biped|bipeda|bipedo|locomocion mixta|hallux abduible|arboreo/.test(txt)) return { state:'partial', label:'Parcial / mixto' };
        if (sp.clado === 'basal') return { state:'unknown', label:'Debatido' };
        return { state:'unknown', label:'No documentado' };
    }
    if (key === 'cc') {
        if (!sp.cc) return { state:'unknown', label:'Sin dato', pct:0 };
        const pct = Math.min(100, Math.round((sp.cc / 1600) * 100));
        if (sp.cc >= 1100) return { state:'present', label:`Alta (${sp.cc} cc)`, pct };
        if (sp.cc >= 600) return { state:'partial', label:`Media (${sp.cc} cc)`, pct };
        return { state:'absent', label:`Baja (${sp.cc} cc)`, pct };
    }
    return { state:'unknown', label:'No documentado' };
}

// ══════════════════════════════════════════════════════════════════════════
//  COMPARADOR MULTI-ESPECIE — PaleoBot
//  Arquitectura: estado central cmpSelectedIds[] → render reactivo
//  Máximo 6 taxones. Mínimo 2 para activar el render completo.
//  Fuentes taxonómicas: CHARACTER_CATALOG, CHARACTER_BASE, CHARACTER_OVERRIDES
//  Cronología: sp.val_time (Ma), sp.anos (etiqueta legible)
// ══════════════════════════════════════════════════════════════════════════

/** @type {string[]} IDs de las especies actualmente seleccionadas en el comparador */
let cmpSelectedIds = [];

/** Máximo de especies comparables simultáneamente (legibilidad visual) */
const CMP_MAX = 6;

/**
 * Colores de las paletas de múltiples series para el radar (orden estable).
 * Se asignan por posición, no por clado, para máxima visibilidad entre series.
 */
const CMP_SERIES_COLORS = [
  '#1a4fa0', '#0a6b49', '#aa1f1f', '#c07800',
  '#6a3db0', '#0e7f9e'
];

/** Presets curriculares predefinidos (DOI relevantes en comentarios) */
const CMP_PRESETS = {
  // Evolución del bipedismo — cubre el continuo desde arborealismo hasta locomoción moderna
  // Ref: Lovejoy 1988 (doi:10.1126/science.239.4845.1284); Haile-Selassie 2001 (doi:10.1038/35097529)
  bipedismo:    ['proconsul', 'ramidus', 'afarensis', 'ergaster', 'sapiens'],
  // Clado Paranthropus — los tres taxones robustos
  // Ref: Wood & Strait 2004 (doi:10.1002/evan.20017)
  paranthropus: ['aethiopicus', 'boisei', 'robustus'],
  // Homo temprano — diversificación inicial del género
  // Ref: Leakey et al. 2012 (doi:10.1038/nature11322)
  homo_temprano: ['habilis', 'rudolfensis', 'ergaster', 'georgicus'],
  // Homo arcaico de distribución global — midpleistocene
  // Ref: Mounier & Mirazón Lahr 2019 (doi:10.1371/journal.pone.0208903)
  arcantropo:   ['heidelbergensis', 'rhodesiensis', 'neander', 'denisova'],
  // Enanismo insular — dos casos bien documentados
  // Ref: Brown et al. 2004 (doi:10.1038/nature02999); Détroit et al. 2019 (doi:10.1038/s41586-019-1067-9)
  islas:        ['flores', 'luzon'],
  // Hominoideos del Mioceno — origen del plan corporal humano
  // Ref: Moyà-Solà et al. 2004 (doi:10.1126/science.1096393)
  mioceno:      ['proconsul', 'morotopithecus', 'dryopithecus', 'pierolapithecus', 'nakalipithecus']
};

// ── A. Estado y mutaciones ────────────────────────────────────────────────

/**
 * Añade una especie al comparador si no está ya y no se ha superado el máximo.
 * @param {string} id - ID del taxón (campo sp.id en DB)
 */
function cmpAddSpecies(id) {
  if (!id) return;
  if (cmpSelectedIds.includes(id)) {
    Logger.log(`cmpAddSpecies: ${id} ya está en la selección.`);
    return;
  }
  if (cmpSelectedIds.length >= CMP_MAX) {
    const dd = document.getElementById('cmpPickerDropdown');
    if (dd) {
      const warn = document.createElement('div');
      warn.className = 'cmp-picker-empty';
      warn.style.color = '#aa1f1f';
      warn.textContent = `Máximo ${CMP_MAX} taxones. Elimina uno para añadir otro.`;
      dd.prepend(warn);
      setTimeout(() => warn.remove(), 2500);
    }
    return;
  }
  const sp = DB.find(s => s.id === id);
  if (!sp) return;
  cmpSelectedIds = [...cmpSelectedIds, id];
  // Limpiar campo de búsqueda y cerrar dropdown
  const inp = document.getElementById('cmpPickerInput');
  if (inp) { inp.value = ''; inp.setAttribute('aria-expanded', 'false'); }
  const dd = document.getElementById('cmpPickerDropdown');
  if (dd) dd.classList.remove('open');
  _cmpRefresh();
}

/**
 * Elimina una especie del comparador.
 * @param {string} id - ID del taxón a eliminar
 */
function cmpRemoveSpecies(id) {
  cmpSelectedIds = cmpSelectedIds.filter(x => x !== id);
  _cmpRefresh();
}

/**
 * Aplica un preset curricular, sustituyendo la selección actual.
 * Solo incluye IDs que existan en DB.
 * @param {string} presetKey - Clave de CMP_PRESETS
 */
function cmpApplyPreset(presetKey) {
  const ids = (CMP_PRESETS[presetKey] || []).filter(id => DB.find(s => s.id === id));
  if (!ids.length) return;
  cmpSelectedIds = ids.slice(0, CMP_MAX);
  _cmpRefresh();
}

// ── B. Picker / buscador ──────────────────────────────────────────────────

/**
 * Inicializa el comparador multi-especie.
 * SOLO prepara el estado inicial — NO renderiza todavía para no
 * bloquear init() con posibles errores de runtime en el render.
 * El render completo ocurre en cmpOnModalOpen() cuando el usuario
 * abre el modal por primera vez.
 */
function initComparePicker() {
  // Selección por defecto pedagógicamente relevante:
  // Au. afarensis + H. neanderthalensis = contraste anatómico máximo
  cmpSelectedIds = ['afarensis', 'neander'];
  // Solo actualizamos los chips (operación segura, sin canvas ni cladística)
  try { _cmpRenderChips(); } catch(e) { Logger.error('initComparePicker chips', e); }
}

/**
 * Llamado cuando el usuario abre el modal de comparación.
 * Ejecuta el render completo de forma lazy y segura.
 * @param {boolean} [force=false] — forzar re-render aunque ya esté visible
 */
function cmpOnModalOpen(force) {
  try {
    _cmpRenderChips();
    renderMultiComparison();
  } catch(e) {
    Logger.error('cmpOnModalOpen', e);
    const res = document.getElementById('compareResult');
    if (res) res.innerHTML = `<div class="cmp-status-msg">
      <strong>⚠ Error al renderizar la comparación</strong>
      ${escapeHtmlText(e.message)}. Prueba a recargar el archivo.
    </div>`;
  }
}

/**
 * Filtra y muestra el dropdown del picker según el texto introducido.
 * @param {string} query - Texto de búsqueda del usuario
 */
function cmpFilterDropdown(query) {
  const dd = document.getElementById('cmpPickerDropdown');
  const inp = document.getElementById('cmpPickerInput');
  if (!dd) return;
  /* v64-fix: posicionamiento dinámico para position:fixed (escapa del overflow:hidden del modal) */
  if (inp) {
    const rect = inp.getBoundingClientRect();
    dd.style.top    = (rect.bottom + 4) + 'px';
    dd.style.left   = rect.left + 'px';
    dd.style.width  = rect.width + 'px';
    dd.style.right  = 'auto';
  }
  const q = String(query || '').toLowerCase().trim();
  const CLADE_NM = { basal: 'Basal/Mioceno', australo: 'Australopithecus', paran: 'Paranthropus', homo: 'Homo' };
  let matches = DB.filter(sp => {
    if (!q) return true;
    return sp.nombre.toLowerCase().includes(q) || (sp.anos || '').toLowerCase().includes(q);
  }).slice(0, 30); // Limitar a 30 resultados para rendimiento

  if (!matches.length) {
    dd.innerHTML = `<div class="cmp-picker-empty">Sin resultados para «${escapeHtmlText(query)}»</div>`;
  } else {
    dd.innerHTML = matches.map(sp => {
      const added = cmpSelectedIds.includes(sp.id) ? 'already-added' : '';
      const col = CLADE_COLORS[sp.clado] || '#888';
      return `<div class="cmp-picker-opt ${added}" role="option"
                   data-cmp-add="${escapeHtmlAttr(sp.id)}"
                   aria-label="${escapeHtmlAttr(sp.nombre)} ${escapeHtmlAttr(sp.anos || '')} ${added ? '(ya seleccionado)' : ''}"
                   tabindex="${added ? '-1' : '0'}">
        <span class="cmp-picker-opt-dot" style="background:${col}" aria-hidden="true"></span>
        <span style="font-style:italic">${escapeHtmlText(sp.nombre)}</span>
        <span style="font-size:0.72rem;color:var(--text-sec)">${escapeHtmlText(CLADE_NM[sp.clado] || sp.clado)}</span>
        <span class="cmp-picker-opt-time">${escapeHtmlText(sp.anos || '')}</span>
        ${added ? '<span style="font-size:0.7rem;color:var(--text-hint);margin-left:auto">✓</span>' : ''}
      </div>`;
    }).join('');
  }
  dd.classList.add('open');
  if (inp) inp.setAttribute('aria-expanded', 'true');
}

// ── C. Renderizado de chips ──────────────────────────────────────────────

/**
 * Actualiza la fila de chips según cmpSelectedIds.
 * Incluye cuenta legible por lector de pantalla.
 */
function _cmpRenderChips() {
  const row = document.getElementById('cmpChipsRow');
  const countLbl = document.getElementById('cmpCountLabel');
  if (!row) return;

  const n = cmpSelectedIds.length;
  if (countLbl) countLbl.textContent = `${n} / ${CMP_MAX} seleccionada${n !== 1 ? 's' : ''}`;

  if (!n) {
    row.innerHTML = '<span class="cmp-chip-ph">Añade al menos dos taxones para comparar…</span>';
    return;
  }

  row.innerHTML = cmpSelectedIds.map(id => {
    const sp = DB.find(s => s.id === id);
    if (!sp) return '';
    const col = CLADE_COLORS[sp.clado] || '#888';
    return `<span class="cmp-chip ${escapeHtmlAttr(sp.clado)}" role="listitem">
      <span class="cmp-chip-dot" style="background:${col}" aria-hidden="true"></span>
      <span class="cmp-chip-name">${escapeHtmlText(sp.nombre)}</span>
      <button type="button" class="cmp-chip-rm" data-cmp-remove="${escapeHtmlAttr(sp.id)}"
              aria-label="Eliminar ${escapeHtmlAttr(sp.nombre)} del comparador"
              title="Eliminar">✕</button>
    </span>`;
  }).join('');
}

// ── D. Orquestador principal ─────────────────────────────────────────────

/**
 * Refresca chips + result en respuesta a cualquier cambio de estado.
 */
function _cmpRefresh() {
  _cmpRenderChips();
  renderMultiComparison();
}

/**
 * Renderiza la comparación completa para las especies en cmpSelectedIds.
 * Estructura de secciones:
 *   1. Cabeceras de taxón
 *   2. Radar morfofuncional (canvas SVG)
 *   3. Barras de capacidad craneal
 *   4. Tabla de rasgos diagnósticos
 *   5. Grid visual morfológico (5 caracteres × N taxones)
 *   6. Cladística N-especie
 *   7. Anatomía craneal + debate (textos paralelos)
 */
function renderMultiComparison() {
  const res = document.getElementById('compareResult');
  if (!res) return;

  const n = cmpSelectedIds.length;

  // ── Caso límite: < 2 especies ──────────────────────────────────────
  if (n < 2) {
    res.innerHTML = `<div class="cmp-status-msg">
      <strong>⚖ Comparador multi-especie</strong>
      ${n === 0
        ? 'Selecciona entre 2 y 6 taxones, o elige un preset curricular.'
        : 'Añade al menos un taxón más para iniciar la comparación.'}
    </div>`;
    return;
  }

  // ── Resolver objetos especie ──────────────────────────────────────
  const species = cmpSelectedIds.map(id => DB.find(s => s.id === id)).filter(Boolean);
  if (species.length < 2) return;

  // ── Asignar colores de serie ────────────────────────────────────
  const seriesColors = {};
  species.forEach((sp, i) => { seriesColors[sp.id] = CMP_SERIES_COLORS[i % CMP_SERIES_COLORS.length]; });

  const CLADE_NM = { basal: 'Basal/Mioceno', australo: 'Australopithecus', paran: 'Paranthropus', homo: 'Homo' };
  const ESTADO_L = { aceptada: 'Aceptada ✓', debatida: 'Debatida [DEBATIDO]', revision: 'En revisión ↺' };

  try {
    res.innerHTML = `
      <!-- 1. Cabeceras -->
      <div class="cmp-headers-n" role="list" aria-label="Taxones comparados">
        ${species.map(sp => `
          <article class="cmp-card ${escapeHtmlAttr(sp.clado)}" role="listitem">
            <div class="cmp-card-kicker" style="color:${seriesColors[sp.id]}">${CLADE_NM[sp.clado] || sp.clado}</div>
            <div class="cmp-card-name" lang="la">${escapeHtmlText(sp.nombre)}</div>
            <div class="cmp-card-sub">${escapeHtmlText(sp.anos || '—')} · 📍 ${escapeHtmlText(sp.ubicacion || '—')}</div>
            ${sp.cc ? `<div class="cmp-card-sub">🧠 ${sp.cc} cc</div>` : ''}
          </article>`).join('')}
      </div>

      <!-- 2. Radar morfofuncional -->
      <div class="cmp-section-title">Perfil morfofuncional comparado (radar de 6 ejes)</div>
      <div class="cmp-radar-wrap">
        <canvas class="cmp-radar-canvas" id="cmpRadarCanvas" width="310" height="310"
                role="img"
                aria-label="Radar de 6 ejes morfofuncionales: encefalización, bipedismo, tecnología lítica, robustez masticatoria, arborealismo y conducta simbólica. ${species.map(sp => sp.nombre).join(', ')}.">
          <p>Tu navegador no soporta Canvas HTML5. Los datos del radar están disponibles en la tabla de rasgos debajo.</p>
        </canvas>
        <div class="cmp-radar-legend" role="list" aria-label="Leyenda del radar">
          ${species.map(sp => `
            <div class="cmp-radar-leg" role="listitem">
              <span class="cmp-radar-swatch" style="background:${seriesColors[sp.id]}" aria-hidden="true"></span>
              <span class="cmp-radar-sp" lang="la">${escapeHtmlText(sp.nombre)}</span>
            </div>`).join('')}
        </div>
      </div>

      <!-- 2b. Comparador 3D didáctico -->
      <div class="cmp-section-title">Comparador 3D didáctico</div>
      ${_cmpRender3DComparativeViewer(species, seriesColors)}

      <!-- 3. Barras CC -->
      ${_cmpRenderCCBars(species, seriesColors)}

      <!-- 4. Tabla de rasgos -->
      <div class="cmp-section-title">Rasgos diagnósticos comparados</div>
      ${_cmpRenderTraitsTable(species, ESTADO_L, CLADE_NM)}

      <!-- 5. Grid visual morfológico -->
      <div class="cmp-section-title">Morfología craneal visible (5 caracteres)</div>
      ${_cmpRenderMorphGridN(species)}

      <!-- 6. Cladística N -->
      <div class="cmp-section-title">Lectura cladística didáctica</div>
      ${_cmpRenderCladisticsN(species, seriesColors)}

      <!-- 7. Anatomía craneal + debate -->
      <div class="cmp-section-title">Descripción craneal comparada</div>
      <div class="cmp-text-grid-n" style="grid-template-columns:repeat(${Math.min(species.length, 3)},1fr)">
        ${species.map(sp => `
          <div class="cmp-text-card">
            <div style="font-size:0.7rem;font-weight:800;text-transform:uppercase;letter-spacing:0.06em;color:${seriesColors[sp.id]};margin-bottom:6px;"
                 lang="la">${escapeHtmlText(sp.nombre)}</div>
            ${safeGlossary(sp.experto?.anatomia_craneal || '<em>Sin datos de anatomía craneal en esta ficha.</em>')}
          </div>`).join('')}
      </div>

      <div class="cmp-section-title">Debates taxonómicos y filogenéticos</div>
      <div class="cmp-text-grid-n" style="grid-template-columns:repeat(${Math.min(species.length, 3)},1fr)">
        ${species.map(sp => `
          <div class="debate-box">
            <p class="cmp-debate-text" lang="la"><strong style="font-style:normal;font-size:0.78rem;color:var(--text-hint)">${escapeHtmlText(sp.nombre)}: </strong>
            ${safeGlossary(sp.experto?.debate || '—')}</p>
          </div>`).join('')}
      </div>
    `;

    // Dibujar radar tras insertar el canvas en el DOM
    requestAnimationFrame(() => {
      const canvas = document.getElementById('cmpRadarCanvas');
      if (canvas) drawRadarChartN(canvas, species, seriesColors);
    });

  } catch (err) {
    Logger.error('renderMultiComparison', err);
    res.innerHTML = `<div class="cmp-status-msg"><strong>Error al renderizar la comparación</strong>
      Revisa la consola con <code>window.__PALEOBOT_DEBUG = true</code> para más detalles.</div>`;
  }
}

// ── E. Secciones internas ────────────────────────────────────────────────

/**
 * Genera las barras de capacidad craneal para N especies + referencia H. sapiens.
 * @param {Object[]} species
 * @param {Object} seriesColors
 * @returns {string} HTML
 */
function _cmp3DMetricProfile(sp) {
  const txt = morphCorpus(sp);
  const ccNorm = sp.cc ? Math.max(22, Math.min(100, Math.round((sp.cc / 1500) * 100))) : (sp.clado === 'homo' ? 64 : 34);
  const torus = morphState(sp, 'torus');
  const chin = morphState(sp, 'chin');
  const sagittal = morphState(sp, 'sagittal');
  const robustHints = [
    /paranthropus|boisei|robustus|aethiopicus/.test(String(sp.id || '').toLowerCase()),
    /mandibula robusta|masticatoria|molares grandes|dientes grandes|cascanueces|crest[a-z]* sagital/.test(txt),
    sp.clado === 'paran'
  ].filter(Boolean).length;
  const prognathism = Math.max(12, Math.min(88,
    (sp.clado === 'homo' ? 28 : sp.clado === 'paran' ? 58 : sp.clado === 'australo' ? 52 : 46)
    + (/prognat|rostro proyectado/.test(txt) ? 18 : 0)
    - (/rostro plano|cara plana|ortognat/.test(txt) ? 16 : 0)
  ));
  const brow = torus.state === 'present' ? 82 : torus.state === 'partial' ? 48 : 18;
  const jaw = Math.min(100, 26 + robustHints * 22 + (sp.clado === 'paran' ? 18 : 0));
  const vault = Math.max(24, Math.min(96, ccNorm + (sp.clado === 'homo' ? 10 : 0) - (sagittal.state === 'present' ? 9 : 0)));
  const chinValue = chin.state === 'present' ? 82 : chin.state === 'partial' ? 48 : 14;
  return {
    vault,
    prognathism,
    brow,
    jaw,
    chin: chinValue,
    sagittal: sagittal.state === 'present',
    ccLabel: sp.cc ? `${sp.cc} cc` : 'sin dato'
  };
}

function _cmp3DSkullSvg(sp, color) {
  const m = _cmp3DMetricProfile(sp);
  const vaultW = 58 + m.vault * 0.42;
  const vaultH = 54 + m.vault * 0.28;
  const faceX = 100 + m.prognathism * 0.32;
  const browW = 22 + m.brow * 0.28;
  const jawW = 34 + m.jaw * 0.42;
  const jawY = 105 - m.chin * 0.08;
  const chinDrop = 10 + m.chin * 0.13;
  const frontalW = 38 + m.vault * 0.34;
  const frontalH = 56 + m.vault * 0.26;
  const mandibleW = 34 + m.jaw * 0.33;
  return `<svg class="cmp-3d-model" viewBox="0 0 230 170" role="img" aria-label="Modelo craneal esquematico de ${escapeHtmlAttr(sp.nombre)}">
    <defs>
      <linearGradient id="cmp3dGrad-${escapeHtmlAttr(sp.id)}" x1="0" x2="1" y1="0" y2="1">
        <stop offset="0" stop-color="#fff7df"/>
        <stop offset="0.52" stop-color="${escapeHtmlAttr(color)}" stop-opacity="0.62"/>
        <stop offset="1" stop-color="#3a2d1e"/>
      </linearGradient>
      <radialGradient id="cmp3dGlow-${escapeHtmlAttr(sp.id)}" cx="42%" cy="28%" r="70%">
        <stop offset="0" stop-color="#fff" stop-opacity="0.65"/>
        <stop offset="0.7" stop-color="#fff" stop-opacity="0.04"/>
        <stop offset="1" stop-color="#000" stop-opacity="0.22"/>
      </radialGradient>
    </defs>
    <ellipse cx="78" cy="82" rx="${vaultW.toFixed(1)}" ry="${vaultH.toFixed(1)}" fill="url(#cmp3dGrad-${escapeHtmlAttr(sp.id)})" stroke="rgba(255,255,255,0.55)" stroke-width="2"/>
    <ellipse cx="70" cy="68" rx="${(vaultW * 0.72).toFixed(1)}" ry="${(vaultH * 0.72).toFixed(1)}" fill="url(#cmp3dGlow-${escapeHtmlAttr(sp.id)})"/>
    ${m.sagittal ? `<path d="M54 28 C70 12 96 12 112 31" fill="none" stroke="#fff7df" stroke-width="5" stroke-linecap="round" opacity="0.72"/>` : ''}
    <path d="M102 72 C${faceX.toFixed(1)} 70 ${(faceX + 18).toFixed(1)} 88 ${(faceX + 8).toFixed(1)} 103 C${(faceX - 4).toFixed(1)} 116 118 118 102 111" fill="rgba(255,247,223,0.82)" stroke="rgba(255,255,255,0.48)" stroke-width="1.5"/>
    <rect x="95" y="72" width="${browW.toFixed(1)}" height="${(5 + m.brow * 0.08).toFixed(1)}" rx="4" fill="#3b2b1f" opacity="${(0.35 + m.brow / 160).toFixed(2)}"/>
    <path d="M78 ${jawY.toFixed(1)} C${(84 + jawW * 0.2).toFixed(1)} ${(126 + chinDrop * 0.1).toFixed(1)} ${(112 + jawW * 0.36).toFixed(1)} ${(126 + chinDrop * 0.16).toFixed(1)} ${(125 + jawW * 0.22).toFixed(1)} ${(112 + chinDrop).toFixed(1)}" fill="none" stroke="rgba(255,247,223,0.92)" stroke-width="${(5 + m.jaw * 0.045).toFixed(1)}" stroke-linecap="round"/>
    <ellipse cx="61" cy="82" rx="8" ry="11" fill="#10202a" opacity="0.56"/>
    <ellipse cx="116" cy="92" rx="5" ry="8" fill="#10202a" opacity="0.45"/>
    <g transform="translate(160 18)">
      <ellipse cx="32" cy="54" rx="${frontalW.toFixed(1)}" ry="${frontalH.toFixed(1)}" fill="url(#cmp3dGrad-${escapeHtmlAttr(sp.id)})" opacity="0.72" stroke="rgba(255,255,255,0.42)" stroke-width="1.5"/>
      <rect x="${(32 - browW * 0.35).toFixed(1)}" y="55" width="${(browW * 0.7).toFixed(1)}" height="${(5 + m.brow * 0.06).toFixed(1)}" rx="4" fill="#2e2119" opacity="0.5"/>
      <path d="M${(32 - mandibleW / 2).toFixed(1)} 100 Q32 ${(116 + chinDrop * 0.22).toFixed(1)} ${(32 + mandibleW / 2).toFixed(1)} 100" fill="none" stroke="rgba(255,247,223,0.84)" stroke-width="${(4 + m.jaw * 0.035).toFixed(1)}" stroke-linecap="round"/>
    </g>
  </svg>`;
}

function _cmpRender3DComparativeViewer(species, seriesColors) {
  if (!species.length) return '<div class="cmp-3d-empty">Selecciona taxones para activar el comparador 3D.</div>';
  const metrics = [
    ['Boveda', 'vault'],
    ['Prognat.', 'prognathism'],
    ['Toro', 'brow'],
    ['Mandib.', 'jaw']
  ];
  return `<div class="cmp-3d-stage">
    <div class="cmp-3d-head">
      <div>
        <strong>Modelos volumetricos esquematicos</strong>
        <span>No son reconstrucciones forenses ni mallas reales: traducen rasgos documentados a volumen visual para comparar boveda craneal, prognatismo, toro supraorbitario y robustez mandibular.</span>
      </div>
    </div>
    <div class="cmp-3d-grid">
      ${species.map((sp, index) => {
        const color = seriesColors[sp.id] || CLADE_COLORS[sp.clado] || '#f0bd4d';
        const m = _cmp3DMetricProfile(sp);
        return `<article class="cmp-3d-card" style="--rot:${index % 2 ? 18 : -18}deg">
          <div class="cmp-3d-title"><span class="cmp-3d-dot" style="background:${escapeHtmlAttr(color)}"></span><em>${escapeHtmlText(sp.nombre)}</em></div>
          <div class="cmp-3d-scene">
            ${_cmp3DSkullSvg(sp, color)}
            <div class="cmp-3d-axis"><i></i> lateral + frontal</div>
          </div>
          <div class="cmp-3d-metrics">
            ${metrics.map(([label, key]) => `<div class="cmp-3d-meter"><b>${label}</b><span class="cmp-3d-track"><span style="width:${Math.round(m[key])}%;background:${escapeHtmlAttr(color)}"></span></span><span>${Math.round(m[key])}</span></div>`).join('')}
          </div>
        </article>`;
      }).join('')}
    </div>
    <div class="cmp-3d-note"><strong>Lectura:</strong> valores altos no significan superioridad evolutiva. Indican intensidad relativa del rasgo en esta visualización didáctica y deben contrastarse con la ficha, el yacimiento y la bibliografía.</div>
  </div>`;
}

function _cmpRenderCCBars(species, seriesColors) {
  const withCC = species.filter(sp => sp.cc);
  if (!withCC.length) return '';

  const MAX_CC = 1800;
  const REF_CC = 1380; // H. sapiens media moderna (Holloway 1973)
  const sapiens = DB.find(s => s.id === 'sapiens');
  const refEntry = sapiens ? [{ sp: sapiens, cc: REF_CC, isRef: true }] : [];
  const allRows = [...withCC.map(sp => ({ sp, cc: sp.cc, isRef: false })), ...refEntry];

  const rows = allRows.map(({ sp, cc, isRef }) => {
    const pct = Math.min(100, Math.round((cc / MAX_CC) * 100));
    const col = isRef ? '#9ab3d4' : seriesColors[sp.id] || CLADE_COLORS[sp.clado] || '#888';
    const alpha = isRef ? 0.45 : 0.82;
    const nameLbl = isRef
      ? `<em>${escapeHtmlText(sp.nombre)}</em> <span class="cmp-ref-note">(referencia)</span>`
      : `<em>${escapeHtmlText(sp.nombre)}</em>`;
    return `<div class="cmp-cc-row-n">
      <div class="cmp-cc-label">${nameLbl}</div>
      <div class="cmp-cc-track">
        <div class="cmp-cc-bar" style="width:${pct}%;background:${col};opacity:${alpha}"></div>
      </div>
      <div class="cmp-cc-num">${cc} cc</div>
    </div>`;
  }).join('');

  const hidden = species.length - withCC.length;
  return `<div class="cmp-section-title">Capacidad craneal comparada</div>
    <div class="cmp-cc-chart-n">${rows}
    ${hidden > 0 ? `<p class="cmp-empty-note" style="margin-top:6px">* ${hidden} taxón(es) sin dato de CC disponible.</p>` : ''}
    </div>`;
}

/**
 * Genera la tabla de rasgos diagnósticos para N especies.
 * @param {Object[]} species
 * @param {Object} estadoLabel
 * @param {Object} cladeNames
 * @returns {string} HTML
 */
function _cmpRenderTraitsTable(species, estadoLabel, cladeNames) {
  const rows = [
    { label: 'Cronología', fn: sp => escapeHtmlText(sp.anos || '—') },
    { label: 'Datación', fn: sp => escapeHtmlText(sp.datacion || '—') },
    { label: 'Cap. craneal', fn: sp => sp.cc ? `${sp.cc} cc` : '<span class="cmp-empty-note">sin dato</span>' },
    { label: 'Holotipo', fn: sp => `<span class="cmp-mono-value">${escapeHtmlText(sp.holo || '—')}</span>` },
    { label: 'Dieta', fn: sp => escapeHtmlText(sp.dieta || '—') },
    { label: 'Herramientas', fn: sp => escapeHtmlText(sp.herramientas || '—') },
    { label: 'Ubicación', fn: sp => escapeHtmlText(sp.ubicacion || '—') },
    { label: 'Clado', fn: sp => cladeNames[sp.clado] || sp.clado },
    { label: 'Estado tax.', fn: sp => estadoLabel[sp.estado || 'aceptada'] || sp.estado },
  ];

  const header = `<tr><th scope="col">Rasgo</th>${species.map(sp => `<th scope="col" lang="la"><em>${escapeHtmlText(sp.nombre)}</em></th>`).join('')}</tr>`;
  const body = rows.map(row =>
    `<tr>
      <td>${row.label}</td>
      ${species.map(sp => `<td>${row.fn(sp)}</td>`).join('')}
    </tr>`
  ).join('');

  return `<table class="cmp-table-n" aria-label="Tabla comparativa de rasgos diagnósticos">
    <caption style="display:none">Comparación de rasgos diagnósticos: ${species.map(sp => sp.nombre).join(', ')}</caption>
    <thead>${header}</thead>
    <tbody>${body}</tbody>
  </table>`;
}

/**
 * Genera el grid morfológico visual para 5 caracteres × N especies.
 * Usa la misma lógica que el comparador de 2, generalizada para N.
 * @param {Object[]} species
 * @returns {string} HTML
 */
function _cmpRenderMorphGridN(species) {
  const chars = [
    { key: 'sagittal', label: 'Cresta sagital' },
    { key: 'torus',    label: 'Toro supraorbitario' },
    { key: 'chin',     label: 'Mentón óseo' },
    { key: 'biped',    label: 'Bipedismo' },
    { key: 'cc',       label: 'CC relativa' }
  ];
  const n = species.length;
  const gridCols = `grid-template-columns: 1.1fr ${Array(n).fill('1fr').join(' ')}`;

  const headerRow = `<div class="cmp-vg-head" style="font-size:0.7rem">Carácter</div>
    ${species.map(sp => `<div class="cmp-vg-head" lang="la"><em>${escapeHtmlText(sp.nombre)}</em></div>`).join('')}`;

  const dataRows = chars.map((ch, idx) => {
    const isLast = idx === chars.length - 1;
    const lastCls = isLast ? ' last-row' : '';
    return `<div class="cmp-vg-row-lbl${lastCls}">
        <span class="cmp-visual-icon" aria-hidden="true">${morphIcon(ch.key)}</span>${ch.label}
      </div>
      ${species.map(sp => {
        const st = morphState(sp, ch.key);
        const gauge = ch.key === 'cc'
          ? `<span class="cmp-cc-gauge" aria-hidden="true"><span style="width:${st.pct || 0}%;background:${CLADE_COLORS[sp.clado] || 'var(--accent)'}"></span></span>`
          : '';
        return `<div class="cmp-vg-cell${lastCls}">
          <span class="cmp-state ${escapeHtmlAttr(st.state)}">${morphIcon(stateIconName(st.state))}${escapeHtmlText(st.label)}</span>
          ${gauge}
        </div>`;
      }).join('')}`;
  }).join('');

  return `<div class="cmp-visual-grid-n" style="${gridCols}" role="table" aria-label="Grid morfológico comparado">
    ${headerRow}${dataRows}
  </div>`;
}

/**
 * Calcula el perfil de 6 ejes morfofuncionales para el radar.
 * Ejes: encefalización, bipedismo, tecnología lítica,
 *       robustez masticatoria, arborealismo, conducta simbólica.
 * @param {Object} sp - Objeto especie
 * @returns {{enceph:number, biped:number, litika:number, masticacion:number, arborealismo:number, simbolismo:number}}
 */
function getMorphRadarScore(sp) {
  const prof = getCharacterProfile(sp);

  // 1. Encefalización — escala lineal 100 cc (0) → 1600 cc (1)
  const enceph = sp.cc ? Math.min(1, Math.max(0, (sp.cc - 100) / 1500)) : 0.12;

  // 2. Bipedismo — de morphState (deriva del corpus textual de la ficha)
  const bSt = morphState(sp, 'biped').state;
  const biped = bSt === 'present' ? 1 : bSt === 'partial' ? 0.5 : 0.08;

  // 3. Tecnología lítica — jerarquía: achelense > olduvayense > ninguna
  const litika = prof.has('acheulean') ? 1 : prof.has('tool_use') ? 0.58 : 0;

  // 4. Robustez masticatoria — suma ponderada de 3 caracteres
  const mastRaw = (prof.has('postcanine_megadontia') ? 1 : 0)
                + (prof.has('masticatory_robusticity') ? 0.65 : 0)
                + (prof.has('sagittal_crest') ? 0.5 : 0);
  const masticacion = Math.min(1, mastRaw / 2.15);

  // 5. Arborealismo — suma ponderada de 3 caracteres
  const arborRaw = (prof.has('arboreal_quadrupedy') ? 1 : 0)
                 + (prof.has('marked_arborealism') ? 0.65 : 0)
                 + (prof.has('curved_phalanges') ? 0.4 : 0);
  const arborealismo = Math.min(1, arborRaw / 2.05);

  // 6. Conducta simbólica — binarizado con nivel intermedio para conducta funeraria
  const simbolismo = prof.has('symbolic_behavior') ? 1 : prof.has('possible_ritual') ? 0.5 : 0;

  return { enceph, biped, litika, masticacion, arborealismo, simbolismo };
}

/**
 * Dibuja el radar morfofuncional de 6 ejes en el canvas dado.
 * Implementación pura Canvas 2D, sin dependencias externas.
 * @param {HTMLCanvasElement} canvas
 * @param {Object[]} species
 * @param {Object} seriesColors - { id → color }
 */
function drawRadarChartN(canvas, species, seriesColors) {
  if (!canvas || !canvas.getContext) return;

  const ctx = canvas.getContext('2d');
  const DPR = window.devicePixelRatio || 1;
  const SIZE = 310;
  canvas.width  = SIZE * DPR;
  canvas.height = SIZE * DPR;
  canvas.style.width  = SIZE + 'px';
  canvas.style.height = SIZE + 'px';
  ctx.scale(DPR, DPR);

  const cx = SIZE / 2, cy = SIZE / 2 + 6;
  const R  = 108; // radio máximo del radar
  const N_AXES = 6;
  const AXES_LABELS = ['Encefalización', 'Bipedismo', 'Tecnología', 'Robustez', 'Arborealismo', 'Simbolismo'];
  const AXES_KEYS   = ['enceph', 'biped', 'litika', 'masticacion', 'arborealismo', 'simbolismo'];

  /** Ángulo del eje i (empezando por arriba, sentido horario) */
  const axAngle = i => (2 * Math.PI * i / N_AXES) - Math.PI / 2;

  /** Punto en el radio r del eje i */
  const axPoint = (i, r) => ({
    x: cx + r * Math.cos(axAngle(i)),
    y: cy + r * Math.sin(axAngle(i))
  });

  // ── Fondo ─────────────────────────────────────────────────────────
  ctx.fillStyle = '#faf9f7';
  ctx.fillRect(0, 0, SIZE, SIZE);

  // ── Círculos de referencia (0.25, 0.50, 0.75, 1.0) ────────────────
  [0.25, 0.5, 0.75, 1.0].forEach(frac => {
    ctx.beginPath();
    for (let i = 0; i < N_AXES; i++) {
      const p = axPoint(i, R * frac);
      i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y);
    }
    ctx.closePath();
    ctx.strokeStyle = frac === 1.0 ? '#d8d4cc' : '#e8e4de';
    ctx.lineWidth = frac === 1.0 ? 1.5 : 1;
    ctx.setLineDash(frac < 1.0 ? [3, 3] : []);
    ctx.stroke();
    ctx.setLineDash([]);
    // Etiqueta de escala
    if (frac < 1.0) {
      const lp = axPoint(0, R * frac);
      ctx.fillStyle = '#a0a8b4';
      ctx.font = `9px ${getComputedStyle(document.body).getPropertyValue('--font-mono') || 'monospace'}`;
      ctx.textAlign = 'left';
      ctx.fillText((frac * 100).toFixed(0) + '%', lp.x + 3, lp.y - 2);
    }
  });

  // ── Ejes ──────────────────────────────────────────────────────────
  for (let i = 0; i < N_AXES; i++) {
    const p = axPoint(i, R);
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(p.x, p.y);
    ctx.strokeStyle = '#d0ccc4';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Etiqueta del eje
    const labelR = R + 18;
    const lp = axPoint(i, labelR);
    ctx.fillStyle = '#4a5a6e';
    ctx.font = `bold 10px ${getComputedStyle(document.body).getPropertyValue('--font-mono') || 'monospace'}`;
    ctx.textAlign = lp.x < cx - 4 ? 'right' : lp.x > cx + 4 ? 'left' : 'center';
    ctx.textBaseline = lp.y < cy - 4 ? 'bottom' : lp.y > cy + 4 ? 'top' : 'middle';
    ctx.fillText(AXES_LABELS[i], lp.x, lp.y);
  }
  ctx.textBaseline = 'alphabetic';

  // ── Polígonos de cada especie ─────────────────────────────────────
  species.forEach((sp, idx) => {
    const scores = getMorphRadarScore(sp);
    const col = seriesColors[sp.id] || CMP_SERIES_COLORS[idx % CMP_SERIES_COLORS.length];

    ctx.beginPath();
    AXES_KEYS.forEach((key, i) => {
      const val = scores[key] || 0;
      const p = axPoint(i, R * val);
      i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y);
    });
    ctx.closePath();

    // Relleno semitransparente
    ctx.fillStyle = col + '28'; // ~16% opacidad
    ctx.fill();

    // Contorno
    ctx.strokeStyle = col;
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.9;
    ctx.stroke();
    ctx.globalAlpha = 1;

    // Puntos en vértices
    AXES_KEYS.forEach((key, i) => {
      const val = scores[key] || 0;
      const p = axPoint(i, R * val);
      ctx.beginPath();
      ctx.arc(p.x, p.y, 4, 0, Math.PI * 2);
      ctx.fillStyle = col;
      ctx.fill();
      ctx.strokeStyle = 'white';
      ctx.lineWidth = 1.5;
      ctx.stroke();
    });
  });

  // ── Centro ────────────────────────────────────────────────────────
  ctx.beginPath();
  ctx.arc(cx, cy, 3, 0, Math.PI * 2);
  ctx.fillStyle = '#8a96a6';
  ctx.fill();
}

/**
 * Genera el análisis cladístico generalizado para N especies.
 * Calcula: rasgos compartidos por todos, por subconjuntos, y autapomorfías.
 * @param {Object[]} species
 * @param {Object} seriesColors
 * @returns {string} HTML
 */
function _cmpRenderCladisticsN(species, seriesColors) {
  const profiles = species.map(sp => ({ sp, profile: getCharacterProfile(sp) }));

  // ── Rasgos compartidos por TODOS ─────────────────────────────────
  const universalIds = [...profiles[0].profile].filter(id =>
    profiles.every(p => p.profile.has(id)) && CHARACTER_CATALOG[id]
  );
  const universalPrimitive = universalIds.filter(id => CHARACTER_CATALOG[id].kind === 'primitive');
  const universalDerived   = universalIds.filter(id => CHARACTER_CATALOG[id].kind === 'derived');

  // ── Autapomorfías de cada especie (derivados exclusivos) ──────────
  const autapos = profiles.map(({ sp, profile }) => {
    const unique = [...profile].filter(id => {
      if (!CHARACTER_CATALOG[id] || CHARACTER_CATALOG[id].kind !== 'derived') return false;
      return profiles.filter(p => p.sp.id !== sp.id).some(p => !p.profile.has(id));
    });
    return { sp, unique };
  });

  // ── Nota interpretativa ──────────────────────────────────────────
  const clades = [...new Set(species.map(s => s.clado))];
  let note;
  if (clades.length === 1) {
    note = `Todos los taxones comparados pertenecen a <strong>${Object.keys(CLADE_NAMES).includes(clades[0]) ? CLADE_NAMES[clades[0]] : clades[0]}</strong>. La presencia de <strong>${universalDerived.length}</strong> rasgos derivados compartidos refuerza su agrupación filogenética.`;
  } else if (universalDerived.length > 0) {
    note = `Aunque proceden de linajes distintos, comparten <strong>${universalDerived.length}</strong> rasgos derivados que reflejan homología o convergencia adaptativa relevante para el debate.`;
  } else {
    note = `El contraste entre <strong>${clades.length}</strong> clados distintos hace visible la diversidad adaptativa del árbol hominino. El análisis de autapomorfías revela trayectorias evolutivas independientes.`;
  }

  return `<div class="cmp-clado-note">${note} <em style="font-size:0.8rem;color:var(--text-hint)">Simplificación pedagógica basada en matrices publicadas.</em></div>

  ${universalIds.length ? `
  <div class="cmp-clado-n-shared" style="margin-top:10px">
    <h4>Rasgos compartidos por todos los taxones comparados</h4>
    ${universalPrimitive.length ? `<div style="margin-bottom:8px"><span style="font-size:0.68rem;text-transform:uppercase;letter-spacing:0.06em;color:#5e6b78;font-weight:700">Plesiomorfías:</span> <div class="cmp-pill-list">${universalPrimitive.map(id => `<span class="cmp-pill primitive">${CHARACTER_CATALOG[id].label}</span>`).join('')}</div></div>` : ''}
    ${universalDerived.length ? `<div><span style="font-size:0.68rem;text-transform:uppercase;letter-spacing:0.06em;color:#0a6b49;font-weight:700">Sinapomorfías:</span> <div class="cmp-pill-list">${universalDerived.map(id => `<span class="cmp-pill derived">${CHARACTER_CATALOG[id].label}</span>`).join('')}</div></div>` : ''}
  </div>` : `<div class="cmp-clado-note" style="margin-top:10px;background:#fff8f0;border-color:#e8d8b0"><em>No se identifican rasgos compartidos por todos los taxones en esta lectura simplificada — alta diversidad morfológica.</em></div>`}

  <div class="cmp-clado-n-grid" style="margin-top:10px">
    ${autapos.map(({ sp, unique }) => `
      <div class="cmp-clado-n-card">
        <h4>
          <span class="cmp-clado-n-dot" style="background:${seriesColors[sp.id]}" aria-hidden="true"></span>
          Autapomorfías de <em lang="la">${escapeHtmlText(sp.nombre)}</em>
        </h4>
        ${unique.length
          ? `<div class="cmp-pill-list">${unique.map(id => `<span class="cmp-pill exclusive-a">${CHARACTER_CATALOG[id].label}</span>`).join('')}</div>`
          : `<div class="cmp-empty">Sin rasgos derivados exclusivos destacados frente al grupo comparado.</div>`}
      </div>`).join('')}
  </div>`;
}

// ── Mantener compatibilidad con llamadas al comparador de 2 heredado ──────
// renderMorphVisualComparison y renderComparison redirigen al nuevo sistema.

/**
 * @deprecated Usar renderMultiComparison(). Mantenido para compatibilidad con otros módulos.
 */
function renderMorphVisualComparison(A, B) {
  return _cmpRenderMorphGridN([A, B]);
}

/**
 * @deprecated Usar renderMultiComparison() directamente.
 * Redirige al nuevo comparador N-especie.
 * Mantenido solo por si algún módulo externo llama a renderComparison().
 */
function renderComparison() {
  renderMultiComparison();
}

/**
 * Devuelve el SVG icono correspondiente a un tipo morfológico.
 * @param {string} kind - 'sagittal' | 'torus' | 'chin' | 'biped' | 'cc' | 'ok' | 'partial' | 'absent' | 'unknown'
 * @returns {string} SVG inline
 */
function morphIcon(kind) {
    const icons = {
        sagittal: '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2"><path d="M7 18c-2-2-3-4-3-7a8 8 0 0 1 16 0c0 4-2 7-5 9"/><path d="M12 3v8"/><path d="M9 6h6"/></svg>',
        torus: '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 12c2-4 5-6 8-6s6 2 8 6"/><path d="M6 13h12"/><circle cx="9" cy="15" r="1.5"/><circle cx="15" cy="15" r="1.5"/></svg>',
        chin: '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2"><path d="M7 4c-2 4-2 9 1 13l4 4 4-4c3-4 3-9 1-13"/><path d="M9 17c2 1 4 1 6 0"/></svg>',
        biped: '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 3v7l-3 9"/><path d="M15 3v7l3 9"/><path d="M7 21h4"/><path d="M13 21h4"/></svg>',
        cc: '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 18a6 6 0 1 1 8-5.6"/><path d="M9 18c-2 0-4-2-4-5a7 7 0 0 1 7-7"/><path d="M13 14h7"/><path d="M17 10v8"/></svg>',
        ok: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="M20 6 9 17l-5-5"/></svg>',
        partial: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="M5 12h14"/></svg>',
        absent: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="M18 6 6 18M6 6l12 12"/></svg>',
        unknown: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><path d="M9.5 9a2.8 2.8 0 0 1 5.2 1.4c0 2-2.7 2.4-2.7 4"/><path d="M12 18h.01"/></svg>'
    };
    return icons[kind] || icons.unknown;
}

function stateIconName(state) {
    return state === 'present' ? 'ok' : state === 'partial' ? 'partial' : state === 'absent' ? 'absent' : 'unknown';
}

function renderStateCell(sp, key) {
    const st = morphState(sp, key);
    const gauge = key === 'cc'
      ? `<span class="cmp-cc-gauge"><span style="width:${st.pct || 0}%;background:${CLADE_COLORS[sp.clado] || 'var(--accent)'}"></span></span>`
      : '';
    return `<div class="cmp-visual-cell" data-label="${escapeHtmlAttr(sp.nombre)}">
      <span class="cmp-state ${escapeHtmlAttr(st.state)}">${morphIcon(stateIconName(st.state))}${escapeHtmlText(st.label)}</span>
      ${gauge}
    </div>`;
}


/**
 * Exporta las especies visibles a CSV — usa ExportManager para escape RFC 4180
 * y tolerancia a campos ausentes. Reemplaza la versión que lanzaba TypeError
 * cuando sp.experto era undefined.
 */
function exportToCSV() {
    const visibles = DB.filter(matchesActiveFilters);
    return PaleoBot.ExportManager.exportCSV(visibles, 'paleobot_' + new Date().toISOString().slice(0,10) + '.csv');
}

/**
 * Exporta como JSON estructurado canónico (nuevo — antes no existía).
 */
function exportToJSON() {
    const visibles = DB.filter(matchesActiveFilters);
    PaleoBot.ExportManager.exportJSON(visibles, 'paleobot_' + new Date().toISOString().slice(0,10) + '.json');
}

/**
 * Copia la bibliografía de la especie actualmente abierta en APA 7.
 */
function copySpeciesBibliography() {
    if (!currentSpecies) { alert('Abre primero la ficha de una especie.'); return; }
    PaleoBot.ExportManager.copyBibliography(currentSpecies, 'apa');
}

function buildFacialPrompt(sp) {
    return `Redacta una descripción científica de la morfología facial de ${sp.nombre} para nivel ${nivelActual}. Usa solo estos datos de la ficha: ${sp.experto?.anatomia_craneal || ''} ${sp.experto?.descripcion_tecnica || ''}. Indica incertidumbres y evita reconstrucciones no documentadas.`;
}

function localFacialDescription(sp) {
    const cranial = sp.experto?.anatomia_craneal || 'La ficha no conserva una descripción craneal suficiente.';
    const tech = sp.experto?.descripcion_tecnica || '';
    const debate = sp.experto?.debate || '';
    const levelLead = {
      basico: 'En lectura básica, conviene imaginar la cara a partir de rasgos observables y evitar detalles especulativos.',
      universitario: 'En lectura universitaria, la reconstrucción debe separar rasgos diagnósticos, inferencias comparativas e incertidumbre tafonómica.',
      doctorado: 'En lectura de doctorado, la descripción debe tratarse como una hipótesis morfológica condicionada por preservación, muestra y debate taxonómico.'
    }[nivelActual] || '';
    return `${levelLead} Para ${sp.nombre}, los datos craneofaciales cargados indican: ${cranial} ${tech ? `Como complemento técnico: ${tech}` : ''} ${debate ? `Punto crítico de interpretación: ${debate}` : ''}`;
}

async function generateFacialDescription() {
    if (!currentSpecies) return;
    const panel = document.getElementById('aiFacialPanel');
    if (!panel) return;
    panel.classList.add('active');
    panel.innerHTML = `<h4>Reconstrucción facial IA</h4><p>Generando descripción adaptada al nivel <strong>${nivelActual}</strong>…</p>`;

    const endpoint = window.PALEOBOT_CLAUDE_ENDPOINT;
    if (endpoint) {
      try {
        const res = await fetch(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            task: 'facial_reconstruction_description',
            speciesId: currentSpecies.id,
            level: nivelActual,
            prompt: buildFacialPrompt(currentSpecies)
          })
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        // FIX C-1: sanitizeText() antes de innerHTML — prevención de XSS
        const _rawText = data.text || data.descripcion || localFacialDescription(currentSpecies);
        const _safeText = sanitizeText(String(_rawText));
        panel.innerHTML = `<h4>Reconstrucción facial IA</h4><p>${aplicarGlosario(_safeText)}</p><small>Generado mediante endpoint Claude configurado en <code>window.PALEOBOT_CLAUDE_ENDPOINT</code>. Revisión docente recomendada.</small>`;
        return;
      } catch (err) {
        Logger.warn('Claude endpoint no disponible:', err);
      }
    }

    // FIX C-1: sanitizeText() en modo local (datos internos — prevención defensiva)
    const _localText = sanitizeText(localFacialDescription(currentSpecies));
    panel.innerHTML = `<h4>Reconstrucción facial IA</h4><p>${aplicarGlosario(_localText)}</p><small>Modo local seguro: no hay endpoint Claude configurado. Para usar Claude sin exponer claves en el navegador, define un proxy propio en <code>window.PALEOBOT_CLAUDE_ENDPOINT</code>.</small>`;
}

function buildAcademicPrintSheet(sp) {
    const disc = DISCOVERY_DATES[sp.id];
    const refs = (sp.experto?.referencias || []).slice(0, 5);
    const doiList = refs.length
      ? refs.map(renderReferencePrintItem).join('')
      : '<li>Sin referencias DOI cargadas para esta ficha.</li>';
    const resourceUrl = `${window.location.href.split('#')[0]}#${encodeURIComponent(sp.id)}`;
    const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=120x120&data=${encodeURIComponent(resourceUrl)}`;
    const safePrintName = escapeHtmlText(sp.nombre);
    const safePrintDate = escapeHtmlText(new Date().toLocaleDateString('es-ES'));
    const safeResourceUrl = escapeHtmlText(resourceUrl);
    const safeQrUrl = escapeHtmlAttr(qrUrl);
    const safePrintClade = escapeHtmlText(CLADE_NAMES[sp.clado] || sp.clado);
    const safePrintYears = escapeHtmlText(sp.anos);
    const safePrintLocation = escapeHtmlText(sp.ubicacion);
    const safePrintHolotype = escapeHtmlText(sp.holo);
    const safePrintDating = escapeHtmlText(sp.datacion);
    const safePrintCc = escapeHtmlText(sp.cc ? sp.cc + ' cc' : 'No disponible');
    const safePrintDiscovery = escapeHtmlText(disc ? `${disc.anio} · ${disc.autor}` : 'No cargado');
    const safePrintStatus = escapeHtmlText(ESTADO_LABEL[sp.estado || 'aceptada'] || 'Aceptada');
    const safePrintSummary = escapeHtmlText(sp.descripcion);
    const safePrintCranial = escapeHtmlText(sp.experto?.anatomia_craneal || 'Datos no disponibles.');
    return `<div class="academic-page">
      <div class="academic-head">
        <div>
          <h1>${safePrintName}</h1>
          <p>PaleoBot · ficha académica de una página · ${safePrintDate}</p>
        </div>
        <img class="academic-qr" src="${safeQrUrl}" alt="QR del recurso">
      </div>
      <div class="academic-grid">
        <div>
          <img class="academic-img" src="${escapeHtmlAttr(getSpeciesImage(sp))}" alt="${escapeHtmlAttr(sp.nombre)}" decoding="async" referrerpolicy="no-referrer">
          <div class="academic-section">
            <h2>Recurso</h2>
            <p>${safeResourceUrl}</p>
          </div>
        </div>
        <div>
          <div class="academic-kpis">
            <div class="academic-kpi"><strong>Clado</strong>${safePrintClade}</div>
            <div class="academic-kpi"><strong>Cronología</strong>${safePrintYears}</div>
            <div class="academic-kpi"><strong>Yacimiento / región</strong>${safePrintLocation}</div>
            <div class="academic-kpi"><strong>Holotipo</strong>${safePrintHolotype}</div>
            <div class="academic-kpi"><strong>Datación</strong>${safePrintDating}</div>
            <div class="academic-kpi"><strong>CC</strong>${safePrintCc}</div>
            <div class="academic-kpi"><strong>Descubrimiento</strong>${safePrintDiscovery}</div>
            <div class="academic-kpi"><strong>Estado</strong>${safePrintStatus}</div>
          </div>
          <div class="academic-section"><h2>Resumen</h2><p>${safePrintSummary}</p></div>
          <div class="academic-section"><h2>Anatomía craneal</h2><p>${safePrintCranial}</p></div>
          <div class="academic-section"><h2>Referencias</h2><ul>${doiList}</ul></div>
        </div>
      </div>
      <div class="academic-footer">
        <span>Exportado desde PaleoBot</span>
        <span>Usar “Guardar como PDF” en el diálogo de impresión</span>
      </div>
    </div>`;
}

function exportAcademicPDF() {
    if (!currentSpecies) { alert('Abre primero la ficha de una especie.'); return; }
    const sheet = document.getElementById('academicPrintSheet');
    if (!sheet) return;
    sheet.innerHTML = buildAcademicPrintSheet(currentSpecies);
    document.body.classList.add('pdf-academic-mode');
    setTimeout(() => {
      window.print();
      setTimeout(() => document.body.classList.remove('pdf-academic-mode'), 300);
    }, 80);
}

function printFicha() {
    const panel = document.getElementById('detailView');
    const detailOpen = Boolean(panel?.classList.contains('active'));
    document.body.classList.toggle('pb-print-active-view', !detailOpen);
    document.documentElement.dataset.pbPrintState = detailOpen ? 'detail-requested' : 'view-requested';
    document.dispatchEvent(new CustomEvent('paleobot:print-requested', {
      detail: { context: detailOpen ? 'detail' : 'active-view' }
    }));
    window.print();
    window.setTimeout(() => document.body.classList.remove('pb-print-active-view'), 300);
    return true;
}

// Placeholder para imagen de cabecera del panel de detalle
function handleImageError(img) {
    if (img.dataset.errorHandled === '1') return;
    img.dataset.errorHandled = '1';
    img.style.display = 'none';
    const ph = document.createElement('div');
    ph.style.cssText = 'width:100%;height:160px;background:#eceae4;border-radius:10px;border:1px dashed #c8c4bc;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;color:#a09890;font-size:0.8rem;margin-bottom:20px;';
    ph.innerHTML = '<span class="ico" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg></span><span>Imagen no disponible — requiere conexión</span>';
    img.parentNode.insertBefore(ph, img.nextSibling);
}

function handleThumbError(img) {
    if (img.dataset.errorHandled === '1') return;
    img.dataset.errorHandled = '1';
    img.style.display = 'none';
    const ph = document.createElement('div');
    ph.className = 'sp-img-thumb';
    ph.style.cssText = 'display:flex;align-items:center;justify-content:center;background:#eceae4;flex-shrink:0;';
    ph.innerHTML = '<span class="ico" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg></span>';
    img.parentNode.insertBefore(ph, img.nextSibling);
}

function handleMapError(img) {
    if (img.dataset.errorHandled === '1') return;
    img.dataset.errorHandled = '1';
    img.style.display = 'none';
    const ph = document.createElement('div');
    ph.style.cssText = 'width:100%;min-height:80px;background:#f0ede8;border-radius:8px;display:flex;align-items:center;justify-content:center;gap:8px;color:#a09080;font-size:0.83rem;border:1px dashed #c8c0b4;margin:6px 0 10px;';
    ph.innerHTML = '<span class="ico" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><polygon points="3 6 9 3 15 6 21 3 21 18 15 21 9 18 3 21"/><line x1="9" y1="3" x2="9" y2="18"/><line x1="15" y1="6" x2="15" y2="21"/></svg></span> Mapa no disponible — requiere conexión';
    img.parentNode.insertBefore(ph, img.nextSibling);
}


/** v58: Genera preguntas guía para la ficha de especie */
function renderSpeciesGuideQuestions(sp) {
  if (!sp) return '';
  const isDebated = sp.estado === 'debatida' || sp.estado === 'revision';
  const hasDebate = sp.experto && sp.experto.debate && sp.experto.debate.length > 30;
  const isBipedal = sp.clado === 'basal' || sp.clado === 'australo';
  const isHomo    = sp.clado === 'homo';

  const questions = [];

  // Pregunta sobre evidencia
  if (sp.holo && sp.holo !== 'N/A') {
    questions.push(`¿Qué puedes afirmar con certeza a partir del holotipo <strong>${escapeHtmlText(sp.holo)}</strong>? ¿Qué inferencias son razonables pero no directamente observables?`);
  }

  // Pregunta sobre contexto africano (DEA)
  if (sp.ubicacion && sp.ubicacion.toLowerCase().includes('áfrica') || ['Kenia','Etiopía','Tanzania','Sudáfrica','Chad','Uganda','Zambia','Marruecos'].some(r => (sp.ubicacion||'').includes(r))) {
    questions.push(`¿Qué nos dice la localización de ${escapeHtmlText(sp.nombre)} en ${escapeHtmlText(sp.ubicacion)} sobre la distribución geográfica de la hominización?`);
  }

  // Pregunta sobre debate si existe
  if (hasDebate) {
    questions.push(`¿Cuál es el debate científico central sobre ${escapeHtmlText(sp.nombre)}? ¿Qué nuevo hallazgo resolvería mejor la controversia?`);
  }

  // Pregunta sobre bipedismo para basales/australos
  if (isBipedal) {
    questions.push(`¿Qué evidencias apoyan el bipedismo en ${escapeHtmlText(sp.nombre)} y cuáles siguen siendo inferidas o debatidas?`);
  }

  // Pregunta sobre cognición para Homo
  if (isHomo && sp.cc && sp.cc > 600) {
    questions.push(`La capacidad craneal de ${escapeHtmlText(sp.nombre)} es ${sp.cc} cc. ¿Implica necesariamente mayor complejidad cognitiva? ¿Qué otras evidencias acompañarían esa inferencia?`);
  }

  if (questions.length === 0) return '';

  const qHtml = questions.slice(0, 3).map((q, i) =>
    `<li style="margin-bottom:8px;padding-left:4px;font-size:0.86rem;color:var(--text-sec);line-height:1.58;">${q}</li>`
  ).join('');

  return `
  <details class="species-guide-questions" style="margin:0 0 20px;background:linear-gradient(135deg,#f0f7ff,#e8f0fb);border:1px solid rgba(26,79,160,0.18);border-radius:12px;padding:13px 15px;">
    <summary style="cursor:pointer;font-weight:700;color:var(--primary);font-size:0.82rem;list-style:none;display:flex;align-items:center;gap:7px;" aria-label="Preguntas guía para reflexionar sobre esta especie">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><path d="M12 17h.01"/></svg>
      Preguntas para reflexionar sobre ${escapeHtmlText(sp.nombre)}
    </summary>
    <ul style="margin:10px 0 0;padding-left:16px;list-style:disc;">${qHtml}</ul>
  </details>`;
}

function runExam() {
    document.getElementById('examIntro').style.display = 'none';
    const examDiv = document.getElementById('examQ');
    examDiv.style.display = 'block';
    examDiv.innerHTML = '';
    // Contador de sesión
    var _qsc = 0;
    try { _qsc = parseInt(sessionStorage.getItem('paleobot_quiz_session_count') || '0', 10) || 0; } catch (e) { _qsc = 0; }
    const sessionCount = _qsc + 1;
    try { sessionStorage.setItem('paleobot_quiz_session_count', String(sessionCount)); } catch (e) { /* recuperable */ }
    // Mostrar indicador en el header del modal si existe
    const headerTitle = document.getElementById('examModal-title');
    if (headerTitle) {
      headerTitle.textContent = 'Autoevaluación de repaso — Pregunta ' + sessionCount;
    }

    // Cada tipo declara también la pestaña de la ficha más relevante (mejora v26)
    const tipos = [
        sp => ({
            q: `¿Cuál es la capacidad craneal aproximada de ${sp.nombre}?`,
            a: sp.cc ? sp.cc + ' cc' : null,
            pool: DB.filter(s => s.cc).map(s => s.cc + ' cc'),
            tab: 'anat',
            explanation: `La capacidad craneal (cc) de ${sp.nombre} es ${sp.cc || 'desconocida'} cc. Este valor es una estimación del volumen endocraneal del holotipo y se usa como indicador del tamaño cerebral, aunque no equivale directamente a capacidad cognitiva.`
        }),
        sp => ({
            q: `¿En qué país o región se descubrieron los fósiles de ${sp.nombre}?`,
            a: sp.ubicacion,
            pool: [...new Set(DB.map(s => s.ubicacion))],
            tab: 'gen',
            explanation: `Los fósiles de ${sp.nombre} proceden de ${sp.ubicacion}. La localización geográfica es clave para entender la distribución africana de los homininos, aunque no implica que la especie se limitara a esa región.`
        }),
        sp => ({
            q: `¿A qué clado pertenece ${sp.nombre}?`,
            a: CLADE_NAMES[sp.clado],
            pool: Object.values(CLADE_NAMES),
            tab: 'gen',
            explanation: `${sp.nombre} pertenece al clado ${CLADE_NAMES[sp.clado]}. Recuerda: el clado agrupa taxones por relación de parentesco, no necesariamente por secuencia temporal ni por ancestralidad directa.`
        }),
        sp => ({
            q: `¿Cuál es el holotipo de ${sp.nombre}?`,
            a: sp.holo,
            pool: DB.map(s => s.holo),
            tab: 'anat',
            explanation: `El holotipo de ${sp.nombre} es ${sp.holo}. El holotipo es el espécimen de referencia formal de la especie, pero la descripción se apoya en toda la muestra conocida; rasgos del holotipo pueden no ser representativos de toda la variación de la especie.`
        }),
        sp => ({
            q: `¿Cuál es el rango temporal documentado de ${sp.nombre}?`,
            a: sp.anos,
            pool: DB.filter(s => s.anos && s.anos !== sp.anos).slice(0,8).map(s => s.anos).filter(Boolean),
            tab: 'gen',
            explanation: `El rango temporal de ${sp.nombre} es ${sp.anos}. Los rangos proceden de dataciones de los especímenes más antiguos y más recientes; los extremos suelen tener mayor incertidumbre que los puntos centrales bien datados.`
        })
    ];

    const sp = DB[Math.floor(Math.random() * DB.length)];
    const tipo = tipos[Math.floor(Math.random() * tipos.length)](sp);
    if (!tipo.a) { runExam(); return; }

    const correcta   = tipo.a;
    const tabDestino = tipo.tab || 'gen';
    const distractores = [...new Set(tipo.pool.filter(x => x !== correcta))]
        .sort(() => Math.random() - 0.5).slice(0, 3);
    const opts = [correcta, ...distractores].sort(() => Math.random() - 0.5);

    const qEl = document.createElement('p');
    qEl.className = 'exam-question-title';
    qEl.textContent = tipo.q;
    examDiv.appendChild(qEl);

    opts.forEach(o => {
        const btn = document.createElement('button');
        btn.className = 'exam-opt';
        btn.textContent = o;
        btn.addEventListener('click', () => {
            const ok = o === correcta;
            QuizProgress.record(sp.id, ok, 'classic');
            examDiv.querySelectorAll('.exam-opt').forEach(b => b.disabled = true);
            btn.classList.add(ok ? 'exam-correct' : 'exam-wrong');
            if (!ok) examDiv.querySelectorAll('.exam-opt').forEach(b => {
                if (b.textContent === correcta) b.classList.add('exam-correct');
            });
            const tabLabels = { gen:'General', anat:'Anatomía', eco:'Ecología', biblio:'Investigación' };
            const explanation = tipo.explanation || '';
            const res = document.createElement('div');
            res.className = 'exam-feedback';
            res.innerHTML = `
              <p class="exam-feedback-title">
                ${ok ? '✅ Correcto' : '❌ Incorrecto'}
              </p>
              ${!ok ? `<p class="exam-feedback-note">
                Respuesta correcta: <strong>${correcta}</strong>
              </p>` : ''}
              ${explanation ? `<div class="exam-feedback-card" style="margin-top:10px;background:#f4f9f6;border:1px solid #b2d8c8;border-radius:9px;padding:11px 13px;">
                <p style="margin:0 0 4px;font-size:0.7rem;font-weight:800;text-transform:uppercase;letter-spacing:0.06em;color:#0a6b49;font-family:var(--font-mono);">📖 ¿Por qué?</p>
                <p style="margin:0;font-size:0.86rem;color:var(--text-sec);line-height:1.58;">${escapeHtmlText(explanation)}</p>
              </div>` : ''}
              <div class="exam-action-row">
                <button type="button" class="exam-btn" data-quiz-next="classic">Siguiente pregunta</button>
                <button type="button" class="exam-btn linked"
                  data-quiz-open-species="${escapeHtmlAttr(sp.id)}"
                  data-quiz-tab="${escapeHtmlAttr(tabDestino)}"
                  title="Abrir la ficha de ${escapeHtmlAttr(sp.nombre)} en la pestaña ${escapeHtmlAttr(tabLabels[tabDestino])}">
                  Ver ficha de <em>${escapeHtmlText(sp.nombre)}</em> → ${escapeHtmlText(tabLabels[tabDestino])}
                </button>
              </div>`;
            examDiv.appendChild(res);
        });
        examDiv.appendChild(btn);
    });
}

function getVisibleQuizPool() {
    const pool = DB.filter(matchesActiveFilters);
    return pool.length >= 4 ? pool : DB.filter(sp => cladoFilter === 'all' || sp.clado === cladoFilter);
}

/**
 * Construye una pregunta generativa a partir del pool visible.
 * v26: añade campo `tab` y `_spId` para enlazar la ficha tras responder.
 */
function buildGenerativeQuestion(pool) {
    const candidates = pool.filter(sp => sp.holo && sp.ubicacion && sp.experto);
    const sp = candidates[Math.floor(Math.random() * candidates.length)] || pool[Math.floor(Math.random() * pool.length)];
    const templates = {
      basico: [
        { q:`¿Qué especie se asocia con ${sp.ubicacion}?`,
          a:sp.nombre, pool:pool.map(s=>s.nombre),
          why:`${sp.nombre} aparece registrado con ubicación principal: ${sp.ubicacion}.`,
          tab:'gen' },
        { q:`¿A qué clado pertenece ${sp.nombre}?`,
          a:CLADE_NAMES[sp.clado], pool:Object.values(CLADE_NAMES),
          why:`Está clasificado dentro del clado ${CLADE_NAMES[sp.clado]}.`,
          tab:'gen' }
      ],
      universitario: [
        { q:`¿Qué holotipo corresponde a ${sp.nombre}?`,
          a:sp.holo, pool:pool.map(s=>s.holo),
          why:`El holotipo de referencia de ${sp.nombre} es ${sp.holo}.`,
          tab:'anat' },
        { q:`¿Qué tecnología o cultura se asocia a ${sp.nombre}?`,
          a:sp.herramientas, pool:[...new Set(pool.map(s=>s.herramientas))],
          why:`La ficha registra: ${sp.herramientas}.`,
          tab:'eco' }
      ],
      doctorado: [
        { q:`¿Qué taxón permite discutir este problema: "${(getSpeciesExpert(sp).debate || '').slice(0, 150)}…"?`,
          a:sp.nombre, pool:pool.map(s=>s.nombre),
          why:`La cita procede del bloque de debate de ${sp.nombre}. Evalúa hipótesis, no solo memoria factual.`,
          tab:'biblio' },
        { q:`¿Qué método de datación está asociado a ${sp.nombre}?`,
          a:sp.datacion, pool:[...new Set(pool.map(s=>s.datacion))],
          why:`La ficha registra ${sp.datacion} como método o marco de datación principal.`,
          tab:'anat' }
      ]
    };
    const options = templates[nivelActual] || templates.doctorado;
    const q = options[Math.floor(Math.random() * options.length)];
    return { ...q, _spId: sp.id };
}

async function runGenerativeQuiz() {
    document.getElementById('examIntro').style.display = 'none';
    const examDiv = document.getElementById('examQ');
    examDiv.style.display = 'block';
    examDiv.innerHTML = '';

    const pool = getVisibleQuizPool();
    if (pool.length < 2) {
        examDiv.innerHTML = `<p class="quiz-status-copy">No hay suficientes especies visibles para generar un quiz. Amplía el filtro temporal o de clado.</p><button type="button" class="exam-btn" data-quiz-back="intro">Volver</button>`;
        return;
    }
    let q = null;
    const endpoint = window.PALEOBOT_CLAUDE_ENDPOINT;
    if (endpoint) {
      examDiv.innerHTML = `<p class="quiz-status-copy">Solicitando pregunta al endpoint Claude configurado…</p>`;
      try {
        const res = await fetch(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            task: 'visible_species_quiz',
            level: nivelActual,
            species: pool.map(sp => ({
              id: sp.id,
              nombre: sp.nombre,
              clado: CLADE_NAMES[sp.clado] || sp.clado,
              anos: sp.anos,
              ubicacion: sp.ubicacion,
              holo: sp.holo,
              datacion: sp.datacion,
              debate: sp.experto?.debate || ''
            }))
          })
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        if (data.question && data.answer) {
          // FIX C-1: sanitizar respuesta de la API antes de usar en innerHTML
          q = {
            q:    sanitizeText(String(data.question)),
            a:    sanitizeText(String(data.answer)),
            pool: Array.isArray(data.options)
                    ? data.options.map(o => sanitizeText(String(o)))
                    : [sanitizeText(String(data.answer))],
            why:  sanitizeText(String(
                    data.feedback || data.justification ||
                    'Pregunta generada mediante endpoint Claude configurado.'
                  )),
            tab:  'gen',
            _spId: null
          };
        }
      } catch (err) {
        Logger.warn('Quiz Claude no disponible:', err);
      }
    }
    if (!q) q = buildGenerativeQuestion(pool);
    let distractores = [...new Set(q.pool.filter(x => x && x !== q.a))]
        .sort(() => Math.random() - 0.5)
        .slice(0, 3);
    if (distractores.length < 3) {
      distractores = [...new Set([...distractores, ...pool.map(sp => sp.nombre).filter(x => x !== q.a)])]
        .sort(() => Math.random() - 0.5)
        .slice(0, 3);
    }
    const opts = [q.a, ...distractores].sort(() => Math.random() - 0.5);
    const encodedAnswer = encodeURIComponent(q.a).replace(/'/g, '%27');
    const encodedWhy    = encodeURIComponent(q.why).replace(/'/g, '%27');
    const encodedSpId   = encodeURIComponent(q._spId || '').replace(/'/g, '%27');
    const encodedTab    = encodeURIComponent(q.tab || 'gen').replace(/'/g, '%27');

    examDiv.innerHTML = `
      <div class="quiz-card">
        <div class="quiz-card-kicker">Quiz generativo local · ${nivelActual}</div>
        <p class="quiz-card-question">${q.q}</p>
      </div>
      ${opts.map(o => `<button type="button" class="exam-opt" data-quiz-answer="${escapeHtmlAttr(encodedAnswer)}" data-quiz-why="${escapeHtmlAttr(encodedWhy)}" data-quiz-species="${escapeHtmlAttr(encodedSpId)}" data-quiz-tab="${escapeHtmlAttr(encodedTab)}">${escapeHtmlText(o)}</button>`).join('')}
      <p class="quiz-footnote">Se genera desde las especies visibles por búsqueda, clado y filtro temporal.</p>
    `;
}

/**
 * Evalúa la respuesta del quiz generativo y muestra el enlace a la ficha (v26).
 * @param {HTMLElement} btn
 * @param {string} encodedAnswer - Respuesta correcta (encodeURIComponent)
 * @param {string} encodedWhy    - Justificación (encodeURIComponent)
 * @param {string} encodedSpId   - ID de la especie (encodeURIComponent)
 * @param {string} encodedTab    - Pestaña destino (encodeURIComponent)
 */
function answerGenerativeQuiz(btn, encodedAnswer, encodedWhy, encodedSpId, encodedTab) {
    const examDiv = document.getElementById('examQ');
    const answer  = decodeURIComponent(encodedAnswer);
    const why     = decodeURIComponent(encodedWhy);
    const spId    = decodeURIComponent(encodedSpId || '');
    const tabId   = decodeURIComponent(encodedTab  || 'gen') || 'gen';
    const ok      = btn.textContent === answer;
    QuizProgress.record(spId || null, ok, 'generative');
    examDiv.querySelectorAll('.exam-opt').forEach(b => {
      b.disabled = true;
      if (b.textContent === answer) b.classList.add('exam-correct');
    });
    if (!ok) btn.classList.add('exam-wrong');
    const tabLabels = { gen:'General', anat:'Anatomía', eco:'Ecología', biblio:'Investigación' };
    const sp = spId ? DB_INDEX[spId] : null;
    const fb = document.createElement('div');
    fb.className = 'exam-feedback-card';
    fb.innerHTML = `
      <p class="exam-feedback-title strong">${ok ? 'Correcto' : 'Incorrecto'}</p>
      <p class="exam-feedback-body">${why}</p>
      <div class="exam-action-row left">
        <button type="button" class="exam-btn" data-quiz-next="generative">Nueva pregunta generativa</button>
        ${sp ? `<button type="button" class="exam-btn linked"
            data-quiz-open-species="${escapeHtmlAttr(sp.id)}"
            data-quiz-tab="${escapeHtmlAttr(tabId)}"
            title="Ver ficha en pestaña ${escapeHtmlAttr(tabLabels[tabId])}">
            Ver ficha de <em>${escapeHtmlText(sp.nombre)}</em> → ${escapeHtmlText(tabLabels[tabId])}
          </button>` : ''}
      </div>`;
    examDiv.appendChild(fb);
}

// ══════════════════════════════════════════════════════════════
// GRÁFICO DE ENCEFALIZACIÓN MEJORADO — Canvas
// ══════════════════════════════════════════════════════════════

let chartZoom = { minMa: 0, maxMa: 23.5, minCC: 0, maxCC: 1750 };
let chartSelectMode = false;
let chartSelectedIds = null; // null = all selected
let chartHoverSp = null;
let chartData = []; // cached points with pixel coords

function setChartZoom(mode, btn) {
  document.querySelectorAll('.chart-ctrl-btn[id^="zoom-"]').forEach(b => {
    b.classList.remove('active');
    b.setAttribute('aria-pressed', 'false');
  });
  if (btn) {
    btn.classList.add('active');
    btn.setAttribute('aria-pressed', 'true');
  }
  const z = { minCC: 0, maxCC: 1750 };
  if (mode === 'all')   { z.minMa = 0;    z.maxMa = 23.5; }
  if (mode === 'mio')   { z.minMa = 4.5;  z.maxMa = 23.5; z.maxCC = 500; }
  if (mode === 'plio')  { z.minMa = 1.3;  z.maxMa = 5.2;  z.maxCC = 900; }
  if (mode === 'pleis') { z.minMa = 0;    z.maxMa = 2.2;  }
  chartZoom = z;
  drawEncefChart();
}

function toggleSelectMode() {
  chartSelectMode = !chartSelectMode;
  const btn = document.getElementById('btn-select-mode');
  btn.classList.toggle('active', chartSelectMode);
  btn.setAttribute('aria-pressed', chartSelectMode ? 'true' : 'false');
  const canvas = document.getElementById('encefChart');
  canvas.classList.toggle('select-mode', chartSelectMode);
  document.getElementById('btn-reset-sel').style.display = chartSelectMode ? '' : 'none';
  if (!chartSelectMode) {
    chartSelectedIds = null;
    document.getElementById('chart-sel-info').style.display = 'none';
  }
  drawEncefChart();
}

function resetChartSelection() {
  chartSelectedIds = null;
  document.getElementById('chart-sel-info').style.display = 'none';
  drawEncefChart();
}

function linReg(pts) {
  // pts: [{x, y}] — x = val_time, y = cc
  const n = pts.length;
  if (n < 2) return null;
  const sx = pts.reduce((s,p)=>s+p.x,0), sy = pts.reduce((s,p)=>s+p.y,0);
  const sxy = pts.reduce((s,p)=>s+p.x*p.y,0), sxx = pts.reduce((s,p)=>s+p.x*p.x,0);
  const denom = n*sxx - sx*sx;
  if (Math.abs(denom) < 1e-12) return null;
  const m = (n*sxy - sx*sy) / denom;
  const b = (sy - m*sx) / n;
  return { m, b }; // y = m*x + b
}

function drawEncefChart() {
  const canvas = document.getElementById('encefChart');
  if (!canvas) return;
  const rect = canvas.getBoundingClientRect();
  const W = rect.width || 860;
  canvas.width  = W * window.devicePixelRatio;
  canvas.height = 420 * window.devicePixelRatio;
  canvas.style.height = '420px';
  const ctx = canvas.getContext('2d');
  ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
  const w = W, h = 420;

  const PAD = { top: 16, right: 18, bottom: 44, left: 62 };
  const plotW = w - PAD.left - PAD.right;
  const plotH = h - PAD.top - PAD.bottom;

  const { minMa, maxMa, minCC, maxCC } = chartZoom;
  const xScale = ma  => PAD.left + ((maxMa - ma) / (maxMa - minMa)) * plotW;
  const yScale = cc  => PAD.top  + plotH - ((cc - minCC) / (maxCC - minCC)) * plotH;

  // Background
  ctx.fillStyle = '#faf9f7';
  ctx.fillRect(0, 0, w, h);

  // Gridlines Y
  ctx.strokeStyle = '#e4e0d8'; ctx.lineWidth = 1; ctx.setLineDash([4, 3]);
  const yTicks = [];
  const yStep = maxCC <= 500 ? 100 : maxCC <= 900 ? 200 : 200;
  for (let v = 0; v <= maxCC; v += yStep) { if (v >= minCC) yTicks.push(v); }
  yTicks.forEach(v => {
    const y = yScale(v);
    ctx.beginPath(); ctx.moveTo(PAD.left, y); ctx.lineTo(w - PAD.right, y); ctx.stroke();
    ctx.fillStyle = '#8a96a6'; ctx.font = `10px JetBrains Mono, monospace`;
    ctx.textAlign = 'right'; ctx.fillText(v, PAD.left - 7, y + 4);
  });

  // Gridlines X
  const xMaTicks = [];
  const allMa = [0, 0.1, 0.3, 0.5, 1, 1.5, 2, 2.5, 3, 3.5, 4, 4.5, 5, 6, 7, 8, 10, 12, 15, 18, 20, 23];
  allMa.forEach(ma => { if (ma >= minMa && ma <= maxMa) xMaTicks.push(ma); });
  ctx.strokeStyle = '#e4e0d8';
  xMaTicks.forEach(ma => {
    const x = xScale(ma);
    ctx.beginPath(); ctx.moveTo(x, PAD.top); ctx.lineTo(x, h - PAD.bottom); ctx.stroke();
    ctx.fillStyle = '#8a96a6'; ctx.font = `10px JetBrains Mono, monospace`;
    ctx.textAlign = 'center';
    const lbl = ma === 0 ? 'Hoy' : ma < 1 ? (ma*1000).toFixed(0)+' ka' : ma+' Ma';
    ctx.fillText(lbl, x, h - PAD.bottom + 14);
  });
  ctx.setLineDash([]);

  // Axes
  ctx.strokeStyle = '#2e4257'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(PAD.left, PAD.top); ctx.lineTo(PAD.left, h - PAD.bottom); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(PAD.left, h - PAD.bottom); ctx.lineTo(w - PAD.right, h - PAD.bottom); ctx.stroke();

  // Axis labels
  ctx.fillStyle = '#4a5a6e'; ctx.font = `bold 11px JetBrains Mono, monospace`;
  ctx.textAlign = 'center';
  ctx.save(); ctx.translate(13, PAD.top + plotH/2); ctx.rotate(-Math.PI/2);
  ctx.fillText('Capacidad craneal (cc)', 0, 0); ctx.restore();
  ctx.fillText('Millones de años antes del presente (Ma)  ←  más antiguo', PAD.left + plotW/2, h - 6);

  // Species with CC in zoom range
  const species = DB.filter(sp => sp.cc != null && matchesActiveFilters(sp) && sp.val_time >= minMa && sp.val_time <= maxMa && sp.cc >= minCC && sp.cc <= maxCC);

  // Regression lines per clade
  const clades = ['basal','australo','paran','homo'];
  clades.forEach(clado => {
    const pts = species.filter(sp => {
      if (clado !== sp.clado) return false;
      if (chartSelectedIds && !chartSelectedIds.has(sp.id)) return false;
      return true;
    }).map(sp => ({ x: sp.val_time, y: sp.cc }));
    if (pts.length < 2) return;
    const reg = linReg(pts);
    if (!reg) return;
    // Draw regression line across zoom range
    const x1ma = maxMa, x2ma = minMa;
    const y1cc = reg.m * x1ma + reg.b;
    const y2cc = reg.m * x2ma + reg.b;
    const col = CLADE_COLORS[clado] || '#888';
    ctx.save();
    ctx.strokeStyle = col; ctx.lineWidth = 1.8; ctx.setLineDash([6, 3]); ctx.globalAlpha = 0.55;
    ctx.beginPath();
    ctx.moveTo(xScale(x1ma), yScale(Math.max(minCC, Math.min(maxCC, y1cc))));
    ctx.lineTo(xScale(x2ma), yScale(Math.max(minCC, Math.min(maxCC, y2cc))));
    ctx.stroke(); ctx.restore();
  });

  // Points
  chartData = [];
  species.forEach(sp => {
    const cx = xScale(sp.val_time);
    const cy = yScale(sp.cc);
    const selected = !chartSelectedIds || chartSelectedIds.has(sp.id);
    const isHover = chartHoverSp && chartHoverSp.id === sp.id;
    const col = CLADE_COLORS[sp.clado] || '#888';
    const r = isHover ? 9 : 7;
    ctx.save();
    ctx.globalAlpha = selected ? (isHover ? 1 : 0.85) : 0.18;
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2);
    ctx.fillStyle = col; ctx.fill();
    ctx.strokeStyle = 'white'; ctx.lineWidth = 1.5; ctx.stroke();
    if (sp.estado === 'debatida') {
      ctx.strokeStyle = '#f5b800'; ctx.lineWidth = 1.5; ctx.setLineDash([2,1]);
      ctx.beginPath(); ctx.arc(cx, cy, r+2, 0, Math.PI*2); ctx.stroke();
    }
    ctx.restore();
    chartData.push({ sp, cx, cy, r: 8 });
  });

  // Hover tooltip
  if (chartHoverSp) {
    const pt = chartData.find(p => p.sp.id === chartHoverSp.id);
    if (pt) {
      const col = CLADE_COLORS[chartHoverSp.clado] || '#888';
      ctx.save();
      const tw = 190, th = 62, tx = Math.min(pt.cx + 14, w - PAD.right - tw - 4), ty = Math.max(PAD.top + 4, pt.cy - 34);
      ctx.fillStyle = '#1c2b3a'; ctx.globalAlpha = 0.92;
      roundRect(ctx, tx, ty, tw, th, 8); ctx.fill();
      ctx.globalAlpha = 1;
      ctx.fillStyle = '#fff'; ctx.font = `italic bold 12px Playfair Display, serif`;
      ctx.textAlign = 'left'; ctx.fillText(chartHoverSp.nombre, tx+10, ty+18);
      ctx.font = `11px JetBrains Mono, monospace`; ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fillText(`${chartHoverSp.cc} cc · ${chartHoverSp.anos}`, tx+10, ty+34);
      ctx.fillStyle = col; ctx.fillText(CLADE_NAMES[chartHoverSp.clado]||chartHoverSp.clado, tx+10, ty+50);
      ctx.restore();
    }
  }

  // Legend
  const legend = document.getElementById('chartLegendEnhanced');
  if (legend) {
    const CLADE_NM = {basal:'Basales/Mioceno',australo:'Australopithecus',paran:'Paranthropus',homo:'Homo'};
    legend.innerHTML = Object.entries(CLADE_COLORS).map(([k,v]) => {
      const cnt = species.filter(s => s.clado === k).length;
    return `<div class="chart-leg-row" style="--legend-color:${v}"><div class="chart-leg-dot"></div><span>${CLADE_NM[k]||k} <span class="chart-leg-count">(${cnt})</span></span><div class="chart-leg-line"></div><span class="chart-leg-note">tendencia</span></div>`;
  }).join('') + `<div class="chart-leg-row"><div class="chart-leg-debated-dot"></div><span class="chart-leg-debated-label">Taxón debatido</span></div>`;
  }
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x+r, y); ctx.lineTo(x+w-r, y);
  ctx.arcTo(x+w, y, x+w, y+r, r);
  ctx.lineTo(x+w, y+h-r); ctx.arcTo(x+w, y+h, x+w-r, y+h, r);
  ctx.lineTo(x+r, y+h); ctx.arcTo(x, y+h, x, y+h-r, r);
  ctx.lineTo(x, y+r); ctx.arcTo(x, y, x+r, y, r);
  ctx.closePath();
}

function exportChartPNG() {
  const canvas = document.getElementById('encefChart');
  if (!canvas) return;
  const link = document.createElement('a');
  link.download = 'paleobot_encefalización.png';
  link.href = canvas.toDataURL('image/png');
  link.click();
}

function abrirEstadisticas() {
  chartZoom = { minMa: 0, maxMa: 23.5, minCC: 0, maxCC: 1750 };
  chartSelectMode = false;
  chartSelectedIds = null;
  chartHoverSp = null;
  document.getElementById('statsModal').classList.add('active');
  // Reset control states
  document.querySelectorAll('.chart-ctrl-btn[id^="zoom-"]').forEach(b => {
    b.classList.remove('active');
    b.setAttribute('aria-pressed', 'false');
  });
  const zAll = document.getElementById('zoom-all');
  if (zAll) {
    zAll.classList.add('active');
    zAll.setAttribute('aria-pressed', 'true');
  }
  const bsm = document.getElementById('btn-select-mode');
  if (bsm) {
    bsm.classList.remove('active');
    bsm.setAttribute('aria-pressed', 'false');
  }
  const brs = document.getElementById('btn-reset-sel');
  if (brs) brs.style.display = 'none';
  const csi = document.getElementById('chart-sel-info');
  if (csi) csi.style.display = 'none';
  requestAnimationFrame(() => {
    drawEncefChart();
    setupChartInteraction();
  });
}

let _chartInteractionSetup = false;
function setupChartInteraction() {
  if (_chartInteractionSetup) return;
  _chartInteractionSetup = true;
  const canvas = document.getElementById('encefChart');
  if (!canvas) return;

  canvas.addEventListener('mousemove', e => {
    const r = canvas.getBoundingClientRect();
    const mx = e.clientX - r.left, my = e.clientY - r.top;
    let found = null;
    for (const pt of chartData) {
      const d = Math.hypot(pt.cx - mx, pt.cy - my);
      if (d <= pt.r + 3) { found = pt.sp; break; }
    }
    chartHoverSp = found;
    const info = document.getElementById('chart-hover-info');
    if (info) info.textContent = found ? `${found.nombre} · ${found.cc} cc · ${found.anos}` : '';
    canvas.style.cursor = found ? 'pointer' : (chartSelectMode ? 'crosshair' : 'default');
    drawEncefChart();
  });

  canvas.addEventListener('mouseleave', () => {
    chartHoverSp = null;
    const info = document.getElementById('chart-hover-info');
    if (info) info.textContent = '';
    drawEncefChart();
  });

  canvas.addEventListener('click', e => {
    const r = canvas.getBoundingClientRect();
    const mx = e.clientX - r.left, my = e.clientY - r.top;
    let found = null;
    for (const pt of chartData) {
      if (Math.hypot(pt.cx - mx, pt.cy - my) <= pt.r + 3) { found = pt.sp; break; }
    }
    if (!found) return;
    if (chartSelectMode) {
      if (!chartSelectedIds) chartSelectedIds = new Set(chartData.map(p => p.sp.id));
      if (chartSelectedIds.has(found.id)) chartSelectedIds.delete(found.id);
      else chartSelectedIds.add(found.id);
      const cnt = chartSelectedIds.size;
      const selInfo = document.getElementById('chart-sel-info');
      const selCnt = document.getElementById('chart-sel-count');
      if (selInfo) selInfo.style.display = '';
      if (selCnt) selCnt.textContent = cnt;
      drawEncefChart();
    } else {
      document.getElementById('statsModal').classList.remove('active');
      showDetail(found);
    }
  });

  // Resize
  const obs = new ResizeObserver(() => drawEncefChart());
  obs.observe(canvas.parentElement);
}

