function getPrimateRecentReferences() {
  if (typeof RECENT_THEMATIC_REFS === 'undefined') return [];
  return RECENT_THEMATIC_REFS.filter(ref => /primatologia|hominoideos vivos/i.test(ref.theme || '')).slice(0, 6);
}

function renderPrimateModelCard(model) {
  return `<article class="primate-card">
    <h3>${escapeHtmlText(model.name)}</h3>
    <p><strong>${escapeHtmlText(model.taxon)}</strong> · ${escapeHtmlText(model.field)}</p>
    <p>${escapeHtmlText(model.value)}</p>
    <small><strong>Cautela:</strong> ${escapeHtmlText(model.caution)}</small>
    <div class="primate-pill-row">${model.traits.map(trait => `<span class="primate-pill">${escapeHtmlText(trait)}</span>`).join('')}</div>
  </article>`;
}

function renderPrimateTraitMatrix() {
  const rows = PRIMATE_TRAIT_MATRIX.map(row => `<tr>
    <td><strong>${escapeHtmlText(row.trait)}</strong></td>
    <td>${escapeHtmlText(row.apes)}</td>
    <td>${escapeHtmlText(row.hominin)}</td>
    <td><span class="primate-evidence ${escapeHtmlAttr(row.evidence)}">${escapeHtmlText(row.evidence === 'shared' ? 'compartido' : row.evidence === 'partial' ? 'parcial' : 'diferencial')}</span></td>
    <td>${escapeHtmlText(row.caution)}</td>
  </tr>`).join('');
  return `<div class="primate-matrix-wrap">
    <table class="primate-matrix">
      <thead><tr><th>Rasgo</th><th>Grandes simios vivos</th><th>Uso en evolucion humana</th><th>Lectura</th><th>Cautela</th></tr></thead>
      <tbody>${rows}</tbody>
    </table>
  </div>`;
}

function renderPrimateReferences() {
  const refs = getPrimateRecentReferences();
  if (!refs.length) return '<div class="primate-ref">No hay referencias recientes de primatologia cargadas en el bloque tematico.</div>';
  return `<div class="primate-ref-list">${refs.map(ref => `<article class="primate-ref">
    <strong>${escapeHtmlText(ref.a)} (${escapeHtmlText(ref.y)})</strong><br>
    ${escapeHtmlText(ref.t)}<br>
    <em>${escapeHtmlText(ref.j)}</em><br>
    ${renderDoiLink(ref.d)}
  </article>`).join('')}</div>`;
}

function renderPrimateAnalogyRules() {
  return `<div class="primate-analogy-grid">${PRIMATE_ANALOGY_RULES.map(rule => `<article class="primate-analogy-card">
    <strong>${escapeHtmlText(rule.title)}</strong>
    <span>${escapeHtmlText(rule.text)}</span>
  </article>`).join('')}</div>`;
}

function renderPrimateScenarioLab() {
  const labels = { aceptable: 'Aceptable', cautelosa: 'Con cautela', abusiva: 'Abusiva' };
  return `<div class="primate-scenario-grid">${PRIMATE_ANALOGY_SCENARIOS.map(scenario => `<article class="primate-scenario" data-primate-scenario-card="${escapeHtmlAttr(scenario.id)}">
    <h4>${escapeHtmlText(scenario.title)}</h4>
    <p>${escapeHtmlText(scenario.claim)}</p>
    <div class="primate-choice-row">
      ${Object.entries(labels).map(([value, label]) => `<button type="button" class="primate-choice" data-primate-choice="${escapeHtmlAttr(scenario.id)}:${escapeHtmlAttr(value)}">${escapeHtmlText(label)}</button>`).join('')}
    </div>
    <div class="primate-feedback" id="primate-feedback-${escapeHtmlAttr(scenario.id)}" aria-live="polite"></div>
  </article>`).join('')}</div>`;
}

function renderPrimateFieldworkCases() {
  return `<div class="primate-field-grid">${PRIMATE_FIELDWORK_CASES.map(item => `<article class="primate-field-card">
    <h4>${escapeHtmlText(item.name)}</h4>
    <p><strong>${escapeHtmlText(item.site)}</strong></p>
    <p>${escapeHtmlText(item.contribution)}</p>
    <p><strong>Leccion metodologica:</strong> ${escapeHtmlText(item.methodLesson)}</p>
    <small><strong>Cautela:</strong> ${escapeHtmlText(item.caution)}</small>
  </article>`).join('')}</div>`;
}

function renderPrimateStudyDesign() {
  return `<div class="primate-design-grid">${PRIMATE_STUDY_DESIGN_STEPS.map((item, index) => `<article class="primate-design-card">
    <h4><span>${index + 1}</span>${escapeHtmlText(item.step)}</h4>
    <p>${escapeHtmlText(item.example)}</p>
            <small><strong>Riesgo metodológico:</strong> ${escapeHtmlText(item.pitfall)}</small>
  </article>`).join('')}</div>`;
}

function answerPrimateScenario(scenarioId, choice) {
  const scenario = PRIMATE_ANALOGY_SCENARIOS.find(item => item.id === scenarioId);
  if (!scenario) return;
  const card = Array.from(document.querySelectorAll('[data-primate-scenario-card]'))
    .find(el => el.dataset.primateScenarioCard === scenarioId);
  const feedback = document.getElementById('primate-feedback-' + scenarioId);
  if (!card || !feedback) return;
  card.querySelectorAll('.primate-choice').forEach(btn => {
    const selected = btn.dataset.primateChoice === `${scenarioId}:${choice}`;
    const correct = btn.dataset.primateChoice === `${scenarioId}:${scenario.answer}`;
    btn.classList.toggle('is-correct', correct);
    btn.classList.toggle('is-wrong', selected && !correct);
  });
  const ok = choice === scenario.answer;
  feedback.className = 'primate-feedback visible ' + (ok ? 'ok' : 'warn');
  feedback.textContent = (ok ? 'Respuesta adecuada. ' : 'Revisa la inferencia. ') + scenario.feedback;
}

function renderPrimatologyView() {
  const container = document.getElementById('primateContent');
  if (!container) return;
  container.innerHTML = `
    <div class="primate-head">
      <div class="primate-head-main">
        <span class="primate-kicker">Primatología comparada</span>
        <h2>Grandes simios vivos como modelos parciales, no como ancestros</h2>
        <p>Este módulo conecta etología, anatomía comparada y evolución humana. Su objetivo es didáctico y metodológico: mostrar que chimpancés, bonobos, gorilas y orangutanes permiten formular hipótesis, pero no sustituyen al registro fósil ni representan estados ancestrales puros.</p>
      </div>
      <div class="primate-method-card">
        <span class="primate-kicker">Regla de lectura</span>
        <p><strong>Comparar no es identificar.</strong> Un rasgo compartido puede ser homología, convergencia o respuesta ecológica semejante. Para usar una analogía con homininos hay que explicitar el puente: anatomía, conducta, ambiente, genética o arqueología.</p>
        <div class="primate-action-row">
          <button type="button" class="primate-action-btn" data-teaching-export="template:primatologia">Descargar plantilla de comparación</button>
          <button type="button" class="primate-action-btn secondary" data-teaching-export="template:observacion-primates">Cuaderno de observación</button>
          <button type="button" class="primate-action-btn secondary" data-action="abrirBiblio">Ver bibliografía</button>
        </div>
      </div>
    </div>
    <div class="primate-section-title"><h3>Modelos comparativos principales</h3><span>Etología y cautela</span></div>
    <div class="primate-grid">${PRIMATE_MODELS.map(renderPrimateModelCard).join('')}</div>
    <div class="primate-section-title"><h3>Matriz de rasgos comparados</h3><span>Del comportamiento vivo a la inferencia fósil</span></div>
    ${renderPrimateTraitMatrix()}
    <div class="primate-section-title"><h3>Trabajo de campo y método</h3><span>De la observación longitudinal a la inferencia</span></div>
    ${renderPrimateFieldworkCases()}
    <div class="primate-section-title"><h3>Diseño de investigación</h3><span>Del dato observado a la pregunta</span></div>
    ${renderPrimateStudyDesign()}
    <div class="primate-section-title"><h3>Protocolo de analogía responsable</h3><span>Método antes que relato</span></div>
    ${renderPrimateAnalogyRules()}
    <div class="primate-section-title"><h3>Semáforo de inferencias</h3><span>Actividad autocorregida</span></div>
    ${renderPrimateScenarioLab()}
    <div class="primate-caution">
      <div><strong>No son fósiles vivientes</strong><span>Las especies actuales también han evolucionado desde su divergencia con el linaje humano.</span></div>
      <div><strong>La conducta no fosiliza sola</strong><span>Debe cruzarse con herramientas, marcas, tafonomía, anatomía y contexto paleoambiental.</span></div>
      <div><strong>Evitar relatos lineales</strong><span>La comparación sirve para razonar, no para ordenar a los primates en una escala de progreso.</span></div>
    </div>
    <div class="primate-section-title"><h3>Referencias recientes del atlas</h3><span>Bibliografía verificada</span></div>
    ${renderPrimateReferences()}
  `;
}

