function renderTeachingDataTable(rows) {
  const body = rows.map(row => {
    const sp = DB_INDEX[row.id];
    const completeness = getTeachingCompletenessLabel(sp);
    return `<tr>
      <td><button type="button" class="teaching-tax-btn" data-open-species="${escapeHtmlAttr(row.id)}">${escapeHtmlText(row.taxon)}</button></td>
      <td>${escapeHtmlText(row.clado)}</td>
      <td>${escapeHtmlText(row.cronologia)}</td>
      <td>${escapeHtmlText(row.ubicacion)}</td>
      <td>${escapeHtmlText(row.yacimiento_holotipo)}</td>
      <td>${escapeHtmlText(row.datacion || 'No indicada')}</td>
      <td><span class="teaching-risk ${escapeHtmlAttr(completeness.cls)}">${escapeHtmlText(row.evidencia)}</span><br><small>${escapeHtmlText(row.modulos_fosiles)}</small></td>
      <td>${escapeHtmlText(row.paleogenomica)}</td>
      <td>${escapeHtmlText(row.paleoproteomica)}</td>
      <td>${escapeHtmlText(row.doi_verificados)}</td>
    </tr>`;
  }).join('');
  return `<div class="teaching-data-wrap">
    <div class="teaching-data-scroll">
      <table class="teaching-data-table">
        <thead><tr><th>Taxon</th><th>Clado</th><th>Cronologia</th><th>Region</th><th>Yacimiento / holotipo</th><th>Datacion</th><th>Evidencia</th><th>Paleogenomica</th><th>Paleoproteómica</th><th>DOI</th></tr></thead>
        <tbody>${body || `<tr><td colspan="10">No hay registros visibles con los filtros activos.</td></tr>`}</tbody>
      </table>
    </div>
  </div>`;
}

