// ── MAPA PAN/ZOOM state ──────────────────────────────────────
const MAP_VW = 1000, MAP_VH = 500;           // SVG coordinate space
let mapVB = { x: 0, y: 0, w: MAP_VW, h: MAP_VH };  // current viewBox
let mapIsDragging = false, mapDragStart = null, mapDragVB = null;
let mapSelectionId = null;
let mapActiveLensId = null;

// ── Coordinate helpers ───────────────────────────────────────
function mapProject(lat, lng) {
    return [((lng + 180) / 360) * MAP_VW, ((90 - lat) / 180) * MAP_VH];
}

// Convert DOM client point → SVG coordinate
function clientToSVG(svg, cx, cy) {
    const r = svg.getBoundingClientRect();
    const sx = (cx - r.left) / r.width;
    const sy = (cy - r.top) / r.height;
    return [mapVB.x + sx * mapVB.w, mapVB.y + sy * mapVB.h];
}

function applyMapViewBox() {
    const svg = document.getElementById('mapSvg');
    if (!svg) return;
    const vb = mapVB;
    svg.setAttribute('viewBox', `${vb.x.toFixed(2)} ${vb.y.toFixed(2)} ${vb.w.toFixed(2)} ${vb.h.toFixed(2)}`);
    const zoom = MAP_VW / vb.w;
    const ro = document.getElementById('mapZoomReadout');
    if (ro) ro.textContent = `${Math.round(zoom * 100)}%`;
    if (svg.dataset.rendered) updateDotRadii();
}

function clampViewBox() {
    const m = 0.05; // allow 5% overflow for comfort
    const minW = MAP_VW / 8, maxW = MAP_VW;
    mapVB.w = Math.max(minW, Math.min(maxW, mapVB.w));
    mapVB.h = mapVB.w * (MAP_VH / MAP_VW);
    mapVB.x = Math.max(-MAP_VW * m, Math.min(MAP_VW * (1 + m) - mapVB.w, mapVB.x));
    mapVB.y = Math.max(-MAP_VH * m, Math.min(MAP_VH * (1 + m) - mapVB.h, mapVB.y));
}

function zoomMapToward(cx, cy, factor) {
    // cx, cy in SVG coords; factor < 1 = zoom in
    const newW = mapVB.w * factor;
    const newH = mapVB.h * factor;
    mapVB.x = cx - (cx - mapVB.x) * (newW / mapVB.w);
    mapVB.y = cy - (cy - mapVB.y) * (newH / mapVB.h);
    mapVB.w = newW;
    mapVB.h = newH;
    clampViewBox();
    applyMapViewBox();
}

function setMapZoom(mode) {
    const cx = mapVB.x + mapVB.w / 2;
    const cy = mapVB.y + mapVB.h / 2;
    if (mode === 'in')    zoomMapToward(cx, cy, 1 / 1.35);
    if (mode === 'out')   zoomMapToward(cx, cy, 1.35);
    if (mode === 'reset') { mapVB = { x: 0, y: 0, w: MAP_VW, h: MAP_VH }; applyMapViewBox(); }
}

function applyMapZoom() { applyMapViewBox(); } // kept for backwards compatibility

function zoomMapToRegion(lens) {
    const vb = getLensPixelBounds(lens);
    const padX = vb.w * 0.18;
    const centerX = vb.x + vb.w / 2;
    const centerY = vb.y + vb.h / 2;
    const targetW = Math.max(MAP_VW / 3, Math.min(MAP_VW, vb.w + padX * 2));
    mapVB.x = centerX - targetW / 2;
    mapVB.y = centerY - (targetW * (MAP_VH / MAP_VW)) / 2;
    mapVB.w = targetW;
    mapVB.h = mapVB.w * (MAP_VH / MAP_VW);
    clampViewBox();
    applyMapViewBox();
}

function initMapPanZoom() {
    const svg = document.getElementById('mapSvg');
    if (!svg || svg._pzInit) return;
    svg._pzInit = true;

    // ─── Mouse wheel zoom ────────────────────────────────────
    svg.addEventListener('wheel', e => {
        e.preventDefault();
        const [sx, sy] = clientToSVG(svg, e.clientX, e.clientY);
        const factor = e.deltaY > 0 ? 1.18 : 1 / 1.18;
        zoomMapToward(sx, sy, factor);
    }, { passive: false });

    // ─── Mouse drag pan ──────────────────────────────────────
    let dragClientStart = null;
    svg.addEventListener('mousedown', e => {
        if (e.button !== 0) return;
        if (e.target.closest('.map-node, .map-region-frame')) return;
        mapIsDragging = true;
        dragClientStart = { x: e.clientX, y: e.clientY };
        mapDragVB = { ...mapVB };
        svg.classList.add('is-dragging');
        e.preventDefault();
    });
    window.addEventListener('mousemove', e => {
        if (!mapIsDragging || !dragClientStart) return;
        const r = svg.getBoundingClientRect();
        const pxW = r.width, pxH = r.height;
        const dx = (dragClientStart.x - e.clientX) / pxW * mapDragVB.w;
        const dy = (dragClientStart.y - e.clientY) / pxH * mapDragVB.h;
        mapVB = { ...mapDragVB, x: mapDragVB.x + dx, y: mapDragVB.y + dy };
        clampViewBox();
        applyMapViewBox();
    });
    window.addEventListener('mouseup', () => {
        if (!mapIsDragging) return;
        mapIsDragging = false;
        dragClientStart = null;
        svg.classList.remove('is-dragging');
    });

    // ─── Touch pan/pinch ─────────────────────────────────────
    let touchClientStart = null, touchVBStart = null, pinchDist0 = null;
    svg.addEventListener('touchstart', e => {
        if (e.touches.length === 1) {
            const t = e.touches[0];
            touchClientStart = { x: t.clientX, y: t.clientY };
            touchVBStart = { ...mapVB };
        } else if (e.touches.length === 2) {
            pinchDist0 = Math.hypot(
                e.touches[0].clientX - e.touches[1].clientX,
                e.touches[0].clientY - e.touches[1].clientY
            );
            touchVBStart = { ...mapVB };
        }
        e.preventDefault();
    }, { passive: false });
    svg.addEventListener('touchmove', e => {
        e.preventDefault();
        const r = svg.getBoundingClientRect();
        if (e.touches.length === 1 && touchClientStart && touchVBStart) {
            const t = e.touches[0];
            const dx = (touchClientStart.x - t.clientX) / r.width  * touchVBStart.w;
            const dy = (touchClientStart.y - t.clientY) / r.height * touchVBStart.h;
            mapVB = { ...touchVBStart, x: touchVBStart.x + dx, y: touchVBStart.y + dy };
            clampViewBox();
            applyMapViewBox();
        } else if (e.touches.length === 2 && pinchDist0 !== null && touchVBStart) {
            const dist = Math.hypot(
                e.touches[0].clientX - e.touches[1].clientX,
                e.touches[0].clientY - e.touches[1].clientY
            );
            const factor = pinchDist0 / dist;
            const midCX = (e.touches[0].clientX + e.touches[1].clientX) / 2;
            const midCY = (e.touches[0].clientY + e.touches[1].clientY) / 2;
            const [sx, sy] = clientToSVG(svg, midCX, midCY);
            mapVB = { ...touchVBStart };
            const newW = Math.max(MAP_VW / 8, Math.min(MAP_VW, touchVBStart.w * factor));
            const scaleRatio = newW / touchVBStart.w;
            mapVB.x = sx - (sx - touchVBStart.x) * scaleRatio;
            mapVB.y = sy - (sy - touchVBStart.y) * scaleRatio;
            mapVB.w = newW;
            mapVB.h = newW * (MAP_VH / MAP_VW);
            clampViewBox();
            applyMapViewBox();
        }
    }, { passive: false });
    svg.addEventListener('touchend', () => { touchClientStart = null; pinchDist0 = null; });
}

function updateDotRadii() {
    const svg = document.getElementById('mapSvg');
    if (!svg || !svg.dataset.rendered) return;

    const containerW = svg.getBoundingClientRect().width || 700;
    const svgUnitsPerPx = mapVB.w / containerW;

    svg.querySelectorAll('.map-node').forEach(node => {
        const sp = DB_INDEX[node.dataset.id];
        if (!sp) return;
        const core = node.querySelector('.map-dot-core');
        if (!core) return;
        // Target screen size: 4.5–7px depending on cranial capacity
        const targetPx = sp.cc ? Math.min(7, 4.5 + Math.sqrt(sp.cc / 400)) : 5;
        const svgR = (targetPx * svgUnitsPerPx).toFixed(2);
        core.setAttribute('r', svgR);
        const hit = node.querySelector('.map-dot-hit');
        if (hit) hit.setAttribute('r', ((targetPx + 8) * svgUnitsPerPx).toFixed(2));
    });

    // Scale anchor lines too
    svg.querySelectorAll('.map-node line').forEach(l => {
        l.setAttribute('stroke-width', (0.5 * svgUnitsPerPx).toFixed(2));
    });

    // Region frames: hidden when zoomed past 2×
    const zoom = MAP_VW / mapVB.w;
    svg.querySelectorAll('.map-region-frame').forEach(f => {
        f.style.display = zoom > 2.2 ? 'none' : '';
    });
}

function getLensPixelBounds(lens) {
    const [x1, y1] = mapProject(lens.bounds.maxLat, lens.bounds.minLng);
    const [x2, y2] = mapProject(lens.bounds.minLat, lens.bounds.maxLng);
    return { x: x1, y: y1, w: Math.max(x2 - x1, 10), h: Math.max(y2 - y1, 10) };
}

function getLensVisibleSpecies(lens, visibleSpecies) {
    return visibleSpecies.filter(sp => {
        const coords = SITES[sp.id];
        if (!coords) return false;
        const [lat, lng] = coords;
        return lat >= lens.bounds.minLat && lat <= lens.bounds.maxLat &&
               lng >= lens.bounds.minLng && lng <= lens.bounds.maxLng;
    });
}

function getLensIdForSpecies(sp) {
    if (!sp || !SITES[sp.id]) return null;
    const [lat, lng] = SITES[sp.id];
    const hit = MAP_LENSES.find(lens =>
        lat >= lens.bounds.minLat && lat <= lens.bounds.maxLat &&
        lng >= lens.bounds.minLng && lng <= lens.bounds.maxLng
    );
    return hit ? hit.id : null;
}

function getLensById(id) {
    return MAP_LENSES.find(lens => lens.id === id) || null;
}

function speciesMatchesLens(sp, lensId) {
    if (!lensId) return true;
    const lens = getLensById(lensId);
    if (!lens || !SITES[sp.id]) return false;
    const [lat, lng] = SITES[sp.id];
    return lat >= lens.bounds.minLat && lat <= lens.bounds.maxLat &&
           lng >= lens.bounds.minLng && lng <= lens.bounds.maxLng;
}

function formatCoords(lat, lng) {
    const latTxt = lat >= 0 ? `${Math.abs(lat).toFixed(1)}°N` : `${Math.abs(lat).toFixed(1)}°S`;
    const lngTxt = lng >= 0 ? `${Math.abs(lng).toFixed(1)}°E` : `${Math.abs(lng).toFixed(1)}°W`;
    return `${latTxt}, ${lngTxt}`;
}

let showMigrations = true;

function getMapVisibleSpecies() {
    const term = normalizeForSearch(document.getElementById('searchInput')?.value || '');
    return DB.filter(sp => {
        if (!SITES[sp.id]) return false;
        if (!matchesActiveFilters(sp)) return false;
        if (!term) return true;
        const haystack = normalizeForSearch([sp.nombre, sp.ubicacion, sp.holo, sp.anos].join(' '));
        return haystack.includes(term);
    });
}

function renderMapRegionGuide(visibleSpecies) {
    const wrap = document.getElementById('mapRegionGuide');
    if (!wrap) return;
    const total = visibleSpecies.length;
    const allActive = !mapActiveLensId;
    const allButton = `<button type="button" class="map-region-pill ${allActive ? 'active' : ''}" data-map-lens="all" aria-pressed="${allActive}">
      Todos los focos <span class="map-region-pill-count">${total}</span>
    </button>`;
    const regionButtons = MAP_LENSES.map(lens => {
        const count = getLensVisibleSpecies(lens, visibleSpecies).length;
        const active = mapActiveLensId === lens.id;
        return `<button type="button" class="map-region-pill ${active ? 'active' : ''}" data-map-lens="${escapeHtmlAttr(lens.id)}" aria-pressed="${active}">
          ${lens.label}<span class="map-region-pill-count">${count}</span>
        </button>`;
    }).join('');
    wrap.innerHTML = allButton + regionButtons;
}

function renderMapLearningLab(visibleSpecies) {
    const host = document.getElementById('mapLearningLab');
    if (!host) return;
    const visible = Array.isArray(visibleSpecies) ? visibleSpecies : [];
    const activeLens = getLensById(mapActiveLensId);
    const selected = mapSelectionId ? DB_INDEX[mapSelectionId] : null;
    const focusSpecies = activeLens ? visible.filter(sp => speciesMatchesLens(sp, activeLens.id)) : visible;
    const oldest = focusSpecies.length ? focusSpecies.reduce((best, sp) => ((sp.val_time || 0) > (best.val_time || 0) ? sp : best), focusSpecies[0]) : null;
    const youngest = focusSpecies.length ? focusSpecies.reduce((best, sp) => ((sp.val_time || 0) < (best.val_time || 0) ? sp : best), focusSpecies[0]) : null;
    const debatedCount = focusSpecies.filter(sp => sp.estado && sp.estado !== 'aceptada').length;
    const lensLabel = activeLens ? activeLens.label : 'vista global';
    const selectedText = selected && SITES[selected.id]
      ? `${selected.nombre}: ${selected.ubicacion}, ${formatCoords(...SITES[selected.id])}`
      : 'elige un marcador para convertir el mapa en evidencia localizada';
    const focusRange = oldest && youngest
      ? `${escapeHtmlText(formatMaRange(getSpeciesTimeRange(oldest).start, getSpeciesTimeRange(youngest).end))}`
      : 'sin rango visible';
    const strongestLens = MAP_LENSES
      .map(lens => ({ lens, count: getLensVisibleSpecies(lens, visible).length }))
      .sort((a, b) => b.count - a.count)[0];
    const suggestedLens = activeLens || strongestLens?.lens || null;
    const suggestedLensText = suggestedLens
      ? `${suggestedLens.label}${strongestLens && !activeLens ? ` (${strongestLens.count} visibles)` : ''}`
      : 'un foco regional';
    host.innerHTML = `
      <section class="map-learning-panel" aria-label="Laboratorio didáctico de mapas">
        <span class="map-learning-kicker">Lectura cartográfica guiada</span>
        <h3>Convierte el mapa en una hipótesis, no en una lista de puntos.</h3>
        <p>Usa el mapa para relacionar territorio, tiempo y calidad de evidencia. La pregunta no es solo dónde aparece un fósil, sino qué permite inferir ese lugar cuando se combina con cronología, yacimiento y método.</p>
        <div class="map-learning-metrics">
          <div class="map-learning-metric"><strong>${escapeHtmlText(String(focusSpecies.length))}</strong><span>taxones en ${escapeHtmlText(lensLabel)}</span></div>
          <div class="map-learning-metric"><strong>${focusRange}</strong><span>rango cronológico visible</span></div>
          <div class="map-learning-metric"><strong>${escapeHtmlText(String(debatedCount))}</strong><span>casos debatidos o en revisión</span></div>
        </div>
        <div class="map-learning-question"><strong>Consigna rápida:</strong> trabaja ${escapeHtmlText(suggestedLensText)}, selecciona el taxón más antiguo y el más reciente visibles, y explica si el patrón sugiere continuidad regional, dispersión, sesgo de preservación o simple falta de datos.</div>
      </section>
      <section class="map-learning-panel dark" aria-label="Cautelas científicas del mapa">
        <span class="map-learning-kicker">Mapa con cautela</span>
        <h3>Protocolo de análisis en tres pasos</h3>
        <div class="map-learning-steps">
          <div class="map-learning-step"><b>1</b><div><strong>Localiza</strong><span>${escapeHtmlText(selectedText)}.</span></div></div>
          <div class="map-learning-step"><b>2</b><div><strong>Temporaliza</strong><span>Compara edad, método de datación y posible solapamiento con otros taxones de la región.</span></div></div>
          <div class="map-learning-step"><b>3</b><div><strong>Argumenta</strong><span>Redacta una inferencia y una cautela: qué dato apoya la hipótesis y qué dato falta.</span></div></div>
        </div>
        <div class="map-learning-cautions">
          <ul>
            <li>Un punto representa yacimiento o hallazgo, no el área completa ocupada por una población.</li>
            <li>Las rutas de dispersión son esquemas interpretativos; no deben leerse como caminos exactos.</li>
            <li>La capa paleoambiental resume escenarios, pero no reconstruye cada microhábitat local.</li>
          </ul>
        </div>
      </section>`;
}

function refreshMapFocusVisuals(visibleSpecies) {
    const svg = document.getElementById('mapSvg');
    if (!svg) return;
    const lensId = mapActiveLensId;
    svg.querySelectorAll('.map-region-frame').forEach(frame => {
        frame.classList.toggle('active', !!lensId && frame.dataset.lens === lensId);
    });
    svg.querySelectorAll('.map-node').forEach(node => {
        const sp = DB_INDEX[node.dataset.id];
        const isDimmed = lensId && sp ? !speciesMatchesLens(sp, lensId) : false;
        node.classList.toggle('is-dimmed', !!isDimmed);
        node.classList.toggle('is-selected', node.dataset.id === mapSelectionId);
    });
}

function setMapLensFocus(lensId) {
    const visibleSpecies = getMapVisibleSpecies();
    const normalized = lensId === 'all' ? null : lensId;
    const candidateLens = normalized ? getLensById(normalized) : null;
    const candidateItems = candidateLens ? getLensVisibleSpecies(candidateLens, visibleSpecies) : visibleSpecies;
    mapActiveLensId = candidateItems.length ? normalized : null;
    // Zoom map to region if one is selected, else reset to full view
    if (mapActiveLensId) {
        const lens = getLensById(mapActiveLensId);
        if (lens) zoomMapToRegion(lens);
    } else {
        setMapZoom('reset');
    }
    renderMapRegionGuide(visibleSpecies);
    renderMapLearningLab(visibleSpecies);
    renderMapSiteList(visibleSpecies);
    renderMapLensGrid(visibleSpecies);
    refreshMapFocusVisuals(visibleSpecies);
    const preferredPool = mapActiveLensId ? visibleSpecies.filter(sp => speciesMatchesLens(sp, mapActiveLensId)) : visibleSpecies;
    const preferred = preferredPool.find(sp => sp.id === mapSelectionId)?.id || preferredPool[0]?.id || null;
    if (preferred) {
        selectMapSpecies(preferred);
    } else {
        mapSelectionId = null;
        refreshMapFocusVisuals(visibleSpecies);
        renderMapSelectionCard(null);
    }
    renderPaleoEnvironmentOverlay();
}

function renderMapSelectionCard(sp) {
    const card = document.getElementById('mapSelectionCard');
    const focus = document.getElementById('mapFocusLabel');
    if (!card || !focus) return;
    if (!sp || !SITES[sp.id]) {
        const lens = getLensById(mapActiveLensId);
        focus.textContent = lens ? `Foco regional activo: ${lens.label}` : 'Selecciona un yacimiento para fijar la ubicación';
        card.innerHTML = `<div class="map-selection-empty">${lens ? `La lectura está centrada en <strong>${lens.label}</strong>. Elige un marcador dentro de esa región o pulsa “Todos los focos” para recuperar la vista completa.` : 'Selecciona un marcador para ver la ubicación exacta, las coordenadas y un acceso rápido a la ficha completa.'}</div>`;
        return;
    }
    const [lat, lng] = SITES[sp.id];
    const lensId = getLensIdForSpecies(sp);
    const lens = getLensById(lensId);
    const stateWarn = sp.estado && sp.estado !== 'aceptada';
    const stateLabel = stateWarn ? (sp.estado === 'debatida' ? 'Debatida' : 'En revisión') : 'Aceptada';
    const safeMapName = escapeHtmlText(sp.nombre);
    const safeMapLocation = escapeHtmlText(sp.ubicacion);
    const safeMapCoords = escapeHtmlText(formatCoords(lat, lng));
    const safeMapCladeName = escapeHtmlText(CLADE_NAMES[sp.clado] || sp.clado);
    const safeMapCladeClass = escapeHtmlAttr(sp.clado === 'basal' ? 'pt-badge-basal' : sp.clado === 'australo' ? 'pt-badge-australo' : sp.clado === 'paran' ? 'pt-badge-paran' : 'pt-badge-homo');
    const safeMapYears = escapeHtmlText(sp.anos);
    const safeMapHolotype = escapeHtmlText(sp.holo);
    const safeMapCc = escapeHtmlText(sp.cc ? sp.cc + ' cc' : 'No disponible');
    const safeMapLensLabel = escapeHtmlText(lens ? lens.label : 'Fuera de las lentes principales');
    const safeMapStateLabel = escapeHtmlText(stateLabel);
    const safeMapId = escapeHtmlAttr(sp.id);
    focus.textContent = `${sp.nombre} · ${sp.ubicacion} · ${formatCoords(lat, lng)}`;
    const summary = sp.descripcion.length > 220 ? sp.descripcion.slice(0, 220) + '…' : sp.descripcion;
    card.innerHTML = `
      <div class="map-selection-head">
        <h3>${safeMapName}</h3>
        <span class="map-status-chip ${stateWarn ? 'warn' : 'ok'}">${safeMapStateLabel}</span>
      </div>
      <div class="map-selection-badges">
        <span class="pt-badge ${safeMapCladeClass}">${safeMapCladeName}</span>
        <span class="pt-badge">${safeMapYears}</span>
      </div>
      <div class="map-kpi-grid">
        <div class="map-kpi"><label>Ubicación</label><div>${safeMapLocation}</div></div>
        <div class="map-kpi"><label>Coordenadas</label><div>${safeMapCoords}</div></div>
        <div class="map-kpi"><label>Holotipo</label><div>${safeMapHolotype}</div></div>
        <div class="map-kpi"><label>Capacidad craneal</label><div>${safeMapCc}</div></div>
        <div class="map-kpi"><label>Región de lectura</label><div>${safeMapLensLabel}</div></div>
      </div>
      <div class="map-selection-actions">
        <button type="button" class="map-action-btn primary" data-open-species="${safeMapId}"><span class="ico" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><rect x="2" y="5" width="20" height="14" rx="2"/><circle cx="9" cy="12" r="2"/><path d="M15 9h4M15 12h4M15 15h2M5 16c0-1.1.9-2 2-2h4a2 2 0 0 1 2 2"/></svg></span> Abrir ficha</button>
        <button type="button" class="map-action-btn secondary" data-map-zoom="reset"><span class="ico" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><circle cx="12" cy="12" r="10"/><line x1="22" y1="12" x2="18" y2="12"/><line x1="6" y1="12" x2="2" y2="12"/><line x1="12" y1="6" x2="12" y2="2"/><line x1="12" y1="22" x2="12" y2="18"/></svg></span> Resetear mapa</button>
      </div>
      <div class="map-selection-note">${escapeHtmlText(summary)}</div>`;
}

function renderMapSiteList(visibleSpecies) {
    const list = document.getElementById('mapSiteList');
    const count = document.getElementById('mapVisibleListCount');
    if (!list || !count) return;
    count.textContent = `${visibleSpecies.length}`;
    if (!visibleSpecies.length) {
        list.innerHTML = `<div class="map-selection-empty">No hay yacimientos visibles con los filtros actuales.</div>`;
        return;
    }
    const ordered = [...visibleSpecies].sort((a, b) => (b.val_time || 0) - (a.val_time || 0));
    list.innerHTML = ordered.map(sp => {
        const [lat, lng] = SITES[sp.id];
        const lensId = getLensIdForSpecies(sp);
        const muted = mapActiveLensId && lensId !== mapActiveLensId;
        const safeId = escapeHtmlAttr(sp.id);
        const safeName = escapeHtmlText(sp.nombre);
        const safeYears = escapeHtmlText(sp.anos);
        const safeLocation = escapeHtmlText(sp.ubicacion);
        const safeCoords = escapeHtmlText(formatCoords(lat, lng));
        const safeLensLabel = escapeHtmlText(getLensById(lensId)?.label || 'Foco secundario');
        return `<button type="button" class="map-site-item ${mapSelectionId === sp.id ? 'active' : ''} ${muted ? 'muted' : ''}" data-map-list-id="${safeId}" data-map-select="${safeId}">
          <div class="map-site-item-head">
            <div class="map-site-item-title">${safeName}</div>
            <div class="map-site-item-meta">${safeYears}</div>
          </div>
          <div class="map-site-item-sub">
            <span>${safeLocation}</span>
            <span>·</span>
            <span>${safeCoords}</span>
            <span>·</span>
            <span>${safeLensLabel}</span>
          </div>
        </button>`;
    }).join('');
}

function renderMapLensGrid(visibleSpecies) {
    const grid = document.getElementById('mapLensGrid');
    if (!grid) return;
    const selected = mapSelectionId ? DB_INDEX[mapSelectionId] : null;
    grid.innerHTML = MAP_LENSES.map(lens => {
        const items = getLensVisibleSpecies(lens, visibleSpecies);
        const active = mapActiveLensId === lens.id;
        if (!items.length) {
            return `<article class="map-lens-card ${active ? 'active' : ''}" data-map-lens="${escapeHtmlAttr(lens.id)}">
              <div class="map-lens-top">
                <div><strong>${lens.label}</strong><span>${lens.hint}</span></div>
                <div class="map-lens-count">0 visibles</div>
              </div>
              <div class="map-lens-empty">Sin yacimientos visibles en esta región con los filtros actuales.</div>
            </article>`;
        }
        const vb = getLensPixelBounds(lens);
        // Scale radius so dots are always ~2% of the viewBox width regardless of region size
        const lensR     = Math.max(2, vb.w * 0.022);
        const lensRSel  = lensR * 1.45;
        const markerHtml = items.map(sp => {
            const [lat, lng] = SITES[sp.id];
            const [x, y] = mapProject(lat, lng);
            const color = CLADE_COLORS[sp.clado] || '#777';
            const isActive = mapSelectionId === sp.id;
            const r = isActive ? lensRSel : lensR;
            return `<g class="map-lens-node ${isActive ? 'active' : ''}" data-map-select="${escapeHtmlAttr(sp.id)}">
              <circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r.toFixed(1)}" fill="${color}"
                      stroke="white" stroke-width="${(r * 0.28).toFixed(1)}" opacity="${isActive ? '1' : '0.88'}"></circle>
            </g>`;
        }).join('');
        const oldest = Math.max(...items.map(sp => getSpeciesTimeRange(sp).start));
        const youngest = Math.min(...items.map(sp => getSpeciesTimeRange(sp).end));
        const topoSrc = lens.topoImg || 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Physical_Map/MapServer/export?f=image&format=png32&bbox=-180%2C-85%2C180%2C85&bboxSR=4326&imageSR=4326&size=512%2C256&transparent=false';
        return `<article class="map-lens-card ${active ? 'active' : ''}" data-map-lens="${escapeHtmlAttr(lens.id)}">
          <div class="map-lens-top">
            <div><strong>${lens.label}</strong><span>${lens.hint}</span></div>
            <div class="map-lens-count">${items.length} visibles</div>
          </div>
          <div class="map-lens-stage">
            <img class="map-lens-topo" src="${topoSrc}" alt="Topografía ${lens.label}" loading="lazy"
              data-pb-map-lens-source="regional">
            <svg viewBox="${vb.x.toFixed(1)} ${vb.y.toFixed(1)} ${vb.w.toFixed(1)} ${vb.h.toFixed(1)}" preserveAspectRatio="xMidYMid meet" aria-label="${lens.label}">
              <rect class="map-lens-bounds" x="${vb.x.toFixed(1)}" y="${vb.y.toFixed(1)}" width="${vb.w.toFixed(1)}" height="${vb.h.toFixed(1)}" fill="none" stroke="${lens.accent}" stroke-width="1.5" stroke-dasharray="6,4"/>
              ${markerHtml}
            </svg>
          </div>
          <div class="map-lens-footer">
            <strong style="display:block;font-size:0.8rem;color:var(--primary);margin-bottom:4px">${items[0].nombre}${items.length > 1 ? ` + ${items.length - 1}` : ''}</strong>
            <em>${formatMaRange(oldest, youngest)}</em>
          </div>
        </article>`;
    }).join('');
}

function selectMapSpecies(id) {
    const sp = DB_INDEX[id];
    if (!sp || !SITES[id]) return;
    mapSelectionId = id;
    mapActiveLensId = getLensIdForSpecies(sp);
    document.querySelectorAll('.map-node').forEach(node => {
        node.classList.toggle('is-selected', node.dataset.id === id);
    });
    document.querySelectorAll('[data-map-list-id]').forEach(node => {
        node.classList.toggle('active', node.dataset.mapListId === id);
    });
    // Update the focus label
    const lbl = document.getElementById('mapFocusLabel');
    if (lbl) lbl.textContent = `${sp.nombre} · ${sp.ubicacion}`;
    const visibleSpecies = getMapVisibleSpecies();
    renderMapRegionGuide(visibleSpecies);
    renderMapLearningLab(visibleSpecies);
    renderMapSiteList(visibleSpecies);
    refreshMapFocusVisuals(visibleSpecies);
    renderMapSelectionCard(sp);
    renderMapLensGrid(visibleSpecies);
}

function toggleMigrations(btn) {
    showMigrations = !showMigrations;
    btn.classList.toggle('active', showMigrations);
    btn.setAttribute('aria-pressed', String(showMigrations));
    const svg = document.getElementById('mapSvg');
    if (!svg) return;
    svg.querySelectorAll('.mig-path').forEach(el => {
        el.style.display = showMigrations ? '' : 'none';
    });
}

function renderMapView() {
    const svg = document.getElementById('mapSvg');
    if (!svg) return;
    if (svg.dataset.rendered) {
        updateMapDots();
        return;
    }

    const VW = MAP_VW, VH = MAP_VH;
    function pt(lat, lng) {
        return [((lng + 180) / 360) * VW, ((90 - lat) / 180) * VH];
    }

    const grouped = {};
    Object.entries(SITES).forEach(([id, coords]) => {
        if (!DB_INDEX[id]) return;
        const key = `${coords[0].toFixed(2)},${coords[1].toFixed(2)}`;
        (grouped[key] ||= []).push({ sp: DB_INDEX[id], lat: coords[0], lng: coords[1] });
    });

    let html = `<defs>
      <marker id="arrowMig" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="3" markerHeight="3" orient="auto">
        <path d="M0 0 L10 5 L0 10 z" fill="rgba(80,100,160,0.5)"/>
      </marker>
      <marker id="arrowSap" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="3" markerHeight="3" orient="auto">
        <path d="M0 0 L10 5 L0 10 z" fill="rgba(10,107,73,0.65)"/>
      </marker>
      <filter id="dotGlow" x="-80%" y="-80%" width="260%" height="260%">
        <feGaussianBlur in="SourceGraphic" stdDeviation="3" result="blur"/>
        <feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge>
      </filter>
    </defs>`;

    // Subtle grid
    for (let lat = -60; lat <= 60; lat += 30) {
        const [, y] = pt(lat, 0);
        html += `<line x1="0" y1="${y.toFixed(1)}" x2="${VW}" y2="${y.toFixed(1)}" stroke="rgba(255,255,255,0.18)" stroke-width="0.6"/>`;
    }
    for (let lng = -150; lng <= 150; lng += 30) {
        const [x] = pt(0, lng);
        html += `<line x1="${x.toFixed(1)}" y1="0" x2="${x.toFixed(1)}" y2="${VH}" stroke="rgba(255,255,255,0.12)" stroke-width="0.6"/>`;
    }

    // Region frames — dashed border only, no SVG text (pills below handle labelling)
    MAP_LENSES.forEach(lens => {
        const vb = getLensPixelBounds(lens);
        html += `<g class="map-region-frame" data-lens="${lens.id}" style="cursor:pointer">
          <rect x="${vb.x.toFixed(1)}" y="${vb.y.toFixed(1)}" width="${vb.w.toFixed(1)}" height="${vb.h.toFixed(1)}"
                fill="none" stroke="${lens.accent}" stroke-width="1.8" stroke-dasharray="8 5" rx="3"/>
        </g>`;
    });

    // Migration arcs
    MIGRATIONS.forEach(m => {
        const [fLat, fLng, cLat, cLng, tLat, tLng, , color] = m;
        const [fx, fy] = pt(fLat, fLng);
        const [cx, cy] = pt(cLat, cLng);
        const [tx, ty] = pt(tLat, tLng);
        const isSap = color.includes('6b49');
        const marker = isSap ? 'url(#arrowSap)' : 'url(#arrowMig)';
        const stroke = isSap ? 'rgba(10,107,73,0.28)' : 'rgba(80,100,160,0.24)';
        const dashArr = isSap ? '3,2' : '6,3';
        html += `<path class="mig-path" d="M${fx.toFixed(1)},${fy.toFixed(1)} Q${cx.toFixed(1)},${cy.toFixed(1)} ${tx.toFixed(1)},${ty.toFixed(1)}"
                  fill="none" stroke="${stroke}" stroke-width="${isSap ? 1 : 0.8}"
                  stroke-dasharray="${dashArr}" marker-end="${marker}"/>`;
    });

    // Species dots with labels
    Object.values(grouped).forEach(group => {
        const { lat, lng } = group[0];
        const [anchorX, anchorY] = pt(lat, lng);
        if (group.length > 1) {
            html += `<circle cx="${anchorX.toFixed(1)}" cy="${anchorY.toFixed(1)}" r="2.5" fill="rgba(28,43,58,0.28)" pointer-events="none"/>`;
        }
        group.sort((a, b) => (b.sp.cc || 0) - (a.sp.cc || 0));
        group.forEach((entry, idx) => {
            const total = group.length;
            const angle = total > 1 ? (-Math.PI / 2) + ((Math.PI * 2) / total) * idx : 0;
            const spread = total > 1 ? (total <= 2 ? 14 : total <= 4 ? 20 : total <= 7 ? 28 : 36) : 0;
            const x = anchorX + Math.cos(angle) * spread;
            const y = anchorY + Math.sin(angle) * spread;
            const sp = entry.sp;
            const color = CLADE_COLORS[sp.clado] || '#888';
            const opacity = sp.estado === 'debatida' ? '0.60' : '0.92';
            // r starts at 0 — updateDotRadii() sets correct screen-pixel size on every zoom change
            html += `<g class="map-node" data-id="${escapeHtmlAttr(sp.id)}" data-clado="${escapeHtmlAttr(sp.clado)}"
                         data-nombre="${escapeHtmlAttr(sp.nombre)}"
                         data-ubicacion="${escapeHtmlAttr(sp.ubicacion)}"
                         data-search="${escapeHtmlAttr(normalizeForSearch([sp.nombre, sp.ubicacion, sp.holo, sp.anos].join(' ')))}">
              ${total > 1 ? `<line x1="${anchorX.toFixed(1)}" y1="${anchorY.toFixed(1)}" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}" stroke="rgba(28,43,58,0.10)" stroke-width="0.4" pointer-events="none"/>` : ''}
              <circle class="map-dot-core" cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="1"
                      fill="${color}" stroke="white" stroke-width="0.9" opacity="${opacity}"/>
              <circle class="map-dot-hit" cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="4"
                      fill="transparent" stroke="none"/>
            </g>`;
        });
    });

    // Append generated nodes to SVG (image element already exists)
    const parser = new DOMParser();
    const doc = parser.parseFromString(`<svg xmlns="http://www.w3.org/2000/svg">${html}</svg>`, 'image/svg+xml');
    Array.from(doc.documentElement.childNodes).forEach(n => svg.appendChild(document.adoptNode(n.cloneNode(true))));

    svg.dataset.rendered = '1';

    // Legend
    const legend = document.getElementById('mapLegend');
    if (legend) {
        legend.innerHTML = Object.entries(CLADE_COLORS).map(([k, v]) =>
            `<div class="map-legend-item"><svg width="14" height="14"><circle cx="7" cy="7" r="6" fill="${v}" stroke="white" stroke-width="1.5"/></svg>${CLADE_NAMES[k]}</div>`
        ).join('') +
        `<div class="map-legend-item" style="margin-left:8px"><svg width="18" height="10"><line x1="0" y1="5" x2="16" y2="5" stroke="rgba(80,100,160,0.6)" stroke-width="1.5" stroke-dasharray="4,2"/></svg>Dispersión</div>
         <div class="map-legend-item"><svg width="18" height="10"><line x1="0" y1="5" x2="16" y2="5" stroke="rgba(10,107,73,0.6)" stroke-width="1.5" stroke-dasharray="3,2"/></svg>H. sapiens</div>
         <div class="map-legend-item" style="color:var(--text-hint);font-style:italic">⚬ Tamaño ∝ CC</div>`;
    }

    // Tooltip
    const tip = document.getElementById('phyloTooltip');
    const MAX_CC_T = 1800;
    const BADGE_CL = {basal:'pt-badge-basal',australo:'pt-badge-australo',paran:'pt-badge-paran',homo:'pt-badge-homo'};

    function _posTip(e) {
        const TW = tip.offsetWidth || 260;
        const TH = tip.offsetHeight || 180;
        let L = e.clientX + 18, T = e.clientY - 16;
        if (L + TW + 12 > window.innerWidth) L = e.clientX - TW - 14;
        if (T + TH + 12 > window.innerHeight) T = e.clientY - TH - 8;
        if (T < 8) T = 8;
        tip.style.left = L + 'px';
        tip.style.top = T + 'px';
    }

    // Helper: SVG coord → container % position for the floating label
    function svgToContainerPct(svgX, svgY) {
        return [
            ((svgX - mapVB.x) / mapVB.w) * 100,
            ((svgY - mapVB.y) / mapVB.h) * 100
        ];
    }

    const hoverLbl = document.getElementById('mapHoverLabel');

    svg.querySelectorAll('.map-node').forEach(el => {
        const sp = DB_INDEX[el.dataset.id];
        if (!sp) return;
        // Get the dot core position from SVG element
        const dotCore = el.querySelector('.map-dot-core');
        const dotCX = dotCore ? parseFloat(dotCore.getAttribute('cx')) : 0;
        const dotCY = dotCore ? parseFloat(dotCore.getAttribute('cy')) : 0;

        el.addEventListener('mouseenter', e => {
            // Tooltip
            document.getElementById('pt-name').textContent = sp.nombre;
            document.getElementById('pt-anos').textContent = sp.anos;
            document.getElementById('pt-loc').textContent = sp.ubicacion;
            document.getElementById('pt-holo').textContent = sp.holo;
            document.getElementById('pt-badge-wrap').innerHTML =
                `<span class="pt-badge ${escapeHtmlAttr(BADGE_CL[sp.clado] || '')}">${escapeHtmlText(CLADE_NAMES[sp.clado] || sp.clado)}</span>` +
                (sp.estado && sp.estado !== 'aceptada' ? `<span class="pt-badge pt-badge-debatida">⚠ ${sp.estado === 'debatida' ? 'Debatida' : 'En revisión'}</span>` : '');
            const ccWrap = document.getElementById('pt-cc-wrap');
            if (sp.cc) {
                ccWrap.style.display = '';
                document.getElementById('pt-cc').textContent = sp.cc + ' cc';
                document.getElementById('pt-cc-fill').style.width = Math.round((sp.cc / MAX_CC_T) * 100) + '%';
                document.getElementById('pt-cc-fill').style.background = CLADE_COLORS[sp.clado] || '#888';
            } else { ccWrap.style.display = 'none'; }
            tip.classList.add('visible');
            _posTip(e);
            // Floating label
            if (hoverLbl) {
                const shortName = sp.nombre.replace('Homo ','H. ').replace('Australopithecus ','A. ')
                    .replace('Paranthropus ','P. ').replace('Ardipithecus ','Ar. ')
                    .replace('Orrorin ','Or. ').replace('Sahelanthropus ','S. ')
                    .replace('Kenyanthropus ','K. ').replace('Dryopithecus ','D. ')
                    .replace('Proconsul ','Pr. ').replace('Morotopithecus ','Mo. ')
                    .replace('Graecopithecus ','Gr. ');
                hoverLbl.textContent = shortName;
                const [px, py] = svgToContainerPct(dotCX, dotCY);
                hoverLbl.style.left = px + '%';
                hoverLbl.style.top  = py + '%';
                hoverLbl.classList.add('visible');
            }
        });
        el.addEventListener('mousemove', e => {
            _posTip(e);
            // Keep label synced to dot position (stays fixed; no need to update on move)
        });
        el.addEventListener('mouseleave', () => {
            tip.classList.remove('visible');
            if (hoverLbl) hoverLbl.classList.remove('visible');
        });
        el.addEventListener('click', e => {
            e.stopPropagation();
            tip.classList.remove('visible');
            if (hoverLbl) hoverLbl.classList.remove('visible');
            selectMapSpecies(sp.id);
        });
    });

    svg.querySelectorAll('.map-region-frame').forEach(frame => {
        frame.addEventListener('click', e => {
            e.stopPropagation();
            const lens = getLensById(frame.dataset.lens);
            if (lens) zoomMapToRegion(lens);
            setMapLensFocus(frame.dataset.lens);
        });
    });

    initMapPanZoom();
    applyMapViewBox();       // sets viewBox + calls updateDotRadii
    updateMapDots();
}

function updateMapDots() {
    const svg = document.getElementById('mapSvg');
    if (!svg) return;
    const visibleSpecies = getMapVisibleSpecies();
    const visibleIds = new Set(visibleSpecies.map(sp => sp.id));
    let visible = 0;
    svg.querySelectorAll('.map-node').forEach(node => {
        const show = visibleIds.has(node.dataset.id);
        node.style.display = show ? '' : 'none';
        if (show) visible++;
    });
    const cnt = document.getElementById('mapCount');
    if (cnt) cnt.textContent = `${visible} / ${Object.keys(SITES).length} marcadores visibles`;
    if (mapActiveLensId && !visibleSpecies.some(sp => speciesMatchesLens(sp, mapActiveLensId))) {
        mapActiveLensId = null;
    }
    renderMapRegionGuide(visibleSpecies);
    renderMapLearningLab(visibleSpecies);
    renderMapSiteList(visibleSpecies);
    renderMapLensGrid(visibleSpecies);
    const focusedSpecies = mapActiveLensId ? visibleSpecies.filter(sp => speciesMatchesLens(sp, mapActiveLensId)) : visibleSpecies;
    refreshMapFocusVisuals(visibleSpecies);
    const preferred = focusedSpecies.find(sp => sp.id === mapSelectionId)?.id ||
        (currentSpecies && focusedSpecies.some(sp => sp.id === currentSpecies.id) ? currentSpecies.id : (focusedSpecies[0]?.id || null));
    if (preferred) {
        selectMapSpecies(preferred);
    } else {
        mapSelectionId = null;
        refreshMapFocusVisuals(visibleSpecies);
        renderMapSelectionCard(null);
    }
    renderPaleoEnvironmentOverlay();
}

// ══════════════════════════════════════════════════════════════
// MODO PRESENTACIÓN / EXPOSICIÓN
// ══════════════════════════════════════════════════════════════

let presSpecies  = [];   // list of species shown in presentation
let presBaseSpecies = []; // visible species when the presentation opens
let presIndex    = 0;
let presAutoMode = false;
let presAutoTimer = null;
let presFilterCC = false; // only species with CC data
const PRES_AUTO_SEC = 8;
const PRES_ICON_SVG = {
  time: '<svg viewBox="0 0 24 24" fill="none" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/><path d="M5 5l-2 2M19 5l2 2"/></svg>',
  cranial: '<svg viewBox="0 0 24 24" fill="none" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 18c-2.4-1.3-4-3.8-4-6.8C4 6.7 7.6 3 12.1 3S20 6.4 20 10.7c0 3.5-1.8 6.3-4.6 7.7"/><path d="M8 18v2h8v-2"/><path d="M9 9.5h.01M15 9.5h.01"/><path d="M9 14c1.9 1.2 4.1 1.2 6 0"/></svg>',
  diet: '<svg viewBox="0 0 24 24" fill="none" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 3c4.5 1.1 7 4.2 7.2 9.4C9.1 12.4 6 9.5 7 3z"/><path d="M14.2 12.4c2.1-3.1 4-4.6 5.8-4.4.3 4-1.7 6.5-6 7.6"/><path d="M12 13c-1.6 2.5-2 5-1.1 8"/><path d="M14 15c1.8 1.4 2.9 3.4 3.3 6"/></svg>'
};

const PRES_CLADE_BG = {
  basal:   'rgba(192,120,0,0.22)',
  australo:'rgba(10,107,73,0.22)',
  paran:   'rgba(170,31,31,0.22)',
  homo:    'rgba(26,79,160,0.22)'
};
const PRES_CLADE_NM = {basal:'Basales / Mioceno',australo:'Australopithecus',paran:'Paranthropus',homo:'Homo'};
const PRES_DIDACTIC_BY_CLADE = {
  basal: {
    key: 'Sitúa el taxón dentro del problema del origen: no todo hominoideo temprano es hominino, pero todos ayudan a reconstruir el repertorio anatómico disponible.',
    question: '¿Qué rasgos permiten separar una semejanza primitiva de una auténtica señal de parentesco hominino?'
  },
  australo: {
    key: 'Lee la especie como mosaico: bipedismo habitual, cerebro reducido y adaptaciones ecológicas variables conviven en combinaciones no lineales.',
    question: '¿Qué evidencia demuestra bipedismo y qué rasgos impiden imaginar una transición directa hacia Homo?'
  },
  paran: {
    key: 'Interpreta la robustez como especialización adaptativa, no como atraso evolutivo: mandíbula, dientes y dieta forman un paquete funcional.',
    question: '¿La especialización masticatoria indica éxito ecológico, callejón evolutivo o ambas cosas según la escala temporal?'
  },
  homo: {
    key: 'Relaciona anatomía, tecnología y dispersión sin convertir cada coincidencia estratigráfica en causalidad directa.',
    question: '¿Qué datos permiten vincular cerebro, herramientas, movilidad y conducta social sin sobreinterpretar el registro?'
  }
};

function getPresentationPool() {
  const visible = DB.filter(matchesActiveFilters);
  return visible.length ? visible : DB.slice();
}

function refreshPresentationSpecies() {
  const base = presBaseSpecies.length ? presBaseSpecies : getPresentationPool();
  const filtered = presFilterCC ? base.filter(s => s.cc != null) : base.slice();
  presSpecies = filtered.length ? filtered : base.slice();
  if (presIndex >= presSpecies.length) presIndex = Math.max(0, presSpecies.length - 1);
}

function openPresentation() {
  // BUG-A FIX: limpiar estado previo
  closeDetailPanel();
  currentSpecies = null;

  presFilterCC = false;
  presBaseSpecies = getPresentationPool();
  refreshPresentationSpecies();
  presIndex = 0;

  // FIX B-3 v32: guardia de pool vacío — si el filtro activo deja 0 especies,
  // resetear filtros temporalmente para que la presentación tenga contenido.
  if (!presSpecies.length) {
    presBaseSpecies = DB.slice();
    presSpecies = DB.slice();
    Logger.warn('openPresentation: pool vacío con filtros activos — usando catálogo completo.');
    const infoPanel = document.getElementById('presInfoPanel');
    if (infoPanel) {
      const warn = document.createElement('div');
      warn.style.cssText = 'position:absolute;top:8px;left:50%;transform:translateX(-50%);background:#fef3c7;border:1px solid #d97706;border-radius:8px;padding:6px 14px;font-size:0.72rem;font-family:\'JetBrains Mono\',monospace;color:#92400e;z-index:10;white-space:nowrap;';
      warn.textContent = 'Sin especies con el filtro activo — mostrando catálogo completo';
      infoPanel.style.position = 'relative';
      infoPanel.prepend(warn);
      setTimeout(() => warn.remove(), 4000);
    }
  }

  const filterBtn = document.getElementById('presFilterBtn');
  if (filterBtn) {
    filterBtn.classList.remove('active');
    filterBtn.setAttribute('aria-pressed', 'false');
  }

  // ORDEN CORREGIDO: activar el overlay ANTES de renderizar.
  // renderPresSlide() usa getBoundingClientRect() en el canvas del mini-gráfico CC;
  // si el overlay está display:none, el canvas tiene dimensiones 0 y el gráfico
  // se pinta con ancho incorrecto. Activar primero garantiza dimensiones reales.
  const overlay = document.getElementById('presOverlay');
  if (!overlay) { Logger.error('presOverlay not found'); return; }
  overlay.classList.add('active');
  overlay.setAttribute('aria-hidden', 'false');
  document.body.classList.add('pres-active');
  document.body.style.overflow = 'hidden';
  const presentationInfoPanel = document.getElementById('presInfoPanel');
  if (presentationInfoPanel) presentationInfoPanel.scrollTop = 0;
  document.addEventListener('keydown', presKeyHandler);
  updateBackButtonState();

  // Renderizar en el siguiente frame para que el navegador haya aplicado display:flex
  requestAnimationFrame(function() {
    try {
      buildPresDots();
      renderPresSlide();
      if (presentationInfoPanel) presentationInfoPanel.scrollTop = 0;
    } catch (err) {
      Logger.error('Error al renderizar diapositiva inicial:', err);
      // Mostrar error visible dentro del overlay para diagnóstico
      const infoPanel = document.getElementById('presInfoPanel');
      if (infoPanel) {
        infoPanel.innerHTML =
          '<div class="render-error" style="margin:40px;background:#fef2f2;border:1px solid #fca5a5;border-radius:10px;padding:20px;color:#7f1d1d;font-size:0.9rem;">' +
          '<strong>Error al cargar la presentación</strong><br>' +
          '<code style="font-size:0.78rem;word-break:break-all">' + String(err).substring(0, 300) + '</code>' +
          '</div>';
      }
    }
  });
}

function closePresentation() {
  // BUG-B FIX: si el handler de flechas abrió el panel detrás del overlay,
  // cerrarlo aquí para que no quede huérfano visible al desaparecer el overlay.
  closePresMapModal();
  closeDetailPanel();
  const overlay = document.getElementById('presOverlay');
  if (overlay) {
    overlay.classList.remove('active');
    overlay.setAttribute('aria-hidden', 'true');
  }
  document.body.classList.remove('pres-active');
  document.body.style.overflow = '';
  document.removeEventListener('keydown', presKeyHandler);
  stopPresAuto();
  presAutoMode = false;
  const autoBtn = document.getElementById('presAutoBtn');
  if (autoBtn) {
    autoBtn.classList.remove('active');
    autoBtn.setAttribute('aria-pressed', 'false');
  }
  updateBackButtonState();
}

function presKeyHandler(e) {
  if (e.key === 'Escape') {
    if (closePresMapModal()) {
      e.preventDefault();
      return;
    }
    closePresentation();
    return;
  }
  if (document.getElementById('presMapModal')?.classList.contains('active')) return;
  if (e.key === 'ArrowRight' || e.key === ' ') { e.preventDefault(); presNav(1); }
  if (e.key === 'ArrowLeft')   { e.preventDefault(); presNav(-1); }
}

function togglePresFilter() {
  presFilterCC = !presFilterCC;
  const btn = document.getElementById('presFilterBtn');
  if (btn) {
    btn.classList.toggle('active', presFilterCC);
    btn.setAttribute('aria-pressed', presFilterCC ? 'true' : 'false');
  }
  refreshPresentationSpecies();
  presIndex = 0;
  buildPresDots();
  renderPresSlide();
}

function buildPresDots() {
  const container = document.getElementById('presDots');
  if (!container) return;
  const total = presSpecies.length;
  const visibleIndexes = new Set([0, total - 1]);
  for (let i = presIndex - 3; i <= presIndex + 3; i++) {
    if (i >= 0 && i < total) visibleIndexes.add(i);
  }
  const ordered = [...visibleIndexes].sort((a, b) => a - b);
  let previous = -1;
  container.innerHTML = ordered.map(i => {
    const gap = previous >= 0 && i - previous > 1 ? '<span class="pres-dot-gap" aria-hidden="true">…</span>' : '';
    previous = i;
    const sp = presSpecies[i];
    return gap + '<button type="button" class="pres-dot' + (i === presIndex ? ' active' : '') + '" data-pres-jump="' + i + '" aria-label="Ir a diapositiva ' + (i + 1) + ': ' + escapeHtmlAttr(sp.nombre) + '" title="' + escapeHtmlAttr((i + 1) + '/' + total + ' · ' + sp.nombre) + '"></button>';
  }).join('');
}

function presJump(i) {
  if (!Number.isFinite(i) || i < 0 || i >= presSpecies.length) return;
  presIndex = i;
  buildPresDots();
  renderPresSlide();
}

function presNav(dir) {
  const n = presIndex + dir;
  if (n < 0 || n >= presSpecies.length) return;
  presIndex = n;
  try {
    buildPresDots();
    renderPresSlide();
  } catch (err) {
    Logger.error('presNav render error:', err);
  }
  if (presAutoMode) resetPresAutoTimer();
}

function presOpenDetail() {
  const sp = presSpecies[presIndex];
  if (!sp) return;
  closePresentation();
  setTimeout(() => showDetail(sp), 200);
}

function openPresMapModal() {
  const sp = presSpecies[presIndex];
  if (!sp) return;
  const modal = document.getElementById('presMapModal');
  const body = document.getElementById('presMapModalBody');
  const title = document.getElementById('presMapModalTitle');
  const sub = document.getElementById('presMapModalSub');
  const foot = document.getElementById('presMapModalFoot');
  const sourceSvg = document.getElementById('presMapSvg');
  if (!modal || !body || !sourceSvg) return;

  const clone = sourceSvg.cloneNode(true);
  clone.removeAttribute('id');
  clone.setAttribute('aria-label', 'Mapa ampliado del yacimiento de ' + (sp.nombre || 'taxón'));
  clone.setAttribute('role', 'img');
  body.innerHTML = '';
  body.appendChild(clone);

  if (title) title.textContent = 'Mapa ampliado: ' + (sp.nombre || 'taxón seleccionado');
  if (sub) sub.textContent = sp.ubicacion || 'Localización no indicada';
  if (foot) {
    const locHtml = document.getElementById('presLocLabel')?.innerHTML || '';
    foot.innerHTML = `<strong>Objetivo de lectura:</strong> explicar por qué la localización importa para interpretar el hallazgo, no memorizar un punto del mapa. ${locHtml ? '<br>' + locHtml : ''}<div class="pres-map-modal-guide">
      <span><b>1. Escala global</b><br>Ubica el continente y el corredor geográfico general.</span>
      <span><b>2. Escala regional</b><br>Relaciona relieve, cuenca o costa con conservación y datación.</span>
      <span><b>3. Cautela</b><br>Proximidad espacial no significa parentesco directo ni contacto seguro.</span>
    </div>`;
  }

  modal.classList.add('active');
  modal.setAttribute('aria-hidden', 'false');
  const closeBtn = modal.querySelector('[data-pres-map-close]');
  if (closeBtn) closeBtn.focus({ preventScroll: true });
  updateBackButtonState();
}

function closePresMapModal() {
  const modal = document.getElementById('presMapModal');
  if (!modal || !modal.classList.contains('active')) return false;
  modal.classList.remove('active');
  modal.setAttribute('aria-hidden', 'true');
  const body = document.getElementById('presMapModalBody');
  if (body) body.innerHTML = '';
  const trigger = document.querySelector('[data-pres-map-expand]');
  if (trigger) trigger.focus({ preventScroll: true });
  updateBackButtonState();
  return true;
}

// ── AUTO-AVANCE ────────────────────────────────────────────────
function togglePresAuto() {
  presAutoMode = !presAutoMode;
  const btn = document.getElementById('presAutoBtn');
  if (btn) {
    btn.classList.toggle('active', presAutoMode);
    btn.setAttribute('aria-pressed', presAutoMode ? 'true' : 'false');
    btn.innerHTML = presAutoMode
      ? '<span class="ico" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg></span> Auto'
      : '<span class="ico" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"/></svg></span> Auto';
  }
  if (presAutoMode) resetPresAutoTimer();
  else stopPresAuto();
}

function resetPresAutoTimer() {
  stopPresAuto();
  const bar = document.getElementById('presTimerBar');
  if (bar) { bar.style.transition = 'none'; bar.style.width = '0%'; }
  requestAnimationFrame(() => {
    if (bar) {
      bar.style.transition = 'width ' + PRES_AUTO_SEC + 's linear';
      bar.style.width = '100%';
    }
  });
  presAutoTimer = setTimeout(() => {
    if (presIndex < presSpecies.length - 1) presNav(1);
    else presIndex = 0;
    buildPresDots();
    renderPresSlide();
    if (presAutoMode) resetPresAutoTimer();
  }, PRES_AUTO_SEC * 1000);
}

function stopPresAuto() {
  if (presAutoTimer) { clearTimeout(presAutoTimer); presAutoTimer = null; }
  const bar = document.getElementById('presTimerBar');
  if (bar) { bar.style.transition = 'none'; bar.style.width = '0%'; }
}

function buildPresentationTeaching(sp) {
  const cladeGuide = PRES_DIDACTIC_BY_CLADE[sp.clado] || PRES_DIDACTIC_BY_CLADE.homo;
  const debate = sp.experto?.debate || '';
  const anatomy = sp.experto?.anatomia_postcraneal || sp.experto?.anatomia_craneal || sp.experto?.descripcion_tecnica || '';
  const ecology = sp.experto?.paleoecologia || '';
  const chips = [
    sp.estado && sp.estado !== 'aceptada' ? `Estado: ${sp.estado}` : 'Estado: aceptada',
    sp.datacion ? `Datación: ${sp.datacion}` : '',
    sp.herramientas && !/^(Ninguna|No)$/i.test(sp.herramientas) ? `Cultura material: ${sp.herramientas}` : 'Sin industria segura'
  ].filter(Boolean).map(item => `<span class="pres-teaching-chip">${escapeHtmlText(item)}</span>`).join('');

  let question = cladeGuide.question;
  if (sp.estado === 'debatida' || sp.estado === 'revision') {
    question = '¿Qué evidencia adicional sería necesaria para estabilizar la clasificación de este taxón?';
  } else if (sp.herramientas && !/^(Ninguna|No)$/i.test(sp.herramientas)) {
    question = '¿La asociación con herramientas es directa, contextual o solo plausible dentro del yacimiento?';
  }

  const keyEvidence = anatomy || ecology || debate || cladeGuide.key;
  const keyText = keyEvidence.length > 220 ? keyEvidence.slice(0, 220) + '…' : keyEvidence;

  return `<div class="pres-teaching-item key">
    <strong>Clave de lectura</strong>
    <p>${escapeHtmlText(cladeGuide.key)}</p>
    <div class="pres-teaching-evidence">${chips}</div>
  </div>
  <div class="pres-teaching-item question">
    <strong>Pregunta didáctica</strong>
    <p>${escapeHtmlText(question)}</p>
    <div class="pres-teaching-evidence"><span class="pres-teaching-chip">${escapeHtmlText(keyText)}</span></div>
  </div>`;
}

// ── RENDER SLIDE ───────────────────────────────────────────────
function renderPresSlide() {
  const sp = presSpecies[presIndex];
  if (!sp) return;

  const col  = CLADE_COLORS[sp.clado] || '#888';
  const total = presSpecies.length;
  const num   = presIndex + 1;
  const media = getSpeciesMedia(sp);

  // Animate info panel
  const panel = document.getElementById('presInfoPanel');
  if (panel) {
    panel.scrollTop = 0;
    panel.classList.remove('pres-slide-anim');
    void panel.offsetWidth; // reflow
    panel.classList.add('pres-slide-anim');
  }

  // Image
  const img = document.getElementById('presImg');
  const bgBlur = document.getElementById('presBgBlur');
  if (img) {
    img.src = media.url || '';
    img.alt = media.titulo || sp.nombre || 'Imagen de especie';
    img.decoding = 'async';
  }
  if (bgBlur) bgBlur.style.backgroundImage = 'url("' + (buildImageThumbUrl(media.url, 500) || '').replace(/"/g, '%22') + '")';

  const mediaCaption = document.getElementById('presMediaCaption');
  if (mediaCaption) {
    mediaCaption.innerHTML = '<strong>' + escapeHtmlText(media.titulo || 'Imagen de referencia') + '</strong>' +
      '<span>' + escapeHtmlText(media.tipo || 'imagen') + ' · ' + escapeHtmlText(media.fuente || 'fuente no indicada') + '</span>';
  }

  // Clade strip
  const strip = document.getElementById('presCladoStrip');
  if (strip) strip.style.background = col;

  // Index badge
  const badge = document.getElementById('presIndexBadge');
  if (badge) badge.textContent = num + ' / ' + total;

  // Clado tag
  const cladoTag = document.getElementById('presCladoTag');
  if (cladoTag) {
    cladoTag.style.background = PRES_CLADE_BG[sp.clado] || 'rgba(255,255,255,0.08)';
    cladoTag.style.color = col;
    cladoTag.style.border = '1px solid ' + col.replace(')', ',0.35)').replace('rgb','rgba');
    cladoTag.innerHTML = '<span class="pres-clade-dot"></span> ' + (PRES_CLADE_NM[sp.clado] || sp.clado);
    cladoTag.style.setProperty('--pres-clade-color', col);
  }

  // Name
  const nameEl = document.getElementById('presName');
  if (nameEl) nameEl.textContent = sp.nombre;

  // Subname (holotipo + datacion)
  const subEl = document.getElementById('presSubname');
  if (subEl) subEl.textContent = 'Holotipo: ' + sp.holo + '  ·  Datación: ' + sp.datacion;

  // Status badges
  const statusRow = document.getElementById('presStatusRow');
  if (statusRow) {
    const ESTADO_LBL = {aceptada:'Aceptada',debatida:'Debatida',revision:'En revisión'};
    const est = sp.estado || 'aceptada';
    statusRow.innerHTML =
      '<span class="pres-status-pill ' + escapeHtmlAttr(est) + '">' + (ESTADO_LBL[est]||est) + '</span>' +
      (sp.herramientas && sp.herramientas !== 'Ninguna' && sp.herramientas !== 'No'
        ? '<span class="pres-status-pill tool">Industria: ' + escapeHtmlText(sp.herramientas) + '</span>' : '');
  }

  // Stats
  const statsEl = document.getElementById('presStats');
  if (statsEl) {
    statsEl.innerHTML =
      '<div class="pres-stat"><span class="pres-stat-icon">' + PRES_ICON_SVG.time + '</span><span class="pres-stat-val">' + escapeHtmlText(sp.anos || '—') + '</span><span class="pres-stat-lbl">Cronología</span></div>' +
      '<div class="pres-stat"><span class="pres-stat-icon">' + PRES_ICON_SVG.cranial + '</span><span class="pres-stat-val">' + escapeHtmlText(sp.cc ? sp.cc + ' cc' : '—') + '</span><span class="pres-stat-lbl">Cap. craneal</span></div>' +
      '<div class="pres-stat"><span class="pres-stat-icon">' + PRES_ICON_SVG.diet + '</span><span class="pres-stat-val compact">' + escapeHtmlText(sp.dieta || '—') + '</span><span class="pres-stat-lbl">Dieta</span></div>';
  }

  // Description (first 420 chars)
  const descEl = document.getElementById('presDesc');
  if (descEl) {
    const d = sp.descripcion || '';
    descEl.textContent = d.length > 440 ? d.slice(0, 440) + '…' : d;
  }

  const teachingEl = document.getElementById('presTeachingCard');
  if (teachingEl) teachingEl.innerHTML = buildPresentationTeaching(sp);

  // Nav info
  const navInfo = document.getElementById('presNavInfo');
  if (navInfo) navInfo.innerHTML = 'Ubicación: ' + escapeHtmlText(sp.ubicacion) + ' · ' + num + '/' + total + '<br><span style="opacity:0.62">← → teclado · espacio avanzar · botón Volver atrás / Esc cerrar</span>';

  // Nav buttons
  const prevBtn = document.getElementById('presPrevBtn');
  const nextBtn = document.getElementById('presNextBtn');
  if (prevBtn) prevBtn.disabled = presIndex === 0;
  if (nextBtn) nextBtn.disabled = presIndex === presSpecies.length - 1;

  // Dots update
  document.querySelectorAll('.pres-dot').forEach(d => d.classList.toggle('active', Number(d.dataset.presJump) === presIndex));

  // Mini map
  renderPresMap(sp, col);

  // Mini CC chart
  renderPresCCChart(sp, col);
}

const PRES_MAP_CONTEXTS = [
  { id:'east_africa', label:'Rift africano / cuencas del Turkana-Awash-Olduvai', bounds:{ minLat:-8, maxLat:18, minLng:28, maxLng:46 } },
  { id:'south_africa', label:'Karst sudafricano y Africa austral', bounds:{ minLat:-35, maxLat:-10, minLng:18, maxLng:34 } },
  { id:'north_africa', label:'Magreb y corredor sahariano', bounds:{ minLat:18, maxLat:38, minLng:-15, maxLng:28 } },
  { id:'europe', label:'Europa y Mediterraneo', bounds:{ minLat:34, maxLat:56, minLng:-12, maxLng:48 } },
  { id:'caucasus', label:'Caucaso y puerta euroasiatica', bounds:{ minLat:35, maxLat:48, minLng:34, maxLng:52 } },
  { id:'east_asia', label:'Asia oriental e interior continental', bounds:{ minLat:24, maxLat:55, minLng:74, maxLng:132 } },
  { id:'island_asia', label:'Sudeste asiatico insular y Pacifico occidental', bounds:{ minLat:-12, maxLat:22, minLng:95, maxLng:130 } }
];

const PRES_WORLD_LAND_PATHS = [
  'M83 118 C129 81 193 82 230 120 C257 146 251 181 221 196 C188 213 160 199 130 221 C105 239 76 218 69 181 C65 155 66 135 83 118Z',
  'M250 250 C286 244 317 276 315 322 C314 364 286 412 263 462 C240 431 230 393 237 356 C244 324 229 294 250 250Z',
  'M419 144 C474 116 566 116 640 138 C719 160 784 136 846 171 C810 196 737 190 702 217 C665 246 607 222 566 248 C525 273 479 238 424 248 C387 253 350 228 355 194 C359 169 386 158 419 144Z',
  'M479 207 C528 191 563 221 563 266 C563 323 526 374 486 354 C449 337 430 286 445 246 C451 229 461 216 479 207Z',
  'M676 280 C713 263 759 271 789 295 C779 324 737 333 703 322 C678 314 657 297 676 280Z',
  'M300 73 C333 52 382 59 400 88 C384 111 328 110 300 92Z'
];

function formatHemisphere(value, positive, negative) {
  return Math.abs(value).toFixed(2) + '° ' + (value >= 0 ? positive : negative);
}

function getPresentationMapContext(lat, lng) {
  return PRES_MAP_CONTEXTS.find(ctx =>
    lat >= ctx.bounds.minLat && lat <= ctx.bounds.maxLat &&
    lng >= ctx.bounds.minLng && lng <= ctx.bounds.maxLng
  ) || { id:'global', label:'Contexto global', bounds:{ minLat:-55, maxLat:70, minLng:-170, maxLng:150 } };
}

function presBoundsToRect(bounds) {
  const [x1, y1] = mapProject(bounds.maxLat, bounds.minLng);
  const [x2, y2] = mapProject(bounds.minLat, bounds.maxLng);
  return {
    x: Math.min(x1, x2),
    y: Math.min(y1, y2),
    w: Math.abs(x2 - x1),
    h: Math.abs(y2 - y1)
  };
}

function presApproxDistanceKm(a, b) {
  const toRad = deg => deg * Math.PI / 180;
  const dLat = toRad(b[0] - a[0]);
  const dLng = toRad(b[1] - a[1]);
  const lat1 = toRad(a[0]);
  const lat2 = toRad(b[0]);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLng / 2) ** 2;
  return 6371 * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h));
}

function getPresentationNearbySites(sp, coords, context) {
  const maxKm = context.id === 'global' ? 4200 : 1800;
  return Object.entries(SITES)
    .filter(([id]) => id !== sp.id && DB_INDEX[id])
    .map(([id, siteCoords]) => ({ id, sp: DB_INDEX[id], coords: siteCoords, km: presApproxDistanceKm(coords, siteCoords) }))
    .filter(item => item.km <= maxKm)
    .sort((a, b) => a.km - b.km)
    .slice(0, 5);
}

function presClamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function expandPresentationBounds(bounds, lat, lng) {
  const latSpan = Math.max(bounds.maxLat - bounds.minLat, 11);
  const lngSpan = Math.max(bounds.maxLng - bounds.minLng, 16);
  const padLat = Math.max(3, latSpan * 0.22);
  const padLng = Math.max(5, lngSpan * 0.22);
  return {
    minLat: presClamp(Math.min(bounds.minLat, lat - latSpan * 0.18) - padLat, -82, 82),
    maxLat: presClamp(Math.max(bounds.maxLat, lat + latSpan * 0.18) + padLat, -82, 82),
    minLng: presClamp(Math.min(bounds.minLng, lng - lngSpan * 0.18) - padLng, -178, 178),
    maxLng: presClamp(Math.max(bounds.maxLng, lng + lngSpan * 0.18) + padLng, -178, 178)
  };
}

function presTransformForBounds(bounds, box) {
  const rect = presBoundsToRect(bounds);
  const scale = Math.min(box.w / rect.w, box.h / rect.h);
  const dx = box.x + (box.w - rect.w * scale) / 2 - rect.x * scale;
  const dy = box.y + (box.h - rect.h * scale) / 2 - rect.y * scale;
  return { rect, scale, dx, dy };
}

function presProjectWithTransform(lat, lng, tr) {
  const [px, py] = mapProject(lat, lng);
  return [tr.dx + px * tr.scale, tr.dy + py * tr.scale];
}

function presRenderLandGroup(transform, opacity = 1) {
  const tf = transform ? ` transform="translate(${transform.dx.toFixed(2)} ${transform.dy.toFixed(2)}) scale(${transform.scale.toFixed(5)})"` : '';
  return `<g${tf} opacity="${opacity}">` + PRES_WORLD_LAND_PATHS
    .map(path => '<path class="pres-map-land" d="' + path + '"/><path class="pres-map-relief" d="' + path + '"/>')
    .join('') + '</g>';
}

function presRenderGraticule(transform, box) {
  const meridians = [-120, -60, 0, 60, 120].map(lon => {
    const [x1, y1] = transform ? presProjectWithTransform(-80, lon, transform) : mapProject(-80, lon);
    const [x2, y2] = transform ? presProjectWithTransform(80, lon, transform) : mapProject(80, lon);
    return '<line class="pres-map-graticule" x1="' + x1.toFixed(1) + '" y1="' + y1.toFixed(1) + '" x2="' + x2.toFixed(1) + '" y2="' + y2.toFixed(1) + '"/>';
  }).join('');
  const parallels = [-45, 0, 45].map(par => {
    const [x1, y1] = transform ? presProjectWithTransform(par, -170, transform) : mapProject(par, -170);
    const [x2, y2] = transform ? presProjectWithTransform(par, 170, transform) : mapProject(par, 170);
    return '<line class="pres-map-graticule" x1="' + x1.toFixed(1) + '" y1="' + y1.toFixed(1) + '" x2="' + x2.toFixed(1) + '" y2="' + y2.toFixed(1) + '"/>';
  }).join('');
  return box ? `<g clip-path="url(#${box})">${meridians}${parallels}</g>` : meridians + parallels;
}

function presApproxScaleLabel(bounds) {
  const midLat = (bounds.minLat + bounds.maxLat) / 2;
  const km = Math.max(250, Math.round((bounds.maxLng - bounds.minLng) * 111 * Math.cos(midLat * Math.PI / 180) / 4 / 100) * 100);
  return km >= 1000 ? `${(km / 1000).toFixed(km % 1000 ? 1 : 0)} mil km` : `${km} km`;
}

// ── MAPA DE PRESENTACIÓN: dos escalas, relieve y lente regional ──────────
function renderPresMap(sp, col) {
  const mapSvg = document.getElementById('presMapSvg');
  const locLbl = document.getElementById('presLocLabel');
  if (!mapSvg) return;

  const coords = SITES[sp.id];
  if (!coords) {
    mapSvg.innerHTML = '<rect width="1000" height="500" fill="#102436"/><text x="500" y="250" text-anchor="middle" class="pres-map-callout">Sin coordenadas cargadas</text>';
    if (locLbl) locLbl.textContent = sp.ubicacion;
    return;
  }

  const [lat, lng] = coords;
  const [gx, gy] = mapProject(lat, lng);
  const context = getPresentationMapContext(lat, lng);
  const expanded = expandPresentationBounds(context.bounds, lat, lng);
  const focusRect = presBoundsToRect(context.bounds);
  const globalBox = { x: 30, y: 96, w: 300, h: 220 };
  const lensBox = { x: 360, y: 96, w: 610, h: 220 };
  const gScaleX = globalBox.w / 1000;
  const gScaleY = globalBox.h / 500;
  const lensTr = presTransformForBounds(expanded, lensBox);
  const [lx, ly] = presProjectWithTransform(lat, lng, lensTr);
  const isGenericHolotype = !sp.holo || /^(N\/A|ADN|no indicado)$/i.test(String(sp.holo).trim());
  const targetName = (isGenericHolotype ? (sp.ubicacion || sp.nombre || 'Yacimiento') : sp.holo).slice(0, 30);
  const targetSub = (sp.ubicacion || sp.nombre || '').slice(0, 42);
  const topoUrl = (MAP_LAYERS?.physical?.url || MAP_LAYERS?.terrain?.url || '').replace(/"/g, '%22');
  const reliefUrl = (MAP_LAYERS?.terrain?.url || topoUrl).replace(/"/g, '%22');

  const globalRaster = topoUrl
    ? `<image class="pres-map-raster" href="${escapeHtmlAttr(topoUrl)}" x="${globalBox.x}" y="${globalBox.y}" width="${globalBox.w}" height="${globalBox.h}" preserveAspectRatio="none"/>`
    : '';
  const lensRaster = reliefUrl
    ? `<image class="pres-map-raster lens" href="${escapeHtmlAttr(reliefUrl)}" x="${lensTr.dx.toFixed(1)}" y="${lensTr.dy.toFixed(1)}" width="${(1000 * lensTr.scale).toFixed(1)}" height="${(500 * lensTr.scale).toFixed(1)}" preserveAspectRatio="none" clip-path="url(#presLensClip)"/>`
    : '';

  const globalLand = `<g opacity="${topoUrl ? '0.30' : '0.62'}" transform="translate(${globalBox.x} ${globalBox.y}) scale(${gScaleX} ${gScaleY})">${PRES_WORLD_LAND_PATHS.map(path => '<path class="pres-map-land" d="' + path + '"/>').join('')}</g>`;
  const lensLand = presRenderLandGroup(lensTr, reliefUrl ? 0.18 : 0.34);
  const globalX = globalBox.x + gx * gScaleX;
  const globalY = globalBox.y + gy * gScaleY;
  const globalFocus = {
    x: globalBox.x + focusRect.x * gScaleX,
    y: globalBox.y + focusRect.y * gScaleY,
    w: focusRect.w * gScaleX,
    h: focusRect.h * gScaleY
  };

  const peers = getPresentationNearbySites(sp, coords, context);
  const peerNodes = peers.map((item, index) => {
    const [px, py] = presProjectWithTransform(item.coords[0], item.coords[1], lensTr);
    return '<g>' +
      '<circle class="pres-map-peer" cx="' + px.toFixed(1) + '" cy="' + py.toFixed(1) + '" r="' + (index < 3 ? '5.2' : '4') + '"/>' +
      '<title>' + escapeHtmlText(item.sp.nombre + ' · ' + Math.round(item.km) + ' km') + '</title></g>';
  }).join('');

  const labelX = lx > lensBox.x + lensBox.w - 210 ? lx - 18 : lx + 18;
  const labelAnchor = lx > lensBox.x + lensBox.w - 210 ? 'end' : 'start';
  const labelY = presClamp(ly - 24, lensBox.y + 28, lensBox.y + lensBox.h - 18);
  const scaleLabel = presApproxScaleLabel(expanded);

  mapSvg.innerHTML =
    '<defs>' +
      '<linearGradient id="presLandGrad" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#e4c88e"/><stop offset="0.42" stop-color="#a47b43"/><stop offset="1" stop-color="#52735c"/></linearGradient>' +
      '<pattern id="presReliefLines" width="28" height="16" patternUnits="userSpaceOnUse" patternTransform="rotate(-18)"><path d="M0 8 C7 2 14 14 28 8" fill="none" stroke="rgba(255,255,255,0.45)" stroke-width="1.2"/></pattern>' +
      '<filter id="presLandShadow" x="-8%" y="-8%" width="116%" height="116%"><feDropShadow dx="0" dy="3" stdDeviation="4" flood-color="#000" flood-opacity="0.30"/></filter>' +
      '<radialGradient id="presOceanGlow" cx="50%" cy="45%" r="70%"><stop offset="0" stop-color="#2d6a87"/><stop offset="0.62" stop-color="#17364d"/><stop offset="1" stop-color="#07121c"/></radialGradient>' +
      '<clipPath id="presGlobalClip"><rect x="' + globalBox.x + '" y="' + globalBox.y + '" width="' + globalBox.w + '" height="' + globalBox.h + '" rx="18"/></clipPath>' +
      '<clipPath id="presLensClip"><rect x="' + lensBox.x + '" y="' + lensBox.y + '" width="' + lensBox.w + '" height="' + lensBox.h + '" rx="18"/></clipPath>' +
    '</defs>' +
    '<rect width="1000" height="500" fill="url(#presOceanGlow)"/>' +
    '<text class="pres-map-question" x="30" y="36">Pregunta guía: ¿qué aporta la localización al valor del hallazgo?</text>' +
    '<text class="pres-map-instruction" x="30" y="60">Lee de izquierda a derecha: primero sitúa el corredor, después comprueba yacimiento, relieve y cautelas.</text>' +
    '<rect class="pres-map-panel-bg" x="' + globalBox.x + '" y="' + globalBox.y + '" width="' + globalBox.w + '" height="' + globalBox.h + '" rx="18"/>' +
    '<rect class="pres-map-panel-bg" x="' + lensBox.x + '" y="' + lensBox.y + '" width="' + lensBox.w + '" height="' + lensBox.h + '" rx="18"/>' +
    '<text class="pres-map-panel-title" x="' + globalBox.x + '" y="' + (globalBox.y - 12) + '">1 · escala global: continente y corredor</text>' +
    '<text class="pres-map-panel-title" x="' + lensBox.x + '" y="' + (lensBox.y - 12) + '">2 · escala regional: yacimiento, relieve y vecinos</text>' +
    '<g clip-path="url(#presGlobalClip)">' + globalLand + globalRaster +
      '<rect class="pres-map-focus-frame" x="' + globalFocus.x.toFixed(1) + '" y="' + globalFocus.y.toFixed(1) + '" width="' + globalFocus.w.toFixed(1) + '" height="' + globalFocus.h.toFixed(1) + '" rx="8"/>' +
      '<circle cx="' + globalX.toFixed(1) + '" cy="' + globalY.toFixed(1) + '" r="13" fill="' + escapeHtmlAttr(col) + '" opacity="0.25"/>' +
      '<circle class="pres-map-marker-core" cx="' + globalX.toFixed(1) + '" cy="' + globalY.toFixed(1) + '" r="5.8" fill="' + escapeHtmlAttr(col) + '"/>' +
    '</g>' +
    '<g clip-path="url(#presLensClip)">' + lensLand + lensRaster + presRenderGraticule(lensTr, 'presLensClip') + peerNodes +
      '<circle cx="' + lx.toFixed(1) + '" cy="' + ly.toFixed(1) + '" r="24" fill="' + escapeHtmlAttr(col) + '" opacity="0.22"/>' +
      '<circle class="pres-map-marker-ring" cx="' + lx.toFixed(1) + '" cy="' + ly.toFixed(1) + '" r="13"/>' +
      '<circle class="pres-map-marker-core" cx="' + lx.toFixed(1) + '" cy="' + ly.toFixed(1) + '" r="7.2" fill="' + escapeHtmlAttr(col) + '"/>' +
    '</g>' +
    '<line x1="' + lx.toFixed(1) + '" y1="' + ly.toFixed(1) + '" x2="' + (labelAnchor === 'end' ? labelX - 8 : labelX + 8).toFixed(1) + '" y2="' + labelY.toFixed(1) + '" stroke="white" stroke-width="1.4" opacity="0.78"/>' +
    '<text class="pres-map-subtitle" x="360" y="336">' + escapeHtmlText(context.label) + '</text>' +
    '<text class="pres-map-callout" text-anchor="' + labelAnchor + '" x="' + labelX.toFixed(1) + '" y="' + labelY.toFixed(1) + '">' + escapeHtmlText(targetName) + '</text>' +
    '<text class="pres-map-callout-sub" text-anchor="' + labelAnchor + '" x="' + labelX.toFixed(1) + '" y="' + (labelY + 15).toFixed(1) + '">' + escapeHtmlText(targetSub) + '</text>' +
    '<line class="pres-map-scale-line" x1="802" y1="334" x2="915" y2="334"/>' +
    '<text class="pres-map-scale" x="923" y="339">' + escapeHtmlText(scaleLabel) + '</text>' +
    '<rect class="pres-map-lesson-card" x="30" y="356" width="220" height="86" rx="10"/>' +
    '<text class="pres-map-lesson-title" x="44" y="379">Qué mirar</text>' +
    '<text class="pres-map-lesson-text" x="44" y="402">Región, cuenca y relieve:</text>' +
    '<text class="pres-map-lesson-text" x="44" y="418">explican preservación y acceso.</text>' +
    '<rect class="pres-map-lesson-card" x="270" y="356" width="220" height="86" rx="10"/>' +
    '<text class="pres-map-lesson-title" x="284" y="379">Dato principal</text>' +
    '<text class="pres-map-lesson-text" x="284" y="402">El punto grande es el sitio</text>' +
    '<text class="pres-map-lesson-text" x="284" y="418">o holotipo que sostiene la ficha.</text>' +
    '<rect class="pres-map-lesson-card" x="510" y="356" width="220" height="86" rx="10"/>' +
    '<text class="pres-map-lesson-title" x="524" y="379">Comparación</text>' +
    '<text class="pres-map-lesson-text" x="524" y="402">Los puntos blancos son sitios</text>' +
    '<text class="pres-map-lesson-text" x="524" y="418">proximos para contrastar.</text>' +
    '<rect class="pres-map-lesson-card" x="750" y="356" width="220" height="86" rx="10"/>' +
    '<text class="pres-map-lesson-title" x="764" y="379">Cautela</text>' +
    '<text class="pres-map-lesson-text" x="764" y="402">Cercanía geográfica no prueba</text>' +
    '<text class="pres-map-lesson-text" x="764" y="418">ancestro, contacto ni continuidad.</text>';

  if (locLbl) {
    const nearbyText = peers.length
      ? ' · Próximos: ' + peers.slice(0, 3).map(item => item.sp.nombre).join(', ')
      : '';
    locLbl.innerHTML = '<strong>' + escapeHtmlText(context.label) + '</strong> · ' +
      escapeHtmlText(formatHemisphere(lat, 'N', 'S') + ', ' + formatHemisphere(lng, 'E', 'O')) +
      ' · ' + escapeHtmlText(sp.ubicacion || '') + escapeHtmlText(nearbyText);
  }
}

// ── MINI GRÁFICO CC ────────────────────────────────────────────
function renderPresCCChart(sp, col) {
  const canvas = document.getElementById('presCCChart');
  const lbl    = document.getElementById('presCCLabel');
  if (!canvas) return;

  const allWithCC = DB.filter(s => s.cc != null).sort((a,b) => a.val_time - b.val_time);
  const MAX_CC  = 1700;
  const MAX_MA  = 23.5;

  const rect  = canvas.getBoundingClientRect();
  const DPR   = window.devicePixelRatio || 1;
  const W     = Math.max(rect.width || 280, 100);
  const H     = 110;
  canvas.width  = W * DPR;
  canvas.height = H * DPR;
  canvas.style.width  = W + 'px';
  canvas.style.height = H + 'px';
  const ctx = canvas.getContext('2d');
  ctx.scale(DPR, DPR);

  // Background
  ctx.fillStyle = 'rgba(255,255,255,0.03)';
  ctx.fillRect(0, 0, W, H);

  const PAD = {t:8, r:8, b:22, l:8};
  const pw = W - PAD.l - PAD.r;
  const ph = H - PAD.t - PAD.b;

  const xS = ma  => PAD.l + ((MAX_MA - ma) / MAX_MA) * pw;
  const yS = cc  => PAD.t + ph - (cc / MAX_CC) * ph;

  // Soft gridlines
  ctx.strokeStyle = 'rgba(255,255,255,0.07)';
  ctx.lineWidth = 1;
  [400, 800, 1200, 1600].forEach(v => {
    ctx.beginPath(); ctx.moveTo(PAD.l, yS(v)); ctx.lineTo(W - PAD.r, yS(v)); ctx.stroke();
  });

  // All points — dimmed
  allWithCC.forEach(s => {
    const isCurrent = s.id === sp.id;
    if (isCurrent) return;
    const x = xS(s.val_time), y = yS(s.cc);
    ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI * 2);
    ctx.fillStyle = (CLADE_COLORS[s.clado] || '#888');
    ctx.globalAlpha = 0.28; ctx.fill(); ctx.globalAlpha = 1;
  });

  // Current species — highlighted
  if (sp.cc) {
    const x = xS(sp.val_time), y = yS(sp.cc);
    ctx.beginPath(); ctx.arc(x, y, 7, 0, Math.PI * 2);
    ctx.fillStyle = col; ctx.globalAlpha = 0.3; ctx.fill(); ctx.globalAlpha = 1;
    ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI * 2);
    ctx.fillStyle = col; ctx.strokeStyle = 'white'; ctx.lineWidth = 1.5; ctx.fill(); ctx.stroke();

    // Vertical reference line
    ctx.setLineDash([3, 2]);
    ctx.strokeStyle = col; ctx.lineWidth = 1; ctx.globalAlpha = 0.4;
    ctx.beginPath(); ctx.moveTo(x, PAD.t); ctx.lineTo(x, H - PAD.b); ctx.stroke();
    ctx.globalAlpha = 1; ctx.setLineDash([]);
  }

  // X axis labels
  ctx.fillStyle = 'rgba(255,255,255,0.25)';
  ctx.font = '9px JetBrains Mono, monospace';
  ctx.textAlign = 'center';
  [23, 15, 7, 3, 0].forEach(ma => {
    const x = xS(ma);
    ctx.fillText(ma === 0 ? 'Hoy' : ma + ' Ma', x, H - 6);
  });

  // CC label
  if (lbl) {
    lbl.textContent = sp.cc
      ? sp.cc + ' cc  ·  posición ' + (allWithCC.findIndex(s => s.id === sp.id) + 1) + '/' + allWithCC.length + ' por cronología'
      : 'CC no disponible para esta especie';
  }
}

// ── MAPA REAL LEAFLET — panel de detalle de especie ──────────
let _activeLeafletMap = null; // destroy previous instance on re-open

function initDetailLeaflet(divId, lat, lng, dotColor, nombre) {
    const el = document.getElementById(divId);
    if (!el || typeof L === 'undefined') return;
    const safeNombre = escapeHtmlText(nombre);

    // FIX v22-B: Doble init — limpiar instancia previa Y estado del contenedor
    if (_activeLeafletMap) {
        try { _activeLeafletMap.remove(); } catch(e) { if(typeof Logger!=="undefined") Logger.debug("leaflet.remove", e); }
        _activeLeafletMap = null;
    }
    // Limpiar _leaflet_id del div por si el panel fue reutilizado sin remove()
    const _containerEl = document.getElementById(divId);
    if (_containerEl) {
        if (_containerEl._leaflet_id) {
            try { L.map._maps && delete L.map._maps[_containerEl._leaflet_id]; } catch(e) { /* recuperable: suprimido intencionalmente */ }
            delete _containerEl._leaflet_id;
        }
        _containerEl.innerHTML = '';
    }

    // Choose zoom: 6 for well-known sites, cap at 8
    const zoom = 6;

    const map = L.map(divId, {
        center: [lat, lng],
        zoom,
        zoomControl: true,
        attributionControl: true,
        scrollWheelZoom: true,
    });
    _activeLeafletMap = map;

    // Tile layers
    const osm = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© <a href="https://openstreetmap.org/copyright" rel="noopener noreferrer">OpenStreetMap</a>',
        maxZoom: 19
    });
    const topo = L.tileLayer('https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png', {
        attribution: '© <a href="https://opentopomap.org" rel="noopener noreferrer">OpenTopoMap</a>',
        maxZoom: 17
    });
    // Satellite via ESRI (free, no key)
    const sat = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
        attribution: 'Tiles © Esri — Source: Esri, USGS, NOAA',
        maxZoom: 19
    });

    osm.addTo(map);
    L.control.layers({ 'Mapa': osm, 'Topográfico': topo, 'Satélite': sat }, {}, { position: 'topright', collapsed: false }).addTo(map);

    // Custom colored marker
    const icon = L.divIcon({
        className: '',
        html: `<div style="
            width:18px;height:18px;border-radius:50%;
            background:${dotColor};border:3px solid white;
            box-shadow:0 2px 8px rgba(0,0,0,0.45);
            position:relative;">
            <div style="
                position:absolute;top:-32px;left:50%;transform:translateX(-50%);
                background:rgba(20,35,50,0.88);color:white;
                padding:3px 8px;border-radius:999px;white-space:nowrap;
                font-size:11px;font-weight:700;font-family:sans-serif;
                backdrop-filter:blur(4px);">${safeNombre}</div>
        </div>`,
        iconSize: [18, 18],
        iconAnchor: [9, 9],
        popupAnchor: [0, -16]
    });

    L.marker([lat, lng], { icon })
        .addTo(map)
        .bindPopup(`<b style="font-style:italic">${safeNombre}</b><br>
            <span style="font-size:0.78rem;color:#555">${lat.toFixed(2)}°, ${lng.toFixed(2)}°</span>`);

    // Fix Leaflet tile loading after panel animation
    setTimeout(() => map.invalidateSize(), 320);
}


