const CLADOGRAM_LEAF_ORDER = [
  'proconsul','morotopithecus','dryopithecus','pierolapithecus','anoiapithecus','nakalipithecus','chororapithecus','graecopithecus','sahel','orrorin','kadabba',
  'ramidus','anamensis','afarensis','deyiremeda','bahrelghazali','kenyanthropus','africanus','prometheus','garhi','sediba',
  'aethiopicus','boisei','robustus',
  'habilis','rudolfensis','ergaster','georgicus','erectus','antecessor','cepranensis','daliensis','flores','luzon',
  'heidelbergensis','bodoensis','rhodesiensis','helmei','naledi','longi','neander','denisova','jebel_irhoud','omo_i','idaltu','sapiens'
];

const CLADOGRAM_NODE_ORDER = Object.keys(CLADOGRAM_INFO);

function cladogramNodeCode(nodeId) {
  const index = CLADOGRAM_NODE_ORDER.indexOf(nodeId);
  return index >= 0 ? 'N' + (index + 1) : 'N?';
}

function shortTaxonName(name) {
  return (name || '')
    .replace(/^Australopithecus /, 'Au. ')
    .replace(/^Ardipithecus /, 'Ar. ')
    .replace(/^Paranthropus /, 'P. ')
    .replace(/^Sahelanthropus /, 'S. ')
    .replace(/^Morotopithecus /, 'M. ')
    .replace(/^Dryopithecus /, 'D. ')
    .replace(/^Pierolapithecus /, 'Pi. ')
    .replace(/^Anoiapithecus /, 'An. ')
    .replace(/^Nakalipithecus /, 'N. ')
    .replace(/^Chororapithecus /, 'C. ')
    .replace(/^Graecopithecus /, 'G. ')
    .replace(/^Homo /, 'H. ');
}

function renderPhyloTree() {
  const container = document.getElementById('phyloSvgContainer');
  if (!container) return;

  const W = 1360, TOP = 84, LEFT = 84, RIGHT = 1260;
  const rowGap = 42, leafTop = 132;
  const leafY = Object.fromEntries(CLADOGRAM_LEAF_ORDER.map((id, i) => [id, leafTop + i * rowGap]));
  const H = leafTop + (CLADOGRAM_LEAF_ORDER.length - 1) * rowGap + 70;
  const visibleCache = {};

  const xAt = (ma) => LEFT + ((23 - Math.max(0, Math.min(23, ma))) / 23) * (RIGHT - LEFT);
  const rangeFor = (id) => {
    const sp = DB_INDEX[id];
    if (!sp) return { start: 0, end: 0 };
    const tr = getSpeciesTimeRange(sp);
    return { start: Number(tr.start || 0), end: Number(tr.end || 0) };
  };
  const leafVisible = (id) => {
    if (visibleCache[id] !== undefined) return visibleCache[id];
    const sp = DB_INDEX[id];
    visibleCache[id] = !!(sp && matchesActiveFilters(sp));
    return visibleCache[id];
  };

  function layout(item) {
    if (item.leaf) {
      const sp = DB_INDEX[item.leaf];
      const tr = rangeFor(item.leaf);
      return {
        type: 'leaf',
        id: item.leaf,
        y: leafY[item.leaf] || leafTop,
        xStart: xAt(tr.start),
        xEnd: xAt(tr.end),
        visible: leafVisible(item.leaf),
        color: sp ? (CLADE_COLORS[sp.clado] || '#777') : '#777'
      };
    }
    const info = CLADOGRAM_INFO[item.node];
    const children = item.children.map(layout);
    const y = children.reduce((sum, c) => sum + c.y, 0) / children.length;
    return {
      type: 'node',
      id: item.node,
      y,
      x: xAt(info.time),
      info,
      children,
      visible: children.some(c => c.visible)
    };
  }

  const root = layout(CLADOGRAM_TREE);
  const parts = [];

  parts.push(`<svg class="phylo-cladogram-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Cladograma ramificado de homíninos">`);
  parts.push(`<defs><linearGradient id="cladoRangeGrad" x1="0" x2="1"><stop offset="0" stop-color="rgba(255,255,255,0.35)"/><stop offset="1" stop-color="rgba(255,255,255,0)"/></linearGradient></defs>`);

  const axisTicks = [23,20,15,10,7,5,3,2,1,0.3,0];
  axisTicks.forEach((t, index) => {
    const x = xAt(t);
    const previousX = index ? xAt(axisTicks[index - 1]) : -999;
    const compact = Math.abs(x - previousX) < 54 || t <= 1;
    const labelY = compact && index % 2 ? TOP - 30 : TOP - 50;
    parts.push(`<line x1="${x.toFixed(1)}" y1="${TOP-22}" x2="${x.toFixed(1)}" y2="${H-28}" stroke="rgba(90,80,70,0.10)" stroke-width="1"/>`);
    parts.push(`<text class="clado-axis-label" x="${x.toFixed(1)}" y="${labelY}" text-anchor="middle">${formatTimePoint(t)}</text>`);
  });
  parts.push(`<text class="clado-axis-label" x="${LEFT}" y="${H-12}">más antiguo</text>`);
  parts.push(`<text class="clado-axis-label" x="${RIGHT}" y="${H-12}" text-anchor="end">presente</text>`);

  function drawBranches(node) {
    if (node.type !== 'node') return;
    node.children.forEach(child => {
      const childX = child.type === 'node' ? child.x : Math.max(child.xStart, node.x + 18);
      const muted = child.visible ? '' : ' opacity="0.22"';
      const branchClass = child.type === 'leaf' && child.id === 'graecopithecus' ? 'clado-branch-soft' : 'clado-branch';
      parts.push(`<path class="${branchClass}" d="M${node.x.toFixed(1)},${node.y.toFixed(1)} H${childX.toFixed(1)} V${child.y.toFixed(1)}"${muted}/>`);
      if (child.type === 'node') drawBranches(child);
    });
  }

  function drawLeaves(item) {
    if (item.type === 'leaf') {
      const sp = DB_INDEX[item.id];
      if (!sp) return;
      const x1 = Math.min(item.xStart, item.xEnd);
      const x2 = Math.max(item.xStart, item.xEnd);
      const w = Math.max(10, x2 - x1);
      const y = item.y;
      const muted = item.visible ? '' : ' is-muted';
      const debated = sp.estado && sp.estado !== 'aceptada';
      parts.push(`<g class="clado-leaf${muted}" data-id="${item.id}" role="button" tabindex="0" aria-label="${escapeHtmlAttr(sp.nombre)}">`);
      parts.push(`<line x1="${x1.toFixed(1)}" y1="${y.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y.toFixed(1)}" stroke="${item.color}" stroke-width="6" stroke-linecap="round" opacity="${debated ? 0.52 : 0.82}"/>`);
      if (debated) parts.push(`<line x1="${x1.toFixed(1)}" y1="${(y-5).toFixed(1)}" x2="${x2.toFixed(1)}" y2="${(y+5).toFixed(1)}" stroke="rgba(255,255,255,0.55)" stroke-width="2" stroke-dasharray="3 3"/>`);
      const labelX = Math.min(RIGHT - 118, Math.max(x2 + 10, x1 + w + 10));
      parts.push(`<rect x="${(labelX-4).toFixed(1)}" y="${(y-13).toFixed(1)}" width="132" height="25" rx="8" fill="${item.color}" fill-opacity="${item.visible ? 0.14 : 0.08}"/>`);
      parts.push(`<text x="${labelX.toFixed(1)}" y="${(y+4).toFixed(1)}">${escapeHtmlAttr(shortTaxonName(sp.nombre))}</text>`);
      parts.push(`</g>`);
      return;
    }
    item.children.forEach(drawLeaves);
  }

  function drawNodes(item) {
    if (item.type === 'node') {
      const info = item.info;
      const opacity = item.visible ? 1 : 0.28;
      const color = item.id.includes('homo') || item.id.includes('archaic') || item.id.includes('dispersal') || item.id.includes('middle') || item.id.includes('sapiens') || item.id.includes('neander') ? CLADE_COLORS.homo :
        item.id.includes('paranthropus') || item.id.includes('paranthro') ? CLADE_COLORS.paran :
        item.id.includes('australopith') ? CLADE_COLORS.australo : CLADE_COLORS.basal;
      const code = cladogramNodeCode(item.id);
      parts.push(`<g class="clado-node" data-node="${item.id}" opacity="${opacity}" role="button" tabindex="0" aria-label="${code}: ${escapeHtmlAttr(info.label)}, ${formatTimePoint(info.time)}">`);
      parts.push(`<title>${code}: ${escapeHtmlAttr(info.label)}. ${formatTimePoint(info.time)}</title>`);
      parts.push(`<circle cx="${item.x.toFixed(1)}" cy="${item.y.toFixed(1)}" r="10" fill="${color}"/>`);
      parts.push(`<text class="clado-node-code" x="${item.x.toFixed(1)}" y="${(item.y+3.2).toFixed(1)}" text-anchor="middle">${code.replace('N','')}</text>`);
      parts.push(`</g>`);
      item.children.forEach(drawNodes);
    }
  }

  drawBranches(root);
  drawLeaves(root);
  drawNodes(root);
  parts.push(`</svg>`);
  container.innerHTML = parts.join('');

  container.querySelectorAll('.clado-node').forEach(el => {
    const selectNode = () => {
      container.querySelectorAll('.clado-node.is-selected').forEach(node => node.classList.remove('is-selected'));
      el.classList.add('is-selected');
      showCladeNodeInfo(el.dataset.node);
    };
    el.addEventListener('click', selectNode);
    el.addEventListener('keydown', e => {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      e.preventDefault();
      selectNode();
    });
  });
  container.querySelectorAll('.clado-leaf').forEach(el => {
    const openLeaf = () => {
      const sp = DB_INDEX[el.dataset.id];
      if (sp) showDetail(sp);
    };
    el.addEventListener('click', openLeaf);
    el.addEventListener('keydown', e => {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      e.preventDefault();
      openLeaf();
    });
  });

  const initial = Object.keys(CLADOGRAM_INFO).find(id => id === 'hominini');
  container.querySelector(`.clado-node[data-node="${initial}"]`)?.classList.add('is-selected');
  showCladeNodeInfo(initial, false);
}

function showCladeNodeInfo(nodeId, pulse = true) {
  const info = CLADOGRAM_INFO[nodeId];
  const panel = document.getElementById('cladeNodeInfo');
  if (!info || !panel) return;
  const code = cladogramNodeCode(nodeId);
  panel.innerHTML = `
    <div>
      <code>${code} / ${formatTimePoint(info.time)}</code>
      <h3>${escapeHtmlAttr(info.label)}</h3>
    </div>
    <p><strong>Carácter derivado:</strong> ${escapeHtmlAttr(info.syn)}<br><span style="color:var(--text-hint)">${escapeHtmlAttr(info.note)}</span></p>`;
  if (pulse) {
    panel.animate([{ transform:'scale(0.992)', opacity:0.72 }, { transform:'scale(1)', opacity:1 }], { duration:180, easing:'ease-out' });
  }
}

let showPaleoEnvironment = false;

function getPaleoEnvironmentStage() {
  const mid = (timeFilter.old + timeFilter.young) / 2;
  if (timeFilter.old - timeFilter.young > 15) {
    return {
      key: 'overview',
      title: 'Síntesis 23 Ma-presente',
      note: 'Capa compuesta: bosques miocenos, expansión C4, sabanización africana y glaciaciones pleistocenas.',
      ice: 0.22, savanna: 0.52, sahara: 0.34, coast: 0.18, forest: 0.48
    };
  }
  if (mid > 5.3) return {
    key: 'miocene',
    title: 'Mioceno',
    note: 'Mosaicos boscosos y expansión inicial de ambientes abiertos; tectónica del Rift en intensificación.',
    ice: 0.04, savanna: 0.22, sahara: 0.12, coast: 0.02, forest: 0.66
  };
  if (mid > 2.58) return {
    key: 'pliocene',
    title: 'Plioceno',
    note: 'Aumento de estacionalidad, C4 y sabanas africanas; mosaicos ecológicos para australopitecos.',
    ice: 0.10, savanna: 0.58, sahara: 0.28, coast: 0.08, forest: 0.34
  };
  if (mid > 0.126) return {
    key: 'pleistocene',
    title: 'Pleistoceno',
    note: 'Ciclos glaciales, costas desplazadas y pulsos de aridez/humedad en Sahara y Arabia.',
    ice: 0.70, savanna: 0.52, sahara: 0.62, coast: 0.58, forest: 0.20
  };
  return {
    key: 'late',
    title: 'Pleistoceno final-Holoceno',
    note: 'Glaciares en retroceso, Sahara muy variable y costas cercanas al trazado moderno.',
    ice: 0.38, savanna: 0.42, sahara: 0.52, coast: 0.28, forest: 0.28
  };
}

function envEllipse(lat, lng, rx, ry, color, opacity, label) {
  const [x, y] = mapProject(lat, lng);
  return `<ellipse class="map-env-band" cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" rx="${rx}" ry="${ry}" fill="${color}" opacity="${opacity}"/>
    <text class="map-env-label" x="${x.toFixed(1)}" y="${(y+4).toFixed(1)}" text-anchor="middle">${label}</text>`;
}

function envPolygon(points, color, opacity, label, labelLat, labelLng) {
  const d = points.map(([lat,lng]) => mapProject(lat,lng).map(v => v.toFixed(1)).join(',')).join(' ');
  const [lx, ly] = mapProject(labelLat, labelLng);
  return `<polygon class="map-env-band" points="${d}" fill="${color}" opacity="${opacity}"/>
    <text class="map-env-label" x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="middle">${label}</text>`;
}

function renderPaleoEnvironmentOverlay() {
  const svg = document.getElementById('mapSvg');
  if (!svg) return;
  svg.querySelectorAll('.map-env-layer').forEach(el => el.remove());
  const legend = document.getElementById('mapLegend');
  if (legend) legend.querySelectorAll('#mapEnvLegend').forEach(el => el.remove());
  const btn = document.getElementById('paleoEnvToggle');
  if (btn) btn.classList.toggle('active', showPaleoEnvironment);
  if (!showPaleoEnvironment) return;

  const stage = getPaleoEnvironmentStage();
  const parts = [`<g class="map-env-layer" data-stage="${stage.key}">`];
  parts.push(envEllipse(0, 24, 120, 66, '#b7c66a', stage.savanna, 'sabanas / C4'));
  parts.push(envEllipse(4, -62, 56, 42, '#2f8a62', stage.forest * 0.75, 'bosque tropical'));
  parts.push(envEllipse(-3, 113, 72, 38, '#2f8a62', stage.forest * 0.72, 'Sunda húmeda'));
  parts.push(envPolygon([[33,-18],[32,45],[15,52],[12,-15]], '#d8a84d', stage.sahara, 'Sahara árido', 23, 16));
  parts.push(envPolygon([[13,32],[15,46],[24,58],[29,44],[19,34]], '#d8a84d', Math.max(stage.sahara - 0.12, 0.08), 'Arabia', 22, 45));
  parts.push(envPolygon([[9,29],[7,36],[-4,39],[-12,36],[-6,29]], '#8a5a2b', 0.45, 'Rift', 1, 35));
  if (stage.ice > 0.08) {
    parts.push(envPolygon([[72,-170],[72,-20],[54,-15],[50,-80],[56,-150]], '#cfe7ef', stage.ice, 'hielo N. América', 61, -96));
    parts.push(envPolygon([[72,-15],[72,170],[56,160],[52,58],[58,10]], '#cfe7ef', stage.ice, 'hielo Eurasia', 62, 72));
  }
  if (stage.coast > 0.05) {
    parts.push(envEllipse(-7, 125, 80, 28, '#7bb7c9', stage.coast, 'plataforma Sunda'));
    parts.push(envEllipse(53, -3, 52, 16, '#7bb7c9', stage.coast * 0.85, 'Doggerland'));
  }
  parts.push(`</g>`);

  const doc = new DOMParser().parseFromString(`<svg xmlns="http://www.w3.org/2000/svg">${parts.join('')}</svg>`, 'image/svg+xml');
  const layer = document.adoptNode(doc.documentElement.firstChild.cloneNode(true));
  const firstDataLayer = svg.querySelector('.mig-path,.map-node');
  svg.insertBefore(layer, firstDataLayer || null);

  if (legend) {
    legend.insertAdjacentHTML('beforeend', `<div class="map-env-legend" id="mapEnvLegend"><strong>🌾 ${stage.title}</strong><br>${stage.note}</div>`);
  }
}

function togglePaleoEnvironment(btn) {
  showPaleoEnvironment = !showPaleoEnvironment;
  if (btn) btn.classList.toggle('active', showPaleoEnvironment);
  if (btn) btn.setAttribute('aria-pressed', String(showPaleoEnvironment));
  renderPaleoEnvironmentOverlay();
}

