function getPaleoproteomicsProfile(sp) {
  if (PALEOPROTEOMICS_PROFILES[sp.id]) return PALEOPROTEOMICS_PROFILES[sp.id];
  const age = Number(sp.val_time);
  if (sp.clado === 'homo' && Number.isFinite(age) && age >= 0.3) {
    return {
      status: 'contextual',
      title: 'Paleoproteómica contextual',
      summary: 'No hay un proteoma antiguo directo cargado para este taxón, pero la paleoproteómica es relevante para fósiles donde el ADN no suele conservarse.',
      signal: 'Potencial centrado en proteínas estables, sobre todo del esmalte dental, si existe material adecuado y preservación suficiente.',
      didactic: 'Útil para preguntar al alumnado qué tipo de molécula podría sobrevivir y qué pregunta respondería.',
      limit: 'Debe presentarse como posibilidad metodológica, no como evidencia directa del taxón.',
      refs: []
    };
  }
  return {
    status: 'ausente',
    title: 'Sin campo paleoproteómico directo',
    summary: 'La ficha no registra datos paleoproteómicos publicados o cargados para este taxón.',
    signal: 'La interpretación se apoya en fósiles, datación, contexto arqueológico y, cuando exista, ADN antiguo.',
    didactic: 'Refuerza una regla científica básica: no todos los campos de evidencia están disponibles para todos los fósiles.',
    limit: 'La ausencia de proteínas recuperadas no resta valor al taxón; solo delimita qué preguntas pueden responderse.',
    refs: []
  };
}

function renderPaleoproteomicsField(sp) {
  const profile = getPaleoproteomicsProfile(sp);
  const label = {
    directa: 'Evidencia directa',
    contextual: 'Contextual',
    ausente: 'Sin dato directo'
  }[profile.status] || 'Campo';
  const refs = profile.refs?.length
    ? `<div class="pp-refs"><h4>Referencias paleoproteómicas clave</h4><ul class="references-list">${profile.refs.map(renderReferenceListItem).join('')}</ul></div>`
    : `<div class="pp-refs"><h4>Referencias paleoproteómicas clave</h4><p style="margin:0;color:var(--text-hint);font-size:0.84rem;line-height:1.55">No hay referencia paleoproteómica directa cargada para este taxón.</p></div>`;
  return `<section class="paleoproteomics-panel" aria-label="Campo de paleoproteómica">
    <div class="paleoproteomics-top">
      <div>
        <h3 class="paleoproteomics-title">${escapeHtmlText(profile.title)}</h3>
        <p class="paleoproteomics-subtitle">${escapeHtmlText(profile.summary)}</p>
      </div>
      <span class="pp-status-badge ${escapeHtmlAttr(profile.status)}">${escapeHtmlText(label)}</span>
    </div>
    <div class="paleoproteomics-grid">
      <div class="pp-card"><strong>Señal proteica</strong><p>${escapeHtmlText(profile.signal)}</p></div>
      <div class="pp-card"><strong>Uso didáctico</strong><p>${escapeHtmlText(profile.didactic)}</p></div>
      <div class="pp-card"><strong>Límite científico</strong><p>${escapeHtmlText(profile.limit)}</p></div>
    </div>
    ${refs}
  </section>`;
}

