function getFossilCompletenessProfile(sp) {
  const txt = normalizeForSearch([
    sp.holo, sp.descripcion, sp.experto?.descripcion_tecnica, sp.experto?.anatomia_craneal,
    sp.experto?.anatomia_postcraneal, sp.experto?.debate
  ].join(' '));
  const has = (re) => re.test(txt);
  const negativePost = /postcraneal no|sin postcraneal|no recuperada|no documentada/.test(txt);
  return {
    craneo: !!sp.cc || has(/craneo|craneal|skull|calvaria|rostro|frontal|occipital|supraorbitario|neurocraneo/),
    mandibula: has(/mandibula|mandibular|maxilar|mauer|taung|lh 4|oh 7|atd6|dh1|lb1/),
    dientes: has(/diente|dental|molar|premolar|canino|esmalte|megadoncia|denticion/),
    postcraneo: !negativePost && has(/postcraneal|pelvis|femur|tibia|pie|mano|falange|metatars|biped|locomocion|esqueleto|turkana/)
  };
}

