function getSpeciesRegions(sp) {
  if (!sp) return ['desconocida'];
  if (/global|mundial/i.test(sp.ubicacion || '')) return ['global'];
  const coords = SITES[sp.id];
  if (coords) {
    const [lat, lng] = coords;
    if (lat >= -38 && lat <= 38 && lng >= -25 && lng <= 60) return ['africa'];
    if (lat >= 34 && lat <= 72 && lng >= -25 && lng <= 65) return ['europa'];
    if (lat >= -12 && lat <= 75 && lng >= 40 && lng <= 170) return ['asia'];
    if (lat <= -10 && lng >= 110) return ['oceania'];
  }
  const u = normalizeForSearch(sp.ubicacion || '');
  const regions = [];
  if (/africa|kenia|etiopia|tanzania|sudafrica|chad|zambia|marruecos|uganda/.test(u)) regions.push('africa');
  if (/europa|espana|francia|alemania|italia|georgia|croacia|grecia/.test(u)) regions.push('europa');
  if (/asia|china|indonesia|filipinas|siberia|java|georgia/.test(u)) regions.push('asia');
  if (/global/.test(u)) regions.push('global');
  return regions.length ? [...new Set(regions)] : ['desconocida'];
}

function speciesOverlapsBin(sp, old, young) {
  const tr = getSpeciesTimeRange(sp);
  return tr.start >= young && tr.end <= old;
}

function speciesTemporalOverlap(a, b) {
  const ar = getSpeciesTimeRange(a);
  const br = getSpeciesTimeRange(b);
  const old = Math.min(ar.start, br.start);
  const young = Math.max(ar.end, br.end);
  return old >= young ? { old, young, duration: old - young } : null;
}

function shareRegion(a, b) {
  const ra = getSpeciesRegions(a);
  const rb = getSpeciesRegions(b);
  if (ra.includes('global') || rb.includes('global')) return 'global';
  const hit = ra.find(r => rb.includes(r));
  return hit || null;
}

// ══════════════════════════════════════════════════════════════════════════
//  CONTEXTO ECOLÓGICO EN COEXISTENCIAS — PaleoBot
//  Enriquece la vista de coexistencias con:
//    1. Banda MIS (frío/cálido) sobre el heatmap
//    2. Bioma dominante por intervalo temporal
//    3. Clasificación de nicho ecológico por especie
//    4. Indicador de interacción entre pares (competencia/partición/simpatría)
//    5. Panel de bin seleccionado con detalle de taxones y contexto
//    6. Filtros de interacción
//  Fuentes:
//    MIS_STAGES: dataset integrado (Lisiecki & Raymo 2005, doi:10.1029/2004PA001071)
//    Biomas: basado en deMenocal 2004 (doi:10.1016/j.epsl.2004.01.036)
//    Nicho: inferido de sp.dieta + sp.herramientas (dieta isótópica)
// ══════════════════════════════════════════════════════════════════════════

/**
 * Biomas dominantes por rango temporal (Ma BP).
 * Simplificación didáctica — solo Africa oriental + zona mediterránea.
 * Ref: deMenocal 2004; Potts 1998 (doi:10.1016/S0047-2484(98)00055-2)
 * @type {Array<{from:number, to:number, biome:string, color:string}>}
 */
const COEX_BIOMES = [
  { from: 0,    to: 0.012, biome: 'Holoceno templado',         color: '#0a6b49' },
  { from: 0.012,to: 0.115, biome: 'Glacial tardío / Dryas',    color: '#4a6a8a' },
  { from: 0.115,to: 0.130, biome: 'Interglaciar Eemiense',      color: '#0a6b49' },
  { from: 0.130,to: 0.780, biome: 'Pleistoceno medio variable', color: '#8a7a3a' },
  { from: 0.780,to: 1.800, biome: 'Sabana pulsada (ciclos 41k)', color: '#c07800' },
  { from: 1.800,to: 2.600, biome: 'Expansión sabana-bosque',    color: '#7a9a3a' },
  { from: 2.600,to: 3.600, biome: 'Bosque / selva africana',    color: '#1a7a4a' },
  { from: 3.600,to: 7.000, biome: 'Bosque cerrado / woodland',  color: '#2a6a2a' },
  { from: 7.000,to:30.000, biome: 'Mioceno – bosque tropical',  color: '#0a4a2a' },
];

/**
 * Retorna el bioma dominante para una edad en Ma BP.
 * @param {number} maBP - Edad en millones de años
 * @returns {{biome:string, color:string}|null}
 */
function getBiomeAtTime(maBP) {
  return COEX_BIOMES.find(b => maBP >= b.from && maBP <= b.to) || null;
}

/**
 * Retorna el estadio MIS que corresponde a una edad en ka BP.
 * Solo cubre el rango del dataset MIS_STAGES.
 * @param {number} kaBP - Edad en miles de años
 * @returns {{warm:boolean, label:string}|null}
 */
function getMISAtTime(kaBP) {
  if (!Array.isArray(MIS_STAGES)) return null;
  return MIS_STAGES.find(m => kaBP >= m.end && kaBP <= m.start) || null;
}

/**
 * Clasifica el nicho ecológico de una especie en una de cuatro categorías.
 * Basado en dieta isotópica (sp.dieta) y tecnología (sp.herramientas).
 * @param {Object} sp - Objeto especie
 * @returns {'herbívoro'|'omnívoro'|'carnívoro'|'desconocido'}
 */
function getEcoNiche(sp) {
  const d = (sp.dieta || '').toLowerCase();
  const h = (sp.herramientas || '').toLowerCase();
  if (/c4|grano|dura|folív|frugív/.test(d))           return 'herbívoro';
  if (/carne|carnív|caza/.test(d))                     return 'carnívoro';
  if (/mixta|omnívor|c3\/c4|c3.c4/.test(d))            return 'omnívoro';
  if (/olduvay|achelense|musteriense|msa|modo [123]/.test(h)) return 'omnívoro'; // Homo con herramientas → omnívoro
  return 'desconocido';
}

/**
 * Evalúa la relación ecológica entre dos especies coexistentes.
 * Lógica simplificada para uso didáctico. Devuelve un array de tags.
 * @param {Object} a - Especie A
 * @param {Object} b - Especie B
 * @returns {Array<{key:string, label:string, css:string, tooltip:string}>}
 */
function getEcoInteraction(a, b) {
  const tags = [];
  const nicheA = getEcoNiche(a);
  const nicheB = getEcoNiche(b);

  // ── Competencia directa: mismo nicho y misma región ──────────────
  if (nicheA !== 'desconocido' && nicheA === nicheB) {
    tags.push({
      key: 'competencia',
      label: 'Competencia potencial',
      css: 'competencia',
      tooltip: `Ambas son ${nicheA}s con dietas similares — posible solapamiento de recursos`
    });
  }

  // ── Partición de nicho: nichos distintos ─────────────────────────
  if (nicheA !== 'desconocido' && nicheB !== 'desconocido' && nicheA !== nicheB) {
    tags.push({
      key: 'particion',
      label: 'Partición de nicho',
      css: 'particion',
      tooltip: `${a.nombre} (${nicheA}) y ${b.nombre} (${nicheB}) explotan recursos distintos`
    });
  }

  // ── Ventaja tecnológica: uno usa herramientas y el otro no ────────
  const hA = (a.herramientas || '').toLowerCase();
  const hB = (b.herramientas || '').toLowerCase();
  const hasToolsA = !/ninguna|no\b|^$/.test(hA);
  const hasToolsB = !/ninguna|no\b|^$/.test(hB);
  if (hasToolsA !== hasToolsB) {
    const toolUser = hasToolsA ? a : b;
    tags.push({
      key: 'tecno-ventaja',
      label: 'Asimetría tecnológica',
      css: 'tecno-ventaja',
      tooltip: `Solo ${toolUser.nombre} tiene evidencia de uso de herramientas — posible ventaja en acceso a recursos`
    });
  }

  // ── Simpatría sin señal de competencia ───────────────────────────
  if (!tags.length) {
    tags.push({
      key: 'simpatria',
      label: 'Simpatría',
      css: 'simpatria',
      tooltip: 'Coexistencia documentada sin señal clara de competencia o partición directa en los datos disponibles'
    });
  }

  return tags;
}

/** Estado del panel de bin activo */
let _coexActiveBin = null;

/**
 * Renderiza la vista de coexistencias con contexto ecológico completo.
 * Estructura:
 *   1. Estadísticas de resumen (ahora incluye pares por tipo de interacción)
 *   2. Tira de contexto ambiental (MIS + bioma del intervalo visible)
 *   3. Heatmap SVG con banda MIS superpuesta
 *   4. Panel de bin seleccionado (lazy, al click)
 *   5. Filtros de interacción + tarjetas de par mejoradas
 */
function renderCoexistenceView() {
  const el = document.getElementById('coexistenceContent');
  if (!el) return;

  // Cache guard — evita re-render en cada pulsación de filtro
  const cacheKey = `${cladoFilter}|${timeFilter.old}|${timeFilter.young}|${document.getElementById('searchInput')?.value||''}`;
  if (cacheKey === _coexCacheKey && el.innerHTML) return;
  _coexCacheKey = cacheKey;
  _coexActiveBin = null;

  const species = DB.filter(matchesActiveFilters);
  if (!species.length) {
    el.innerHTML = '<div class="cmp-status-msg"><strong>Sin taxones visibles</strong>Ajusta los filtros de clado o intervalo temporal para mostrar especies.</div>';
    return;
  }

  const old   = Math.max(timeFilter.old, timeFilter.young);
  const young = Math.min(timeFilter.old, timeFilter.young);
  const step  = 0.1;
  const bins  = [];
  for (let t = old; t > young + 0.0001; t = +(t - step).toFixed(4)) {
    bins.push({ old: +t.toFixed(2), young: +Math.max(young, t - step).toFixed(2) });
  }
  if (!bins.length) bins.push({ old: old + 0.05, young: Math.max(0, young - 0.05) });

  const labelW = 175, cellW = 9, rowH = 19, misH = 10, top = 54;
  const W = labelW + bins.length * cellW + 28;
  const H = top + species.length * rowH + 28;

  // ── Conteo por bin ───────────────────────────────────────────────
  let maxSimul = 0, maxBin = null;
  const binCounts = bins.map(bin => {
    const count = species.filter(sp => speciesOverlapsBin(sp, bin.old, bin.young)).length;
    if (count > maxSimul) { maxSimul = count; maxBin = bin; }
    return count;
  });

  // ── Banda MIS ────────────────────────────────────────────────────
  const misRects = bins.map((bin, bi) => {
    const midKa = (bin.old + bin.young) / 2 * 1000;
    const mis = getMISAtTime(midKa);
    if (!mis) return '';
    const x = labelW + bi * cellW;
    const fill = mis.warm ? '#c07800' : '#3a6a9a';
    return `<rect class="coex-mis-rect" x="${x}" y="${top - misH - 4}" width="${cellW}" height="${misH}" fill="${fill}" title="${escapeHtmlAttr(mis.label)}"/>`;
  }).join('');

  // Etiquetas MIS cada 20 bins
  const misLabels = bins.map((bin, bi) => {
    if (bi % 20 !== 0) return '';
    const midKa = (bin.old + bin.young) / 2 * 1000;
    const mis = getMISAtTime(midKa);
    if (!mis) return '';
    const x = labelW + bi * cellW;
    return `<text class="coex-mis-label" x="${x}" y="${top - misH - 7}">${escapeHtmlAttr(mis.label.split('—')[0].trim())}</text>`;
  }).join('');

  // ── Eje + gráfica de barras de simultaneidad ─────────────────────
  const axis = bins.map((bin, i) => {
    const isMajor = Math.abs(bin.old - Math.round(bin.old)) < 0.0001 || i === 0 || i === bins.length - 1;
    if (!isMajor) return '';
    const x = labelW + i * cellW;
    return `<line x1="${x}" y1="${top - misH - 18}" x2="${x}" y2="${H - 18}" stroke="rgba(90,80,70,0.14)" stroke-width="1"/>
            <text class="coexist-axis" x="${x}" y="${top - misH - 20}" text-anchor="middle">${formatTimePoint(bin.old)}</text>`;
  }).join('');

  const barChart = binCounts.map((count, i) => {
    const x = labelW + i * cellW;
    const h = maxSimul ? (count / maxSimul) * 18 : 0;
    return `<rect x="${x}" y="${top - h - misH - 22}" width="${cellW - 1}" height="${h}" fill="#8a5a00" opacity="0.42" rx="1"/>`;
  }).join('');

  // ── Filas de especies ─────────────────────────────────────────────
  // FIX rendimiento (Claude 2026-06): antes se generaba un <rect>+<title> por
  // CADA celda (especie × bin), incluidas las inactivas (opacity 0.08). Con ~230
  // bins × 50 especies = ~11.500 rects + 11.500 titles (~2,5 MB de SVG) que
  // colgaban la pestaña varios segundos al renderizar. Ahora cada fila pinta UN
  // solo rect de fondo tenue (la rejilla) y solo las celdas ACTIVAS reciben
  // rect+title. El resultado visual es equivalente; los nodos caen de ~11.500 a
  // unos cientos. Las columnas siguen siendo interactivas vía colTriggers.
  const rows = [];
  const gridW = bins.length * cellW;
  species.forEach((sp, ri) => {
    const y = top + ri * rowH;
    const color = CLADE_COLORS[sp.clado] || '#888';
    rows.push(`<text class="coexist-row-label" x="${labelW - 8}" y="${y + 13}" text-anchor="end" data-id="${escapeHtmlAttr(sp.id)}">${escapeHtmlAttr(shortTaxonName(sp.nombre))}</text>`);
    // fondo tenue de toda la fila (sustituye a las ~230 celdas inactivas)
    rows.push(`<rect class="coexist-row-bg" x="${labelW}" y="${y}" width="${gridW}" height="${rowH - 2}" rx="2" fill="#ddd4c9" opacity="0.1"/>`);
    bins.forEach((bin, bi) => {
      if (!speciesOverlapsBin(sp, bin.old, bin.young)) return; // solo celdas activas
      const x = labelW + bi * cellW;
      rows.push(`<rect class="coexist-cell active"
        x="${x}" y="${y}" width="${cellW - 1}" height="${rowH - 2}" rx="2"
        fill="${color}" opacity="0.82"
        data-coex-bin="${bi}" data-coex-active="1">
        <title>${escapeHtmlAttr(sp.nombre)} · ${formatTimePoint(bin.young)}-${formatTimePoint(bin.old)}</title>
      </rect>`);
    });
  });

  // Línea de click en columna del SVG (columnas interactivas)
  const colTriggers = bins.map((bin, bi) => {
    const x = labelW + bi * cellW;
    return `<rect x="${x}" y="${top}" width="${cellW}" height="${species.length * rowH}"
      fill="transparent" style="cursor:pointer"
      data-coex-col="${bi}" data-bin-old="${bin.old}" data-bin-young="${bin.young}"
      aria-label="Intervalo ${formatTimePoint(bin.young)}-${formatTimePoint(bin.old)}"/>`;
  }).join('');

  // ── Leyenda MIS ───────────────────────────────────────────────────
  const misLegend = bins.length <= 500 ? `
    <div class="coex-eco-strip" aria-label="Contexto climático del intervalo mostrado">
      <span class="coex-eco-pill biome">Banda superior:</span>
      <span class="coex-eco-pill warm">🌡 Cálido (MIS impar)</span>
      <span class="coex-eco-pill cold">❄ Frío (MIS par)</span>
      <span class="coex-eco-pill biome">📍 ${escapeHtmlText(getBiomeAtTime((old + young) / 2)?.biome || 'Bioma variable')}</span>
    </div>` : '';

  // ── Pares ecológicos ──────────────────────────────────────────────
  const pairs = [];
  for (let i = 0; i < species.length; i++) {
    for (let j = i + 1; j < species.length; j++) {
      const overlap = speciesTemporalOverlap(species[i], species[j]);
      const region  = overlap ? shareRegion(species[i], species[j]) : null;
      if (overlap && region) {
        const interactions = getEcoInteraction(species[i], species[j]);
        pairs.push({ a: species[i], b: species[j], overlap, region, interactions });
      }
    }
  }
  pairs.sort((x, y) => y.overlap.duration - x.overlap.duration || (y.a.clado === 'homo') - (x.a.clado === 'homo'));

  // Contar por tipo de interacción
  const interactionCounts = { competencia: 0, particion: 0, simpatria: 0, 'tecno-ventaja': 0 };
  pairs.forEach(p => p.interactions.forEach(t => { if (t.key in interactionCounts) interactionCounts[t.key]++; }));

  // ── HTML de tarjetas de par ───────────────────────────────────────
  const pairCards = pairs.slice(0, 24).map(p => {
    const tagsHtml = p.interactions.map(t =>
      `<span class="coex-eco-tag ${escapeHtmlAttr(t.css)}" title="${escapeHtmlAttr(t.tooltip)}">${escapeHtmlText(t.label)}</span>`
    ).join('');
    return `<article class="coex-pair-v2" data-coex-itype="${escapeHtmlAttr(p.interactions[0]?.key || 'simpatria')}">
      <div class="cpv2-names">${escapeHtmlText(shortTaxonName(p.a.nombre))} + ${escapeHtmlText(shortTaxonName(p.b.nombre))}</div>
      <div class="cpv2-meta">📍 ${escapeHtmlText(p.region)} · ⏱ ${formatTimePoint(p.overlap.young)}–${formatTimePoint(p.overlap.old)}</div>
      <div class="cpv2-eco">${tagsHtml}</div>
    </article>`;
  }).join('');

  // ── Filtros de interacción ────────────────────────────────────────
  const filterBtns = [
    { key: 'all',         label: `Todos (${pairs.length})` },
    { key: 'competencia', label: `Competencia (${interactionCounts.competencia})` },
    { key: 'particion',   label: `Partición (${interactionCounts.particion})` },
    { key: 'tecno-ventaja',label:`Asimetría tecnol. (${interactionCounts['tecno-ventaja']})` },
    { key: 'simpatria',   label: `Simpatría (${interactionCounts.simpatria})` },
  ].map(f => `<button type="button" class="coex-itype-btn${f.key === 'all' ? ' active' : ''}"
    data-coex-filter="${escapeHtmlAttr(f.key)}" aria-pressed="${f.key === 'all'}">${escapeHtmlText(f.label)}</button>`).join('');

  // ── Ensamblado final ──────────────────────────────────────────────
  el.innerHTML = `
    <div class="coexist-summary">
      <div class="coexist-stat"><strong>${species.length}</strong><span>taxones visibles</span></div>
      <div class="coexist-stat"><strong>${bins.length}</strong><span>intervalos de 100 ka</span></div>
      <div class="coexist-stat"><strong>${maxSimul}</strong><span>máximo simultáneo${maxBin ? ` en ${formatTimePoint(maxBin.young)}–${formatTimePoint(maxBin.old)}` : ''}</span></div>
      <div class="coexist-stat"><strong>${pairs.length}</strong><span>pares con coexistencia</span></div>
      <div class="coexist-stat"><strong>${interactionCounts.competencia}</strong><span>pares con competencia potencial</span></div>
      <div class="coexist-stat"><strong>${interactionCounts.particion}</strong><span>pares con partición de nicho</span></div>
    </div>

    ${misLegend}

    <div class="coexist-scroll" role="region" aria-label="Heatmap de coexistencias con banda climática MIS">
      <svg class="coexist-svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}"
           role="img" aria-label="Matriz de coexistencias con estadios marinos isotópicos (MIS)">
        ${axis}
        ${barChart}
        ${misRects}
        ${misLabels}
        ${rows.join('')}
        ${colTriggers}
      </svg>
    </div>

    <!-- Panel de bin seleccionado (lazy) -->
    <div id="coexBinPanel" class="coex-bin-panel" aria-live="polite" aria-label="Detalle del intervalo seleccionado"></div>

    <div class="coexist-summary" style="margin-top:10px">
      <div class="coexist-stat" style="background:#fdecea;border-color:#e8c0be">
        <strong style="color:#aa1f1f">${interactionCounts.competencia}</strong>
        <span>Competencia potencial</span>
      </div>
      <div class="coexist-stat" style="background:#e8f8f1;border-color:#b0e4ce">
        <strong style="color:#0a6b49">${interactionCounts.particion}</strong>
        <span>Partición de nicho</span>
      </div>
      <div class="coexist-stat" style="background:#fdf3e0;border-color:#e8d8b0">
        <strong style="color:#7a4200">${interactionCounts['tecno-ventaja']}</strong>
        <span>Asimetría tecnológica</span>
      </div>
      <div class="coexist-stat" style="background:#e8edf8;border-color:#b0c0e0">
        <strong style="color:#1a4fa0">${interactionCounts.simpatria}</strong>
        <span>Simpatría</span>
      </div>
    </div>

    <details class="coex-eco-legend" style="margin:8px 0;padding:10px 14px;background:#faf9f7;border:1px solid var(--border);border-radius:10px;font-size:0.8rem;color:var(--text-sec)">
      <summary style="font-weight:700;color:var(--primary);cursor:pointer">📖 Glosario de categorías ecológicas</summary>
      <ul style="margin:8px 0 0;padding-left:18px;line-height:1.7">
        <li><strong>Competencia potencial</strong>: dos especies con el mismo nicho trófico (herbívoro/omnívoro/carnívoro) y solapamiento regional — inferencia didáctica simplificada [PROVISIONAL]</li>
        <li><strong>Partición de nicho</strong>: nichos tróficos distintos — menor presión de competencia directa</li>
        <li><strong>Asimetría tecnológica</strong>: solo una de las dos especies tiene evidencia de herramientas — posible diferencial de acceso a recursos</li>
        <li><strong>Simpatría</strong>: coexistencia documentada sin datos suficientes para asignar otro tipo de interacción</li>
        <li><em>Nota: las categorías son didácticas y simplificadas. La competencia real entre linajes homíninos es un debate abierto. Consulta los debates activos para bibliografía especializada.</em></li>
      </ul>
    </details>

    <div style="margin:10px 0 6px;font-size:0.72rem;font-weight:800;text-transform:uppercase;letter-spacing:0.07em;color:var(--text-hint);font-family:var(--font-mono)">
      Filtrar pares por tipo de interacción:
    </div>
    <div class="coex-itype-filters" role="group" aria-label="Filtros de tipo de interacción ecológica">
      ${filterBtns}
    </div>
    <div class="coexist-pairs" id="coexPairGrid">
      ${pairCards || '<div class="cmp-status-msg">No se detectan pares con solapamiento en el filtro actual.</div>'}
    </div>
  `;

  // ── Event listeners locales ───────────────────────────────────────

  // Click en labels de especie → ficha
  el.querySelectorAll('.coexist-row-label').forEach(label => {
    label.addEventListener('click', () => {
      const sp = DB_INDEX[label.dataset.id];
      if (sp) showDetail(sp);
    });
  });

  // Click en columna del SVG → panel de bin
  el.querySelectorAll('[data-coex-col]').forEach(rect => {
    rect.addEventListener('click', () => {
      const bi   = parseInt(rect.dataset.coexCol);
      const binO = parseFloat(rect.dataset.binOld);
      const binY = parseFloat(rect.dataset.binYoung);
      _showCoexBinPanel(bi, binO, binY, species, bins);
    });
  });

  // Filtros de interacción
  el.querySelectorAll('[data-coex-filter]').forEach(btn => {
    btn.addEventListener('click', () => {
      el.querySelectorAll('[data-coex-filter]').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const key = btn.dataset.coexFilter;
      el.querySelectorAll('[data-coex-itype]').forEach(card => {
        card.style.display = (key === 'all' || card.dataset.coexItype === key) ? '' : 'none';
      });
    });
  });
}

/**
 * Muestra el panel lateral de detalle para un bin (intervalo temporal) seleccionado.
 * Incluye: taxones presentes, contexto climático MIS, bioma dominante.
 * @param {number} bi        - Índice del bin
 * @param {number} binOld    - Límite superior del bin en Ma
 * @param {number} binYoung  - Límite inferior del bin en Ma
 * @param {Array}  species   - Array de especies visibles
 * @param {Array}  bins      - Array de bins
 */
function _showCoexBinPanel(bi, binOld, binYoung, species, bins) {
  const panel = document.getElementById('coexBinPanel');
  if (!panel) return;

  const present = species.filter(sp => speciesOverlapsBin(sp, binOld, binYoung));
  const midKa   = (binOld + binYoung) / 2 * 1000;
  const midMa   = (binOld + binYoung) / 2;
  const mis     = getMISAtTime(midKa);
  const biome   = getBiomeAtTime(midMa);

  // Contexto de clima y evento
  const climaEvent = Array.isArray(CLIMA_EVENTS)
    ? CLIMA_EVENTS.find(ev => Math.abs(ev.ka - midKa) < 100)
    : null;

  // Pares presentes en este bin
  const binPairs = [];
  for (let i = 0; i < present.length; i++) {
    for (let j = i + 1; j < present.length; j++) {
      const region = shareRegion(present[i], present[j]);
      if (region) {
        binPairs.push({
          a: present[i], b: present[j], region,
          interactions: getEcoInteraction(present[i], present[j])
        });
      }
    }
  }

  panel.innerHTML = `
    <h4>
      🕐 Intervalo ${formatTimePoint(binYoung)}–${formatTimePoint(binOld)}
      <span style="font-size:0.72rem;font-weight:400;color:var(--text-hint);font-family:var(--font-mono)">
        ${present.length} taxón(es) presente(s)
      </span>
    </h4>

    <div class="coex-eco-strip">
      ${mis
        ? `<span class="coex-eco-pill ${mis.warm ? 'warm' : 'cold'}">${mis.warm ? '🌡' : '❄'} ${escapeHtmlText(mis.label)}</span>`
        : ''}
      ${biome
        ? `<span class="coex-eco-pill biome">🌿 ${escapeHtmlText(biome.biome)}</span>`
        : ''}
      ${climaEvent
        ? `<span class="coex-eco-pill event">⚡ ${escapeHtmlText(climaEvent.label)}</span>`
        : ''}
    </div>

    ${present.length
      ? `<div class="coex-bin-species-grid">
          ${present.map(sp => `
            <div class="coex-bin-sp" style="border-left-color:${CLADE_COLORS[sp.clado] || '#888'}"
                 data-open-species="${escapeHtmlAttr(sp.id)}" role="button" tabindex="0"
                 aria-label="Abrir ficha de ${escapeHtmlAttr(sp.nombre)}">
              <strong>${escapeHtmlText(shortTaxonName(sp.nombre))}</strong>
              <span>${escapeHtmlText(sp.dieta || '—')} · ${escapeHtmlText(sp.herramientas || '—')}</span>
            </div>`).join('')}
        </div>`
      : '<p style="color:var(--text-hint);font-size:0.82rem">Sin taxones en este intervalo.</p>'}

    ${binPairs.length
      ? `<div style="margin-top:8px;font-size:0.72rem;font-weight:800;text-transform:uppercase;
                    letter-spacing:0.06em;color:var(--text-hint);font-family:var(--font-mono)">
           Pares en este intervalo (${binPairs.length})
         </div>
         <div class="coexist-pairs" style="margin-top:6px">
           ${binPairs.slice(0, 6).map(p => `
             <article class="coex-pair-v2">
               <div class="cpv2-names">${escapeHtmlText(shortTaxonName(p.a.nombre))} + ${escapeHtmlText(shortTaxonName(p.b.nombre))}</div>
               <div class="cpv2-meta">📍 ${escapeHtmlText(p.region)}</div>
               <div class="cpv2-eco">
                 ${p.interactions.map(t => `<span class="coex-eco-tag ${escapeHtmlAttr(t.css)}" title="${escapeHtmlAttr(t.tooltip)}">${escapeHtmlText(t.label)}</span>`).join('')}
               </div>
             </article>`).join('')}
         </div>`
      : ''}
  `;

  panel.classList.add('visible');
  panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

